--
-- Name: admin_adjust_membership_period("uuid", "uuid", "uuid", "text", integer, timestamp with time zone, timestamp with time zone, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_adjust_membership_period"("p_actor_id" "uuid", "p_user_id" "uuid", "p_subscription_id" "uuid", "p_operation" "text", "p_days" integer, "p_ends_at" timestamp with time zone, "p_expected_ends_at" timestamp with time zone, "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("subscription_id" "uuid", "plan_code" "public"."nb_membership_plan", "status" "text", "starts_at" timestamp with time zone, "previous_ends_at" timestamp with time zone, "ends_at" timestamp with time zone, "operation" "text", "delta_days" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_subscription public.membership_subscriptions%rowtype;
  v_existing_audit public.admin_audit_events%rowtype;
  v_now timestamptz := now();
  v_target_ends_at timestamptz;
  v_status text;
  v_metadata jsonb;
begin
  if p_actor_id is null or p_user_id is null or p_subscription_id is null then
    raise exception 'MEMBERSHIP_ADJUSTMENT_TARGET_REQUIRED' using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'MEMBERSHIP_ADJUSTMENT_REASON_REQUIRED' using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.users u
    join public.admin_user_roles aur
      on aur.user_id = u.id
     and aur.role_code = 'super_admin'
     and aur.is_active = true
     and aur.revoked_at is null
    join public.admin_roles ar
      on ar.code = aur.role_code
     and ar.is_active = true
    where u.id = p_actor_id
      and u.admin_status = 'active'
  ) then
    raise exception 'ADMIN_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  select *
  into v_subscription
  from public.membership_subscriptions ms
  where ms.id = p_subscription_id
    and ms.user_id = p_user_id
  for update;

  if not found then
    raise exception 'MEMBERSHIP_NOT_FOUND' using errcode = 'P0002';
  end if;

  select *
  into v_existing_audit
  from public.admin_audit_events aae
  where aae.action = 'admin_adjust_membership_period'
    and aae.idempotency_key = btrim(p_idempotency_key)
  limit 1;

  if found then
    if v_existing_audit.target_id <> p_subscription_id::text then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode = '23505';
    end if;

    return query select
      p_subscription_id,
      (v_existing_audit.metadata ->> 'plan_code')::public.nb_membership_plan,
      v_existing_audit.metadata ->> 'status',
      nullif(v_existing_audit.metadata ->> 'starts_at', '')::timestamptz,
      nullif(v_existing_audit.metadata ->> 'previous_ends_at', '')::timestamptz,
      nullif(v_existing_audit.metadata ->> 'ends_at', '')::timestamptz,
      v_existing_audit.metadata ->> 'operation',
      nullif(v_existing_audit.metadata ->> 'delta_days', '')::integer;
    return;
  end if;

  if v_subscription.source <> 'manual'
    or v_subscription.status not in ('trialing', 'active')
    or v_subscription.starts_at > v_now
    or (v_subscription.ends_at is not null and v_subscription.ends_at <= v_now) then
    raise exception 'MEMBERSHIP_ADJUSTMENT_NOT_MANUAL_CURRENT' using errcode = '22023';
  end if;

  if v_subscription.ends_at is distinct from p_expected_ends_at then
    raise exception 'MEMBERSHIP_PERIOD_STALE' using errcode = '40001';
  end if;

  if p_operation not in ('add_days', 'subtract_days', 'set_end_at') then
    raise exception 'MEMBERSHIP_ADJUSTMENT_OPERATION_INVALID' using errcode = '22023';
  end if;

  if p_operation in ('add_days', 'subtract_days') then
    if p_days is null or p_days <= 0 or p_ends_at is not null then
      raise exception 'MEMBERSHIP_ADJUSTMENT_DAYS_INVALID' using errcode = '22023';
    end if;
    if v_subscription.ends_at is null then
      raise exception 'MEMBERSHIP_ADJUSTMENT_PERMANENT_REQUIRES_END_DATE'
        using errcode = '22023';
    end if;

    v_target_ends_at := case p_operation
      when 'add_days' then v_subscription.ends_at + make_interval(days => p_days)
      else v_subscription.ends_at - make_interval(days => p_days)
    end;
  else
    if p_ends_at is null or p_days is not null then
      raise exception 'MEMBERSHIP_ADJUSTMENT_END_DATE_INVALID' using errcode = '22023';
    end if;
    v_target_ends_at := p_ends_at;
  end if;

  if v_target_ends_at <= v_subscription.starts_at then
    raise exception 'MEMBERSHIP_ADJUSTMENT_PERIOD_INVALID' using errcode = '22023';
  end if;

  v_status := case
    when v_target_ends_at <= v_now then 'expired'
    else v_subscription.status
  end;

  update public.membership_subscriptions
  set
    status = v_status,
    ends_at = v_target_ends_at,
    current_period_end = v_target_ends_at,
    updated_at = now()
  where id = v_subscription.id;

  v_metadata := jsonb_build_object(
    'subscription_id', v_subscription.id,
    'plan_code', v_subscription.plan_code,
    'status', v_status,
    'starts_at', v_subscription.starts_at,
    'previous_ends_at', v_subscription.ends_at,
    'ends_at', v_target_ends_at,
    'operation', p_operation,
    'delta_days', p_days,
    'source', v_subscription.source
  );

  insert into public.admin_audit_events (
    actor_id,
    action,
    target_type,
    target_id,
    reason,
    idempotency_key,
    metadata
  )
  values (
    p_actor_id,
    'admin_adjust_membership_period',
    'membership_subscription',
    v_subscription.id::text,
    btrim(p_reason),
    btrim(p_idempotency_key),
    v_metadata
  );

  return query select
    v_subscription.id,
    v_subscription.plan_code,
    v_status,
    v_subscription.starts_at,
    v_subscription.ends_at,
    v_target_ends_at,
    p_operation,
    p_days;
end;
$$;


--
-- Name: admin_adjust_sale_points("uuid", integer, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_adjust_sale_points"("p_sale_user_id" "uuid", "p_point_delta_cents" integer, "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_adjustment_id uuid;
begin
  perform public.admin_assert_permission('points.write');

  if p_point_delta_cents is null or p_point_delta_cents = 0 then
    raise exception 'INVALID_POINT_ADJUSTMENT' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.sale_profiles
    where user_id = p_sale_user_id
  ) then
    raise exception 'SALE_PROFILE_NOT_FOUND' using errcode = '22023';
  end if;

  insert into public.sale_point_adjustments (
    sale_user_id,
    point_delta_cents,
    reason,
    reviewed_by,
    idempotency_key,
    metadata
  )
  values (
    p_sale_user_id,
    p_point_delta_cents,
    btrim(p_reason),
    auth.uid(),
    nullif(btrim(p_idempotency_key), ''),
    jsonb_build_object('approval_count_required', 1)
  )
  on conflict (idempotency_key) do update
  set metadata = public.sale_point_adjustments.metadata
  returning id into v_adjustment_id;

  perform public.admin_write_audit(
    'admin_adjust_sale_points',
    'sale_point_adjustment',
    v_adjustment_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'sale_user_id',
      p_sale_user_id,
      'point_delta_cents',
      p_point_delta_cents,
      'approval_count_required',
      1
    )
  );

  return query select true, 'Da ghi dieu chinh diem Sale.';
end;
$$;


--
-- Name: admin_assert_payment_reviewer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_assert_payment_reviewer"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if not public.admin_has_payment_reviewer_role() then
    raise exception 'PAYMENT_REVIEWER_ROLE_REQUIRED' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: admin_assert_permission("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_assert_permission"("p_permission" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if not public.admin_has_permission(p_permission) then
    raise exception 'ADMIN_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: admin_cancel_reward_redemption("uuid", "text", boolean, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_cancel_reward_redemption"("p_redemption_id" "uuid", "p_reason" "text", "p_external_revocation_confirmed" boolean, "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_redemption public.wellness_reward_redemptions%rowtype;
  v_code public.wellness_reward_codes%rowtype;
  v_existing_audit public.admin_audit_events%rowtype;
  v_program record;
  v_subject_id uuid;
  v_ledger_id uuid := gen_random_uuid();
  v_allocation public.wellness_point_allocations%rowtype;
  v_allocation_id uuid := gen_random_uuid();
  v_wallet public.wellness_reward_wallets%rowtype;
begin
  perform public.admin_assert_permission('wellness_rewards.write');

  if p_redemption_id is null then
    raise exception using errcode = 'P0001', message = 'redemption_required';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'admin_reason_required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;
  if not coalesce(p_external_revocation_confirmed, false) then
    raise exception using errcode = 'P0001', message = 'external_revocation_confirmation_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:admin:cancel:' || btrim(p_idempotency_key),
    0
  ));

  select * into v_existing_audit
  from public.admin_audit_events aae
  where aae.action = 'admin_cancel_reward_redemption'
    and aae.idempotency_key = btrim(p_idempotency_key);

  if v_existing_audit.id is not null then
    if v_existing_audit.target_id <> p_redemption_id::text then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    return jsonb_build_object(
      'success', true,
      'message', 'Giao dịch đã được hủy trước đó.',
      'redemption_id', p_redemption_id,
      'accepted_count', 0,
      'duplicate_count', 0,
      'rejected_count', 0,
      'idempotent_replay', true
    );
  end if;

  select * into v_redemption
  from public.wellness_reward_redemptions wrr
  where wrr.id = p_redemption_id
  for update;

  if v_redemption.id is null then
    raise exception using errcode = 'P0001', message = 'redemption_not_found';
  end if;

  if v_redemption.status = 'cancelled' then
    perform public.admin_write_audit(
      'admin_cancel_reward_redemption',
      'wellness_reward_redemption',
      v_redemption.id::text,
      p_reason,
      p_idempotency_key,
      jsonb_build_object(
        'already_cancelled', true,
        'refund_created', false,
        'external_revocation_confirmed', true
      )
    );
    return jsonb_build_object(
      'success', true,
      'message', 'Giao dịch đã ở trạng thái hủy.',
      'redemption_id', v_redemption.id,
      'accepted_count', 0,
      'duplicate_count', 0,
      'rejected_count', 0,
      'idempotent_replay', true
    );
  end if;

  select * into v_code
  from public.wellness_reward_codes wrc
  where wrc.id = v_redemption.reward_code_id
  for update;

  select hs.id into v_subject_id
  from public.health_subjects hs
  where hs.owner_user_id = v_redemption.user_id
    and hs.subject_type = 'self'
    and hs.is_active = true
  limit 1;

  if v_subject_id is null then
    raise exception using errcode = 'P0001', message = 'health_subject_required';
  end if;

  select * into v_program
  from public.current_wellness_reward_program();

  perform public.refresh_wellness_reward_wallet(v_redemption.user_id);
  select * into v_wallet
  from public.wellness_reward_wallets
  where user_id = v_redemption.user_id
  for update;

  insert into public.wellness_point_ledgers (
    id,
    user_id,
    subject_id,
    source_type,
    source_id,
    schedule_date,
    points_delta,
    program_code,
    idempotency_key,
    event_type,
    status,
    title,
    is_redeemable,
    available_at,
    expires_at,
    program_config_id,
    redemption_id,
    metadata
  )
  values (
    v_ledger_id,
    v_redemption.user_id,
    v_subject_id,
    'reward_redemption_refund',
    v_redemption.id,
    (now() at time zone 'Asia/Ho_Chi_Minh')::date,
    v_redemption.points_spent,
    v_program.contract_version,
    'reward_refund:' || v_redemption.id::text,
    'refund',
    'refunded',
    'Hoàn điểm ưu đãi: ' || v_redemption.offer_title_snapshot,
    true,
    now(),
    now() + make_interval(days => v_program.expiry_days),
    v_program.program_config_id,
    v_redemption.id,
    jsonb_build_object(
      'cancelled_by', auth.uid(),
      'external_revocation_confirmed', true
    )
  );

  insert into public.wellness_point_allocations (
    id,
    user_id,
    subject_id,
    ledger_id,
    source_type,
    source_id,
    original_points,
    remaining_points,
    status,
    available_at,
    expires_at,
    program_config_id
  )
  values (
    v_allocation_id,
    v_redemption.user_id,
    v_subject_id,
    v_ledger_id,
    'admin_refund',
    v_redemption.id,
    v_redemption.points_spent,
    v_redemption.points_spent,
    'available',
    now(),
    now() + make_interval(days => v_program.expiry_days),
    v_program.program_config_id
  )
  returning * into v_allocation;

  update public.wellness_reward_wallets
  set
    available_points = available_points + v_redemption.points_spent,
    lifetime_refunded_points = lifetime_refunded_points + v_redemption.points_spent,
    lock_version = lock_version + 1,
    updated_at = now()
  where user_id = v_redemption.user_id
  returning * into v_wallet;

  update public.wellness_reward_codes
  set
    status = 'retired',
    retired_at = now()
  where id = v_code.id;

  update public.wellness_reward_redemptions
  set
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = auth.uid(),
    cancellation_reason = btrim(p_reason),
    refund_allocation_id = v_allocation.id,
    updated_at = now()
  where id = v_redemption.id;

  perform public.admin_write_audit(
    'admin_cancel_reward_redemption',
    'wellness_reward_redemption',
    v_redemption.id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'external_revocation_confirmed', true,
      'code_restocked', false,
      'refund_points', v_redemption.points_spent,
      'refund_allocation_id', v_allocation.id,
      'refund_expires_at', v_allocation.expires_at
    )
  );

  return jsonb_build_object(
    'success', true,
    'message', 'Đã hủy giao dịch và hoàn Điểm chăm sóc.',
    'redemption_id', v_redemption.id,
    'refund_points', v_redemption.points_spent,
    'available_points', v_wallet.available_points,
    'accepted_count', 1,
    'duplicate_count', 0,
    'rejected_count', 0,
    'idempotent_replay', false
  );
end;
$$;


--
-- Name: admin_create_reconciliation_run("text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_create_reconciliation_run"("p_scope" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_run_id uuid;
begin
  perform public.admin_assert_permission('reconciliation.write');

  insert into public.admin_reconciliation_runs (
    scope,
    status,
    reason,
    created_by,
    idempotency_key
  )
  values (
    coalesce(nullif(btrim(p_scope), ''), 'payments'),
    'open',
    btrim(p_reason),
    auth.uid(),
    nullif(btrim(p_idempotency_key), '')
  )
  on conflict (idempotency_key) do update
  set metadata = public.admin_reconciliation_runs.metadata
  returning id into v_run_id;

  insert into public.admin_reconciliation_discrepancies (
    run_id,
    target_type,
    target_id,
    severity,
    status,
    summary,
    metadata
  )
  select
    v_run_id,
    'payment_event',
    pe.id::text,
    'high',
    'open',
    'Payment da duyet nhung chua co subscription lien ket.',
    jsonb_build_object('payment_event_id', pe.id, 'plan_code', pe.plan_code)
  from public.payment_events pe
  where pe.status = 'succeeded'
    and pe.subscription_id is null
  on conflict do nothing;

  perform public.admin_write_audit(
    'admin_create_reconciliation_run',
    'admin_reconciliation_run',
    v_run_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object('scope', p_scope)
  );

  return query select true, 'Da tao phien doi soat.';
end;
$$;


