--
-- Name: admin_list_payments("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_list_payments"("p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "text", "title" "text", "subtitle" "text", "status" "text", "section" "text", "created_at" timestamp with time zone, "transfer_reference" "text", "transfer_memo" "text", "payer_full_name" "text", "plan_code" "text", "billing_cycle" "text", "amount_cents" integer, "currency" "text", "transfer_confirmed_at" timestamp with time zone, "review_reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.admin_assert_payment_reviewer();

  return query
  select
    pe.id::text,
    concat(
      pe.plan_code::text,
      ' - ',
      coalesce(nullif(pe.metadata ->> 'billing_cycle', ''), 'unknown'),
      ' - ',
      pe.amount_cents::text,
      ' ',
      pe.currency
    ),
    concat_ws(
      ' - ',
      coalesce(
        nullif(pe.metadata ->> 'payer_full_name', ''),
        nullif(u.full_name, ''),
        u.email,
        pe.payer_user_id::text
      ),
      pe.provider,
      pe.transfer_reference
    ),
    pe.status,
    'payments',
    pe.created_at,
    pe.transfer_reference,
    pe.transfer_memo,
    coalesce(
      nullif(pe.metadata ->> 'payer_full_name', ''),
      nullif(u.full_name, ''),
      u.email,
      pe.payer_user_id::text
    ),
    pe.plan_code::text,
    nullif(pe.metadata ->> 'billing_cycle', ''),
    pe.amount_cents,
    pe.currency,
    nullif(pe.metadata ->> 'transfer_confirmed_at', '')::timestamptz,
    nullif(pe.review_reason, '')
  from public.payment_events pe
  join public.users u on u.id = pe.payer_user_id
  where coalesce(p_query, '') = ''
     or u.email ilike '%' || p_query || '%'
     or u.full_name ilike '%' || p_query || '%'
     or pe.provider_event_id ilike '%' || p_query || '%'
     or pe.transfer_reference ilike '%' || p_query || '%'
     or pe.transfer_memo ilike '%' || p_query || '%'
     or coalesce(pe.metadata ->> 'payer_full_name', '') ilike '%' || p_query || '%'
  order by
    case
      when pe.status = 'pending_review' then 0
      when pe.status = 'pending' then 1
      else 2
    end,
    pe.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
end;
$$;


