--
-- Name: admin_list_sale_point_conversions("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_list_sale_point_conversions"("p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "text", "title" "text", "subtitle" "text", "status" "text", "section" "text", "created_at" timestamp with time zone, "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.admin_assert_permission('sales.write');

  return query
  select
    spc.id::text,
    concat(coalesce(nullif(u.full_name, ''), u.email, spc.sale_user_id::text), ' - ', spc.requested_point_cents::text, ' diem'),
    concat_ws(' - ', spc.money_amount_cents::text || ' ' || spc.currency, spc.review_reason),
    spc.status,
    'sale_point_conversions',
    spc.created_at,
    jsonb_build_object(
      'sale_user_id',
      spc.sale_user_id,
      'requested_point_cents',
      spc.requested_point_cents,
      'money_amount_cents',
      spc.money_amount_cents,
      'currency',
      spc.currency,
      'citizen_id',
      coalesce(spc.metadata ->> 'citizen_id', spp.citizen_id),
      'bank_bin',
      coalesce(spc.metadata ->> 'bank_bin', spp.bank_bin),
      'bank_name',
      coalesce(spc.metadata ->> 'bank_name', spp.bank_name),
      'bank_account_number',
      coalesce(spc.metadata ->> 'bank_account_number', spp.bank_account_number),
      'bank_account_name',
      coalesce(spc.metadata ->> 'bank_account_name', spp.bank_account_name),
      'payment_content',
      coalesce(spc.metadata ->> 'payment_content', concat('SALE ', substr(spc.id::text, 1, 8))),
      'payment_proof_path',
      spc.metadata ->> 'payment_proof_path',
      'vietqr_payload',
      concat_ws(
        '|',
        'VIETQR',
        coalesce(spc.metadata ->> 'bank_bin', spp.bank_bin),
        coalesce(spc.metadata ->> 'bank_account_number', spp.bank_account_number),
        coalesce(spc.metadata ->> 'bank_account_name', spp.bank_account_name),
        spc.money_amount_cents::text,
        spc.currency,
        coalesce(spc.metadata ->> 'payment_content', concat('SALE ', substr(spc.id::text, 1, 8)))
      )
    )
  from public.sale_point_conversions spc
  join public.users u on u.id = spc.sale_user_id
  left join public.sale_payout_profiles spp on spp.sale_user_id = spc.sale_user_id
  where coalesce(p_query, '') = ''
     or u.email ilike '%' || p_query || '%'
     or u.full_name ilike '%' || p_query || '%'
     or spc.id::text = p_query
  order by spc.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
end;
$$;


--
-- Name: admin_list_sales("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_list_sales"("p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "text", "title" "text", "subtitle" "text", "status" "text", "section" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.admin_assert_permission('sales.write');

  return query
  select
    sp.user_id::text,
    coalesce(nullif(u.full_name, ''), nullif(u.email, ''), sp.user_id::text),
    concat_ws(' - ', u.email, rc.code),
    sp.status::text,
    'sales',
    sp.created_at
  from public.sale_profiles sp
  join public.users u on u.id = sp.user_id
  left join public.referral_codes rc
    on rc.sale_user_id = sp.user_id
   and rc.status = 'active'
  where coalesce(p_query, '') = ''
     or u.email ilike '%' || p_query || '%'
     or u.full_name ilike '%' || p_query || '%'
     or rc.code ilike '%' || p_query || '%'
  order by sp.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
end;
$$;


--
-- Name: admin_list_wellness_rewards("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_list_wellness_rewards"("p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 100) RETURNS TABLE("item_type" "text", "id" "uuid", "offer_id" "uuid", "redemption_id" "uuid", "title" "text", "description" "text", "provider_name" "text", "cost_points" integer, "points_spent" integer, "status" "text", "is_active" boolean, "eligible_plan_codes" "text"[], "available_from" timestamp with time zone, "available_until" timestamp with time zone, "voucher_expires_at" timestamp with time zone, "available_codes" integer, "issued_codes" integer, "retired_codes" integer, "user_id" "uuid", "user_label" "text", "masked_code" "text", "created_at" timestamp with time zone, "cancelled_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.admin_assert_permission('wellness_rewards.read');

  return query
  with offer_rows as (
    select
      'offer'::text as item_type,
      wro.id,
      wro.id as offer_id,
      null::uuid as redemption_id,
      wro.title,
      wro.description,
      wro.provider_name,
      wro.cost_points,
      null::integer as points_spent,
      case when wro.is_active then 'active' else 'inactive' end::text as status,
      wro.is_active,
      wro.eligible_plan_codes,
      wro.available_from,
      wro.available_until,
      wro.voucher_expires_at,
      count(wrc.id) filter (
        where wrc.status = 'available'
          and coalesce(wrc.voucher_expires_at, wro.voucher_expires_at) > now()
      )::integer as available_codes,
      count(wrc.id) filter (where wrc.status = 'issued')::integer as issued_codes,
      count(wrc.id) filter (where wrc.status = 'retired')::integer as retired_codes,
      null::uuid as user_id,
      null::text as user_label,
      null::text as masked_code,
      wro.created_at,
      null::timestamptz as cancelled_at,
      wro.updated_at as sort_at
    from public.wellness_reward_offers wro
    left join public.wellness_reward_codes wrc on wrc.offer_id = wro.id
    where coalesce(btrim(p_query), '') = ''
       or wro.title ilike '%' || btrim(p_query) || '%'
       or wro.provider_name ilike '%' || btrim(p_query) || '%'
       or wro.offer_code ilike '%' || btrim(p_query) || '%'
    group by wro.id
  ),
  redemption_rows as (
    select
      'redemption'::text as item_type,
      wrr.id,
      wrr.offer_id,
      wrr.id as redemption_id,
      wrr.offer_title_snapshot as title,
      ''::text as description,
      wrr.provider_name_snapshot as provider_name,
      null::integer as cost_points,
      wrr.points_spent,
      wrr.status,
      true as is_active,
      array[]::text[] as eligible_plan_codes,
      null::timestamptz as available_from,
      null::timestamptz as available_until,
      wrr.voucher_expires_at,
      null::integer as available_codes,
      null::integer as issued_codes,
      null::integer as retired_codes,
      wrr.user_id,
      coalesce(
        nullif(u.full_name, ''),
        case
          when position('@' in coalesce(u.email, '')) > 1
            then left(u.email, 1) || '***' || substring(u.email from position('@' in u.email))
          else 'Tài khoản NanoBio'
        end
      ) as user_label,
      '••••••'::text as masked_code,
      wrr.created_at,
      wrr.cancelled_at,
      wrr.updated_at as sort_at
    from public.wellness_reward_redemptions wrr
    join public.users u on u.id = wrr.user_id
    where coalesce(btrim(p_query), '') = ''
       or wrr.offer_title_snapshot ilike '%' || btrim(p_query) || '%'
       or wrr.provider_name_snapshot ilike '%' || btrim(p_query) || '%'
       or coalesce(u.full_name, '') ilike '%' || btrim(p_query) || '%'
       or coalesce(u.email, '') ilike '%' || btrim(p_query) || '%'
  ),
  combined as (
    select * from offer_rows
    union all
    select * from redemption_rows
  )
  select
    c.item_type,
    c.id,
    c.offer_id,
    c.redemption_id,
    c.title,
    c.description,
    c.provider_name,
    c.cost_points,
    c.points_spent,
    c.status,
    c.is_active,
    c.eligible_plan_codes,
    c.available_from,
    c.available_until,
    c.voucher_expires_at,
    c.available_codes,
    c.issued_codes,
    c.retired_codes,
    c.user_id,
    c.user_label,
    c.masked_code,
    c.created_at,
    c.cancelled_at
  from combined c
  order by c.sort_at desc, c.id desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
end;
$$;


--
-- Name: admin_list_wellness_rewards_v2("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_list_wellness_rewards_v2"("p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_offers jsonb;
  v_redemptions jsonb;
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 200));
begin
  perform public.admin_assert_permission('wellness_rewards.read');

  select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) into v_offers
  from (
    select
      'offer'::text as item_type,
      wro.id,
      wro.id as offer_id,
      wro.reward_type,
      wro.title,
      wro.description,
      wro.provider_name,
      wro.cost_points,
      wro.stock_count,
      wro.eligible_plan_codes,
      wro.available_from,
      wro.available_until,
      wro.voucher_expires_at,
      wro.is_active,
      (select count(*)::integer from public.wellness_reward_codes wrc
        where wrc.offer_id = wro.id and wrc.status = 'available'
          and coalesce(wrc.voucher_expires_at, wro.voucher_expires_at) > now()) as available_codes,
      (select count(*)::integer from public.wellness_reward_codes wrc
        where wrc.offer_id = wro.id and wrc.status = 'issued') as issued_codes,
      wro.created_at,
      wro.updated_at as sort_at
    from public.wellness_reward_offers wro
    where coalesce(btrim(p_query), '') = ''
       or wro.title ilike '%' || btrim(p_query) || '%'
       or wro.provider_name ilike '%' || btrim(p_query) || '%'
       or wro.offer_code ilike '%' || btrim(p_query) || '%'
    order by wro.updated_at desc, wro.id desc
    limit v_limit
  ) q;

  select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) into v_redemptions
  from (
    select
      'redemption'::text as item_type,
      wrr.id,
      wrr.id as redemption_id,
      wrr.offer_id,
      wrr.reward_type_snapshot as reward_type,
      wrr.offer_title_snapshot as title,
      wrr.provider_name_snapshot as provider_name,
      wrr.points_spent,
      wrr.status,
      wrr.voucher_expires_at,
      wrr.received_at,
      wrr.received_by,
      wrr.user_id,
      coalesce(nullif(u.full_name, ''),
        case when position('@' in coalesce(u.email, '')) > 1
          then left(u.email, 1) || '***' || substring(u.email from position('@' in u.email))
          else 'Tài khoản NanoBio' end) as user_label,
      case when wrr.reward_type_snapshot = 'voucher' then '••••••'::text else null end as masked_code,
      wrr.created_at,
      wrr.cancelled_at,
      wrr.updated_at as sort_at
    from public.wellness_reward_redemptions wrr
    join public.users u on u.id = wrr.user_id
    where coalesce(btrim(p_query), '') = ''
       or wrr.offer_title_snapshot ilike '%' || btrim(p_query) || '%'
       or wrr.provider_name_snapshot ilike '%' || btrim(p_query) || '%'
       or coalesce(u.full_name, '') ilike '%' || btrim(p_query) || '%'
       or coalesce(u.email, '') ilike '%' || btrim(p_query) || '%'
    order by wrr.updated_at desc, wrr.id desc
    limit v_limit
  ) q;

  return jsonb_build_object('offers', v_offers, 'redemptions', v_redemptions);
end;
$$;


--
-- Name: admin_mark_reward_redemption_received("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_mark_reward_redemption_received"("p_redemption_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_redemption public.wellness_reward_redemptions%rowtype;
  v_existing_audit public.admin_audit_events%rowtype;
begin
  perform public.admin_assert_permission('wellness_rewards.write');
  if p_redemption_id is null then
    raise exception using errcode = 'P0001', message = 'redemption_required';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'admin_reason_required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:admin:received:' || btrim(p_idempotency_key), 0
  ));
  select * into v_existing_audit
  from public.admin_audit_events aae
  where aae.action = 'admin_mark_reward_redemption_received'
    and aae.idempotency_key = btrim(p_idempotency_key);
  if v_existing_audit.id is not null then
    if v_existing_audit.target_id <> p_redemption_id::text then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    return jsonb_build_object('success', true, 'status', 'received', 'idempotent_replay', true);
  end if;

  select * into v_redemption
  from public.wellness_reward_redemptions
  where id = p_redemption_id
  for update;
  if v_redemption.id is null then
    raise exception using errcode = 'P0001', message = 'redemption_not_found';
  end if;
  if v_redemption.reward_type_snapshot <> 'physical' then
    raise exception using errcode = 'P0001', message = 'physical_reward_required';
  end if;
  if v_redemption.status = 'received' then
    return jsonb_build_object(
      'success', true, 'status', 'received', 'received_at', v_redemption.received_at,
      'idempotent_replay', true
    );
  end if;
  if v_redemption.status <> 'redeemed' then
    raise exception using errcode = 'P0001', message = 'reward_cannot_be_received';
  end if;

  update public.wellness_reward_redemptions
  set status = 'received', received_at = now(), received_by = auth.uid(), updated_at = now()
  where id = v_redemption.id
  returning * into v_redemption;

  perform public.admin_write_audit(
    'admin_mark_reward_redemption_received', 'wellness_reward_redemption',
    v_redemption.id::text, p_reason, p_idempotency_key,
    jsonb_build_object(
      'reward_type', v_redemption.reward_type_snapshot,
      'previous_status', 'redeemed',
      'status', 'received',
      'received_at', v_redemption.received_at
    )
  );

  return jsonb_build_object(
    'success', true, 'redemption_id', v_redemption.id, 'status', 'received',
    'received_at', v_redemption.received_at, 'received_by', v_redemption.received_by,
    'idempotent_replay', false
  );
end;
$$;


--
-- Name: admin_refund_or_cancel_payment("uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_refund_or_cancel_payment"("p_payment_event_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_payment public.payment_events%rowtype;
  v_status text;
begin
  perform public.admin_assert_permission('payments.write');

  if p_decision not in ('refund', 'cancel', 'chargeback') then
    raise exception 'INVALID_PAYMENT_REVERSAL_DECISION' using errcode = '22023';
  end if;

  select * into v_payment
  from public.payment_events
  where id = p_payment_event_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND' using errcode = '22023';
  end if;

  if coalesce(v_payment.paid_at, v_payment.reviewed_at, v_payment.created_at)
      < now() - interval '24 hours' then
    raise exception 'PAYMENT_REVERSAL_WINDOW_EXPIRED' using errcode = '22023';
  end if;

  v_status := case
    when p_decision = 'refund' then 'refunded'
    when p_decision = 'chargeback' then 'chargeback'
    else 'failed'
  end;

  update public.payment_events
  set
    status = v_status,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_reason = btrim(p_reason),
    metadata = metadata || jsonb_build_object('admin_decision', p_decision)
  where id = p_payment_event_id;

  perform public.create_sale_point_reversal_for_payment(
    p_payment_event_id,
    p_decision,
    p_reason,
    p_idempotency_key
  );

  if v_payment.subscription_id is not null then
    update public.membership_subscriptions
    set status = 'canceled', ends_at = least(coalesce(ends_at, now()), now())
    where id = v_payment.subscription_id
      and status in ('trialing', 'active', 'past_due');
  end if;

  perform public.admin_write_audit(
    'admin_refund_or_cancel_payment',
    'payment_event',
    p_payment_event_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'decision',
      p_decision,
      'reversal_policy',
      'negative_sale_point_adjustment'
    )
  );

  return query select true, 'Da xu ly hoan huy va tru diem Sale neu co.';
end;
$$;


--
-- Name: admin_request_report_export("text", "jsonb", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_request_report_export"("p_report_type" "text", "p_filters" "jsonb", "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_export_id uuid;
begin
  perform public.admin_assert_permission('reports.write');

  if btrim(coalesce(p_report_type, '')) not in (
    'membership_summary',
    'sale_points_summary',
    'admin_audit_summary'
  ) then
    raise exception 'INVALID_REPORT_TYPE' using errcode = '22023';
  end if;

  insert into public.report_exports (
    report_type,
    filters,
    reason,
    requested_by
  )
  values (
    btrim(p_report_type),
    jsonb_build_object(
      'report_type', btrim(p_report_type),
      'time_zone', coalesce(p_filters ->> 'time_zone', 'Asia/Ho_Chi_Minh'),
      'privacy', 'no_raw_payloads'
    ),
    btrim(p_reason),
    auth.uid()
  )
  returning id into v_export_id;

  perform public.admin_write_audit(
    'admin_request_report_export',
    'report_export',
    v_export_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'report_type', btrim(p_report_type),
      'time_zone', coalesce(p_filters ->> 'time_zone', 'Asia/Ho_Chi_Minh'),
      'privacy', 'no_raw_payloads'
    )
  );

  return query select true, 'Da tao yeu cau xuat bao cao.';
end;
$$;


--
-- Name: admin_review_payment("uuid", "text", "text", "text", boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_review_payment"("p_payment_event_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text", "p_transfer_verified" boolean) RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_payment public.payment_events%rowtype;
  v_existing_subscription public.membership_subscriptions%rowtype;
  v_payer_user_id uuid;
  v_legacy_subscription_id uuid;
  v_subscription_id uuid := gen_random_uuid();
  v_switched_subscription_ids uuid[] := array[]::uuid[];
  v_decision text := lower(btrim(coalesce(p_decision, '')));
  v_billing_cycle text;
  v_reviewed_at timestamptz := now();
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_transition text;
begin
  perform public.admin_assert_payment_reviewer();

  if v_decision not in ('approve', 'reject') then
    raise exception 'INVALID_PAYMENT_DECISION' using errcode = '22023';
  end if;

  -- Lock the payer before the payment row so parallel approvals and request
  -- creation serialize on the same user.
  select pe.payer_user_id
  into v_payer_user_id
  from public.payment_events pe
  where pe.id = p_payment_event_id;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND' using errcode = '22023';
  end if;

  perform 1
  from public.users u
  where u.id = v_payer_user_id
  for update;

  select *
  into v_payment
  from public.payment_events pe
  where pe.id = p_payment_event_id
  for update;

  if v_payment.status in ('succeeded', 'failed') then
    if v_payment.metadata ->> 'admin_decision' = v_decision then
      return query select true, 'Payment da duoc xu ly truoc do.';
      return;
    end if;

    raise exception 'PAYMENT_ALREADY_REVIEWED' using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'PAYMENT_REVIEW_REASON_REQUIRED' using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode = '22023';
  end if;

  if v_decision = 'approve' and p_transfer_verified is distinct from true then
    raise exception 'PAYMENT_TRANSFER_RECONCILIATION_REQUIRED'
      using errcode = '22023';
  end if;

  -- Historical `pending` payments remain reviewable, but must include the
  -- billing-cycle snapshot required for finite, auditable access periods.
  if v_payment.status not in ('pending_review', 'pending') then
    raise exception 'PAYMENT_NOT_READY_FOR_REVIEW' using errcode = '22023';
  end if;

  v_billing_cycle := lower(btrim(coalesce(
    v_payment.metadata ->> 'billing_cycle',
    ''
  )));
  if v_decision = 'approve'
    and v_billing_cycle not in ('monthly', 'yearly') then
    raise exception 'PAYMENT_BILLING_CYCLE_MISSING' using errcode = '22023';
  end if;

  if v_decision = 'approve' then
    -- Never infer an expiry for old paid access. A controlled data migration
    -- must repair it before a new approval can change the user's plan.
    select ms.id
    into v_legacy_subscription_id
    from public.membership_subscriptions ms
    where ms.user_id = v_payment.payer_user_id
      and ms.plan_code in ('plus', 'family_plus')
      and ms.status in ('trialing', 'active')
      and ms.starts_at <= v_reviewed_at
      and ms.ends_at is null
    limit 1
    for update;

    if found then
      raise exception 'LEGACY_PAID_SUBSCRIPTION_MISSING_ENDS_AT'
        using errcode = '22023',
          hint = 'Repair the legacy paid subscription with a controlled migration before approving another package.';
    end if;

    -- A cross-plan purchase is an immediate switch. Each superseded record is
    -- linked to the new payment/subscription for both user history and audit.
    with switched as (
      update public.membership_subscriptions ms
      set
        status = 'canceled',
        -- Keep the row's period constraint valid even for a legacy record
        -- that started at exactly v_reviewed_at. Its canceled status removes
        -- access immediately; the microsecond is schema-only bookkeeping.
        ends_at = greatest(
          v_reviewed_at,
          ms.starts_at + interval '1 microsecond'
        ),
        current_period_end = greatest(
          v_reviewed_at,
          ms.starts_at + interval '1 microsecond'
        ),
        metadata = ms.metadata || jsonb_build_object(
          'superseded_at', v_reviewed_at,
          'superseded_by_payment_event_id', v_payment.id,
          'superseded_by_subscription_id', v_subscription_id,
          'superseded_by_plan_code', v_payment.plan_code::text
        )
      where ms.user_id = v_payment.payer_user_id
        and ms.plan_code in ('plus', 'family_plus')
        and ms.plan_code <> v_payment.plan_code
        and ms.status in ('trialing', 'active')
        and ms.starts_at <= v_reviewed_at
        and ms.ends_at > v_reviewed_at
      returning ms.id
    )
    select coalesce(array_agg(id), array[]::uuid[])
    into v_switched_subscription_ids
    from switched;

    select *
    into v_existing_subscription
    from public.membership_subscriptions ms
    where ms.user_id = v_payment.payer_user_id
      and ms.plan_code = v_payment.plan_code
      and ms.status in ('trialing', 'active')
      and ms.starts_at <= v_reviewed_at
      and ms.ends_at > v_reviewed_at
    order by ms.ends_at desc, ms.starts_at desc
    limit 1
    for update;

    if found then
      v_period_start := v_existing_subscription.ends_at;
      v_transition := 'same_plan_renewal';
    else
      v_period_start := v_reviewed_at;
      v_transition := case
        when cardinality(v_switched_subscription_ids) > 0 then 'plan_switch'
        else 'new_subscription'
      end;
    end if;

    v_period_end := case v_billing_cycle
      when 'monthly' then (
        (v_period_start at time zone 'Asia/Ho_Chi_Minh') + interval '1 month'
      ) at time zone 'Asia/Ho_Chi_Minh'
      when 'yearly' then (
        (v_period_start at time zone 'Asia/Ho_Chi_Minh') + interval '1 year'
      ) at time zone 'Asia/Ho_Chi_Minh'
    end;

    if v_transition = 'same_plan_renewal' then
      v_subscription_id := v_existing_subscription.id;

      update public.membership_subscriptions
      set
        ends_at = v_period_end,
        current_period_start = v_period_start,
        current_period_end = v_period_end,
        metadata = metadata || jsonb_build_object(
          'last_membership_payment_event_id', v_payment.id,
          'last_billing_cycle', v_billing_cycle,
          'last_renewed_at', v_reviewed_at
        )
      where id = v_subscription_id;
    else
      insert into public.membership_subscriptions (
        id,
        user_id,
        plan_code,
        status,
        source,
        starts_at,
        ends_at,
        current_period_start,
        current_period_end,
        provider,
        provider_subscription_id,
        metadata
      )
      values (
        v_subscription_id,
        v_payment.payer_user_id,
        v_payment.plan_code,
        'active',
        'payment_provider',
        v_period_start,
        v_period_end,
        v_period_start,
        v_period_end,
        v_payment.provider,
        v_payment.provider_event_id,
        jsonb_build_object(
          'payment_event_id', v_payment.id,
          'billing_cycle', v_billing_cycle,
          'approved_at', v_reviewed_at,
          'subscription_transition', v_transition,
          'superseded_subscription_ids', v_switched_subscription_ids
        )
      );
    end if;
  else
    v_transition := 'rejected';
  end if;

  update public.payment_events
  set
    status = case when v_decision = 'approve' then 'succeeded' else 'failed' end,
    paid_at = case
      when v_decision = 'approve' then coalesce(paid_at, v_reviewed_at)
      else paid_at
    end,
    reviewed_by = auth.uid(),
    reviewed_at = v_reviewed_at,
    review_reason = nullif(btrim(p_reason), ''),
    subscription_id = case
      when v_decision = 'approve' then v_subscription_id
      else subscription_id
    end,
    metadata = metadata || jsonb_build_object(
      'admin_decision', v_decision,
      'admin_review_idempotency_key', btrim(p_idempotency_key),
      'manual_approval_required', true,
      'transfer_reconciliation_confirmed', coalesce(p_transfer_verified, false),
      'transfer_reference', transfer_reference,
      'transfer_memo', transfer_memo,
      'transfer_confirmed_at', metadata ->> 'transfer_confirmed_at',
      'billing_cycle', v_billing_cycle,
      'subscription_transition', v_transition,
      'subscription_id', case
        when v_decision = 'approve' then v_subscription_id::text
        else null
      end,
      'superseded_subscription_ids', v_switched_subscription_ids
    )
  where id = p_payment_event_id
  returning * into v_payment;

  perform public.admin_write_audit(
    'admin_review_payment',
    'payment_event',
    p_payment_event_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'decision', v_decision,
      'transfer_reconciliation_confirmed', coalesce(p_transfer_verified, false),
      'transfer_reference', v_payment.transfer_reference,
      'transfer_memo', v_payment.transfer_memo,
      'transfer_confirmed_at', v_payment.metadata ->> 'transfer_confirmed_at',
      'billing_cycle', v_billing_cycle,
      'subscription_transition', v_transition,
      'subscription_id', case
        when v_decision = 'approve' then v_subscription_id::text
        else null
      end,
      'superseded_subscription_ids', v_switched_subscription_ids
    )
  );

  return query select true, 'Da xu ly payment.';
end;
$$;


--
-- Name: admin_review_sale_point_conversion("uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_review_sale_point_conversion"("p_conversion_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text", "p_payment_proof_path" "text" DEFAULT NULL::"text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  perform public.admin_assert_permission('sales.write');

  v_status := case p_decision
    when 'approve' then 'approved'
    when 'reject' then 'rejected'
    when 'mark_paid' then 'paid'
    else null
  end;

  if v_status is null then
    raise exception 'INVALID_CONVERSION_DECISION' using errcode = '22023';
  end if;

  update public.sale_point_conversions
  set
    status = v_status,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_reason = btrim(p_reason),
    paid_at = case when v_status = 'paid' then now() else paid_at end,
    metadata = metadata
      || jsonb_build_object('admin_decision', p_decision)
      || case
        when nullif(btrim(coalesce(p_payment_proof_path, '')), '') is null then '{}'::jsonb
        else jsonb_build_object('payment_proof_path', btrim(p_payment_proof_path))
      end
  where id = p_conversion_id;

  if not found then
    raise exception 'SALE_CONVERSION_NOT_FOUND' using errcode = '22023';
  end if;

  perform public.admin_write_audit(
    'admin_review_sale_point_conversion',
    'sale_point_conversion',
    p_conversion_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'decision',
      p_decision,
      'status',
      v_status,
      'payment_proof_path',
      nullif(btrim(coalesce(p_payment_proof_path, '')), '')
    )
  );

  return query select true, 'Da cap nhat yeu cau quy doi diem Sale.';
end;
$$;


--
-- Name: admin_review_sale_profile("uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_review_sale_profile"("p_sale_user_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status public.nb_sale_status;
  v_candidate text;
  v_created_code text;
begin
  perform public.admin_assert_permission('sales.write');

  v_status := case p_decision
    when 'approve' then 'active'::public.nb_sale_status
    when 'reject' then 'closed'::public.nb_sale_status
    when 'suspend' then 'suspended'::public.nb_sale_status
    when 'close' then 'closed'::public.nb_sale_status
    else null
  end;

  if v_status is null then
    raise exception 'INVALID_SALE_DECISION' using errcode = '22023';
  end if;

  if v_status = 'active' and not exists (
    select 1
    from public.membership_subscriptions ms
    where ms.user_id = p_sale_user_id
      and ms.plan_code in ('plus', 'family_plus')
      and ms.status = 'active'
      and ms.starts_at <= now()
      and (ms.ends_at is null or ms.ends_at > now())
  ) then
    raise exception 'SALE_REQUIRES_ACTIVE_PAID_PLAN' using errcode = '42501';
  end if;

  insert into public.sale_profiles (user_id, status, approved_at, note)
  values (
    p_sale_user_id,
    v_status,
    case when v_status = 'active' then now() else null end,
    btrim(p_reason)
  )
  on conflict (user_id) do update
  set
    status = excluded.status,
    approved_at = case
      when excluded.status = 'active' then coalesce(public.sale_profiles.approved_at, now())
      else public.sale_profiles.approved_at
    end,
    suspended_at = case
      when excluded.status = 'suspended' then now()
      else public.sale_profiles.suspended_at
    end,
    closed_at = case
      when excluded.status = 'closed' then now()
      else public.sale_profiles.closed_at
    end,
    note = excluded.note,
    updated_at = now();

  if v_status = 'active' and not exists (
    select 1
    from public.referral_codes
    where sale_user_id = p_sale_user_id
      and status = 'active'
  ) then
    for i in 1..12 loop
      v_candidate := 'NANO-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
      insert into public.referral_codes (code, sale_user_id, status)
      values (v_candidate, p_sale_user_id, 'active')
      on conflict (code) do nothing
      returning code into v_created_code;
      exit when v_created_code is not null;
    end loop;

    if v_created_code is null then
      raise exception 'REFERRAL_CODE_ALLOCATION_FAILED';
    end if;
  end if;

  perform public.admin_write_audit(
    'admin_review_sale_profile',
    'sale_profile',
    p_sale_user_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object('decision', p_decision, 'status', v_status::text)
  );

  return query select true, 'Da cap nhat Sale.';
end;
$$;


--
-- Name: admin_search_users("text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_search_users"("p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "text", "title" "text", "subtitle" "text", "status" "text", "section" "text", "created_at" timestamp with time zone, "plan_code" "text", "subscription_id" "text", "membership_status" "text", "membership_source" "text", "membership_starts_at" timestamp with time zone, "membership_ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.admin_assert_permission('users.write');

  return query
  select
    u.id::text,
    coalesce(nullif(u.full_name, ''), nullif(u.email, ''), u.id::text),
    concat_ws(' - ', u.email, access.plan_code, u.sale_status::text),
    u.admin_status,
    'users',
    u.created_at,
    access.plan_code,
    paid_membership.id::text,
    paid_membership.status,
    paid_membership.source,
    paid_membership.starts_at,
    paid_membership.ends_at
  from public.users u
  cross join lateral (
    select case
      when u.is_anonymous and u.product_access_status = 'guest' then 'guest'
      else public.current_plan_for_user(u.id)::text
    end as plan_code
  ) access
  left join lateral (
    select
      ms.id,
      ms.status,
      ms.source,
      ms.starts_at,
      ms.ends_at
    from public.membership_subscriptions ms
    where ms.user_id = u.id
      and ms.plan_code in ('plus', 'family_plus')
      and ms.status in ('trialing', 'active')
      and ms.starts_at <= now()
      and (ms.ends_at is null or ms.ends_at > now())
    order by
      case ms.plan_code
        when 'family_plus' then 3
        when 'plus' then 2
        else 1
      end desc,
      ms.starts_at desc
    limit 1
  ) paid_membership on true
  where coalesce(p_query, '') = ''
     or u.email ilike '%' || p_query || '%'
     or u.full_name ilike '%' || p_query || '%'
     or u.phone ilike '%' || p_query || '%'
  order by u.created_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 100));
end;
$$;


--
-- Name: admin_update_early_access_lead_status("uuid", "text", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_update_early_access_lead_status"("p_lead_id" "uuid", "p_status" "text", "p_actor_id" "uuid", "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_old_status text;
  v_existing_target text;
begin
  if p_status not in ('new','contacted','registered','converted','rejected')
     or p_reason is null or char_length(btrim(p_reason)) < 5 or char_length(p_reason) > 300
     or p_idempotency_key is null or char_length(p_idempotency_key) < 8
     or char_length(p_idempotency_key) > 120 then
    raise exception 'INVALID_EARLY_ACCESS_STATUS_UPDATE' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.users u
    where u.id = p_actor_id and u.admin_status = 'active'
  ) or not exists (
    select 1
    from public.admin_user_roles aur
    join public.admin_roles ar on ar.code = aur.role_code and ar.is_active = true
    where aur.user_id = p_actor_id
      and aur.role_code in ('super_admin','support_admin','operations_admin')
      and aur.is_active = true and aur.revoked_at is null
  ) then
    raise exception 'EARLY_ACCESS_ADMIN_ROLE_REQUIRED' using errcode = '42501';
  end if;

  select target_id into v_existing_target
  from public.admin_audit_events
  where action = 'early_access_lead_status_updated'
    and idempotency_key = p_idempotency_key;
  if found then
    if v_existing_target <> p_lead_id::text then
      raise exception 'EARLY_ACCESS_IDEMPOTENCY_CONFLICT' using errcode = '23505';
    end if;
    return jsonb_build_object('success', true, 'message', 'Đã xử lý thao tác trước đó.');
  end if;

  select status into v_old_status
  from public.early_access_leads
  where id = p_lead_id
  for update;
  if not found then
    raise exception 'EARLY_ACCESS_LEAD_NOT_FOUND' using errcode = 'P0002';
  end if;

  update public.early_access_leads set status = p_status where id = p_lead_id;
  insert into public.admin_audit_events (
    actor_id, action, target_type, target_id, reason, idempotency_key, metadata
  ) values (
    p_actor_id, 'early_access_lead_status_updated', 'early_access_lead',
    p_lead_id::text, btrim(p_reason), p_idempotency_key,
    jsonb_build_object('from_status', v_old_status, 'to_status', p_status)
  );
  return jsonb_build_object('success', true, 'message', 'Đã cập nhật trạng thái hồ sơ.');
end;
$$;


--
-- Name: admin_update_reconciliation_discrepancy_status("uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_update_reconciliation_discrepancy_status"("p_discrepancy_id" "uuid", "p_status" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_discrepancy public.admin_reconciliation_discrepancies%rowtype;
begin
  perform public.admin_assert_permission('reconciliation.write');

  if p_status not in ('needs_follow_up', 'resolved', 'adjusted', 'dismissed') then
    raise exception 'INVALID_RECONCILIATION_STATUS' using errcode = '22023';
  end if;

  select * into v_discrepancy
  from public.admin_reconciliation_discrepancies
  where id = p_discrepancy_id
  for update;

  if not found then
    raise exception 'RECONCILIATION_DISCREPANCY_NOT_FOUND' using errcode = '22023';
  end if;

  update public.admin_reconciliation_discrepancies
  set
    status = p_status,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    review_reason = btrim(p_reason)
  where id = p_discrepancy_id;

  if p_status = 'adjusted'
    and (v_discrepancy.metadata ? 'sale_user_id')
    and (v_discrepancy.metadata ? 'point_delta_cents') then
    insert into public.sale_point_adjustments (
      sale_user_id,
      point_delta_cents,
      reason,
      reviewed_by,
      idempotency_key,
      metadata
    )
    values (
      (v_discrepancy.metadata ->> 'sale_user_id')::uuid,
      (v_discrepancy.metadata ->> 'point_delta_cents')::integer,
      btrim(p_reason),
      auth.uid(),
      nullif(btrim(p_idempotency_key), ''),
      jsonb_build_object('reconciliation_discrepancy_id', p_discrepancy_id)
    )
    on conflict (idempotency_key) do update
    set metadata = public.sale_point_adjustments.metadata;
  end if;

  perform public.admin_write_audit(
    'admin_update_reconciliation_discrepancy_status',
    'admin_reconciliation_discrepancy',
    p_discrepancy_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object('status', p_status)
  );

  return query select true, 'Da cap nhat doi soat.';
end;
$$;


--
-- Name: admin_update_user_status("uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_update_user_status"("p_user_id" "uuid", "p_status" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.admin_assert_permission('users.write');

  if p_status not in ('active', 'suspended', 'closed') then
    raise exception 'INVALID_USER_STATUS' using errcode = '22023';
  end if;

  update public.users
  set admin_status = p_status, updated_at = now()
  where id = p_user_id;

  if not found then
    raise exception 'USER_NOT_FOUND' using errcode = 'P0002';
  end if;

  -- public.users.admin_status is the operational source used by NanoBio.
  -- Mirror it into Supabase Auth so a suspended/closed user cannot create a
  -- new password session. Existing Auth sessions are removed immediately.
  if p_status in ('suspended', 'closed') then
    update auth.users
    set banned_until = now() + interval '100 years',
        updated_at = now()
    where id = p_user_id;

    delete from auth.sessions
    where user_id = p_user_id;
  else
    update auth.users
    set banned_until = null,
        updated_at = now()
    where id = p_user_id;
  end if;

  perform public.admin_write_audit(
    'admin_update_user_status',
    'user',
    p_user_id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'status', p_status,
      'auth_enforced', true
    )
  );

  return query select true, 'Da cap nhat trang thai nguoi dung.';
end;
$$;


--
-- Name: admin_upsert_config_version("text", "jsonb", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_upsert_config_version"("p_config_key" "text", "p_config_value" "jsonb", "p_reason" "text", "p_idempotency_key" "text") RETURNS TABLE("success" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_permission text;
begin
  v_permission := case
    when p_config_key ilike 'plan%' then 'plans.write'
    else 'config.write'
  end;

  perform public.admin_assert_permission(v_permission);

  update public.system_config_versions
  set status = 'archived'
  where config_key = p_config_key
    and status = 'active';

  insert into public.system_config_versions (
    config_key,
    config_value,
    status,
    reason,
    created_by
  )
  values (
    btrim(p_config_key),
    coalesce(p_config_value, '{}'::jsonb),
    'active',
    btrim(p_reason),
    auth.uid()
  );

  perform public.admin_write_audit(
    'admin_upsert_config_version',
    'system_config',
    p_config_key,
    p_reason,
    p_idempotency_key,
    coalesce(p_config_value, '{}'::jsonb)
  );

  return query select true, 'Da luu phien ban cau hinh.';
end;
$$;


--
-- Name: admin_upsert_nabi_notification_definition("text", integer, "text", integer, "text", "text", "text", "text"[], "text", "text", "jsonb", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_upsert_nabi_notification_definition"("p_notification_id" "text", "p_content_version" integer, "p_category" "text", "p_priority" integer, "p_policy_key" "text", "p_primary_action_key" "text", "p_secondary_action_key" "text", "p_allowed_channels" "text"[], "p_title_template" "text", "p_body_template" "text", "p_config" "jsonb", "p_status" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  perform public.admin_assert_permission('notifications.write');
  if nullif(btrim(coalesce(p_reason, '')), '') is null
     or nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception 'ADMIN_REASON_AND_IDEMPOTENCY_REQUIRED' using errcode = '22023';
  end if;
  if p_status not in ('draft', 'active', 'archived')
     or p_category not in ('contextual', 'milestone', 'subscription', 'retention', 'reward', 'report', 'care', 'profile')
     or not p_policy_key = any(array[
       'free_plan_limit', 'free_chat_limit', 'first_streak_7', 'expert_locked',
       'map365_locked', 'weekly_report_locked', 'expert_recommended',
       'plus_day_7', 'plus_day_15', 'plus_expiry_5', 'plus_expiry_1',
       'streak_6', 'rescue_card', 'reward_ready', 'report_ready',
       'invite_available', 'care_near_sleep', 'return_72h', 'partial_day', 'profile_stale'
     ])
     or not p_primary_action_key = any(array[
       'membership_compare', 'membership_payment', 'achievement', 'expert_benefit',
       'map365', 'weekly_report', 'easiest_task', 'rescue_card_confirm',
       'reward_box', 'user_invite', 'dashboard_today', 'today_tasks', 'partial_profile'
     ])
     or exists (
       select 1 from unnest(coalesce(p_allowed_channels, array[]::text[])) channel
       where channel not in ('in_app', 'os_local')
     ) then
    raise exception 'INVALID_NOTIFICATION_DEFINITION' using errcode = '22023';
  end if;

  if p_status = 'active' then
    update public.nabi_notification_definitions
    set status = 'archived'
    where notification_id = btrim(p_notification_id) and status = 'active';
  end if;

  insert into public.nabi_notification_definitions (
    notification_id, content_version, category, priority, policy_key,
    primary_action_key, secondary_action_key, allowed_channels,
    title_template, body_template, config, status, reason, created_by
  ) values (
    btrim(p_notification_id), p_content_version, p_category, p_priority,
    p_policy_key, p_primary_action_key, nullif(btrim(coalesce(p_secondary_action_key, '')), ''),
    p_allowed_channels, p_title_template, p_body_template,
    coalesce(p_config, '{}'::jsonb), p_status, btrim(p_reason), auth.uid()
  )
  on conflict (notification_id, content_version) do update set
    category = excluded.category,
    priority = excluded.priority,
    policy_key = excluded.policy_key,
    primary_action_key = excluded.primary_action_key,
    secondary_action_key = excluded.secondary_action_key,
    allowed_channels = excluded.allowed_channels,
    title_template = excluded.title_template,
    body_template = excluded.body_template,
    config = excluded.config,
    status = excluded.status,
    reason = excluded.reason
  returning id into v_id;

  perform public.admin_write_audit(
    'nabi_notification_definition_upsert', 'nabi_notification_definition',
    btrim(p_notification_id), btrim(p_reason), btrim(p_idempotency_key),
    jsonb_build_object('content_version', p_content_version, 'status', p_status)
  );
  return v_id;
end;
$$;


--
-- Name: admin_upsert_reward_offer("uuid", "text", "text", "text", integer, "text"[], timestamp with time zone, timestamp with time zone, timestamp with time zone, boolean, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_upsert_reward_offer"("p_offer_id" "uuid", "p_title" "text", "p_description" "text", "p_provider_name" "text", "p_cost_points" integer, "p_eligible_plan_codes" "text"[], "p_available_from" timestamp with time zone, "p_available_until" timestamp with time zone, "p_voucher_expires_at" timestamp with time zone, "p_is_active" boolean, "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_offer public.wellness_reward_offers%rowtype;
  v_new_id uuid := coalesce(p_offer_id, gen_random_uuid());
  v_existing_audit public.admin_audit_events%rowtype;
begin
  perform public.admin_assert_permission('wellness_rewards.write');

  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'admin_reason_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:admin:upsert:' || btrim(p_idempotency_key),
    0
  ));

  select * into v_existing_audit
  from public.admin_audit_events aae
  where aae.action = 'admin_upsert_reward_offer'
    and aae.idempotency_key = btrim(p_idempotency_key);

  if v_existing_audit.id is not null then
    if p_offer_id is not null
       and v_existing_audit.target_id <> p_offer_id::text then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    select * into v_offer
    from public.wellness_reward_offers
    where id::text = v_existing_audit.target_id;
    return jsonb_build_object(
      'success', true,
      'message', 'Yêu cầu đã được xử lý trước đó.',
      'offer_id', v_offer.id,
      'accepted_count', 0,
      'duplicate_count', 0,
      'rejected_count', 0,
      'idempotent_replay', true
    );
  end if;

  if not public.reward_text_is_vietnamese(p_title)
     or not public.reward_text_is_vietnamese(p_description) then
    raise exception using errcode = 'P0001', message = 'invalid_vietnamese_copy';
  end if;
  if nullif(btrim(coalesce(p_provider_name, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'provider_name_required';
  end if;
  if p_cost_points is null or p_cost_points <= 0 then
    raise exception using errcode = 'P0001', message = 'reward_cost_invalid';
  end if;
  if p_eligible_plan_codes is null
     or cardinality(p_eligible_plan_codes) = 0
     or not (p_eligible_plan_codes <@ array['free', 'plus', 'family_plus']::text[]) then
    raise exception using errcode = 'P0001', message = 'eligible_plans_invalid';
  end if;
  if p_available_from is not null and p_available_until is not null
     and p_available_until <= p_available_from then
    raise exception using errcode = 'P0001', message = 'offer_window_invalid';
  end if;
  if p_voucher_expires_at is not null and p_voucher_expires_at <= now() then
    raise exception using errcode = 'P0001', message = 'voucher_expiry_invalid';
  end if;

  if p_offer_id is not null and not exists (
    select 1 from public.wellness_reward_offers where id = p_offer_id
  ) then
    raise exception using errcode = 'P0001', message = 'offer_not_found';
  end if;

  insert into public.wellness_reward_offers (
    id,
    offer_code,
    title,
    description,
    provider_name,
    cost_points,
    eligible_plan_codes,
    available_from,
    available_until,
    voucher_expires_at,
    is_active,
    created_by,
    updated_by
  )
  values (
    v_new_id,
    'reward_' || replace(v_new_id::text, '-', ''),
    btrim(p_title),
    btrim(p_description),
    btrim(p_provider_name),
    p_cost_points,
    array(select distinct lower(btrim(x)) from unnest(p_eligible_plan_codes) x order by 1),
    p_available_from,
    p_available_until,
    p_voucher_expires_at,
    coalesce(p_is_active, false),
    auth.uid(),
    auth.uid()
  )
  on conflict (id) do update
  set
    title = excluded.title,
    description = excluded.description,
    provider_name = excluded.provider_name,
    cost_points = excluded.cost_points,
    eligible_plan_codes = excluded.eligible_plan_codes,
    available_from = excluded.available_from,
    available_until = excluded.available_until,
    voucher_expires_at = excluded.voucher_expires_at,
    is_active = excluded.is_active,
    updated_by = auth.uid(),
    updated_at = now()
  returning * into v_offer;

  perform public.admin_write_audit(
    'admin_upsert_reward_offer',
    'wellness_reward_offer',
    v_offer.id::text,
    p_reason,
    p_idempotency_key,
    jsonb_build_object(
      'is_active', v_offer.is_active,
      'cost_points', v_offer.cost_points,
      'eligible_plan_codes', v_offer.eligible_plan_codes,
      'voucher_expires_at', v_offer.voucher_expires_at
    )
  );

  return jsonb_build_object(
    'success', true,
    'message', 'Đã lưu ưu đãi.',
    'offer_id', v_offer.id,
    'accepted_count', 1,
    'duplicate_count', 0,
    'rejected_count', 0,
    'idempotent_replay', false
  );
end;
$$;


--
-- Name: admin_upsert_reward_offer_v2("uuid", "text", "text", "text", "text", integer, integer, "text"[], timestamp with time zone, timestamp with time zone, timestamp with time zone, boolean, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_upsert_reward_offer_v2"("p_offer_id" "uuid", "p_reward_type" "text", "p_title" "text", "p_description" "text", "p_provider_name" "text", "p_cost_points" integer, "p_stock_count" integer, "p_eligible_plan_codes" "text"[], "p_available_from" timestamp with time zone, "p_available_until" timestamp with time zone, "p_voucher_expires_at" timestamp with time zone, "p_is_active" boolean, "p_reason" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_offer public.wellness_reward_offers%rowtype;
  v_existing_audit public.admin_audit_events%rowtype;
  v_new_id uuid := coalesce(p_offer_id, gen_random_uuid());
begin
  perform public.admin_assert_permission('wellness_rewards.write');
  if coalesce(p_reward_type, '') not in ('voucher', 'physical') then
    raise exception using errcode = 'P0001', message = 'reward_type_invalid';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'admin_reason_required';
  end if;

  if p_offer_id is not null then
    select * into v_offer from public.wellness_reward_offers
    where id = p_offer_id for update;
    if v_offer.id is null then
      raise exception using errcode = 'P0001', message = 'offer_not_found';
    end if;
    if v_offer.reward_type <> p_reward_type then
      raise exception using errcode = 'P0001', message = 'reward_type_immutable';
    end if;
  end if;

  if p_reward_type = 'voucher' then
    return public.admin_upsert_reward_offer(
      p_offer_id, p_title, p_description, p_provider_name, p_cost_points,
      p_eligible_plan_codes, p_available_from, p_available_until,
      p_voucher_expires_at, p_is_active, p_reason, p_idempotency_key
    );
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:admin:upsert:physical:' || btrim(p_idempotency_key), 0
  ));
  select * into v_existing_audit
  from public.admin_audit_events aae
  where aae.action = 'admin_upsert_physical_reward_offer'
    and aae.idempotency_key = btrim(p_idempotency_key);
  if v_existing_audit.id is not null then
    if p_offer_id is not null and v_existing_audit.target_id <> p_offer_id::text then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    return jsonb_build_object(
      'success', true,
      'message', 'Yêu cầu đã được xử lý trước đó.',
      'offer_id', v_existing_audit.target_id,
      'idempotent_replay', true
    );
  end if;

  if not public.reward_text_is_vietnamese(p_title)
     or not public.reward_text_is_vietnamese(p_description) then
    raise exception using errcode = 'P0001', message = 'invalid_vietnamese_copy';
  end if;
  if nullif(btrim(coalesce(p_provider_name, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'provider_name_required';
  end if;
  if p_cost_points is null or p_cost_points <= 0 then
    raise exception using errcode = 'P0001', message = 'reward_cost_invalid';
  end if;
  if p_stock_count is null or p_stock_count < 0 then
    raise exception using errcode = 'P0001', message = 'reward_stock_invalid';
  end if;
  if p_eligible_plan_codes is null
     or cardinality(p_eligible_plan_codes) = 0
     or not (p_eligible_plan_codes <@ array['free', 'plus', 'family_plus']::text[]) then
    raise exception using errcode = 'P0001', message = 'eligible_plans_invalid';
  end if;
  if p_available_from is not null and p_available_until is not null
     and p_available_until <= p_available_from then
    raise exception using errcode = 'P0001', message = 'offer_window_invalid';
  end if;

  insert into public.wellness_reward_offers (
    id, offer_code, reward_type, stock_count, title, description, provider_name,
    cost_points, eligible_plan_codes, available_from, available_until,
    voucher_expires_at, is_active, created_by, updated_by
  ) values (
    v_new_id, 'reward_' || replace(v_new_id::text, '-', ''), 'physical', p_stock_count,
    btrim(p_title), btrim(p_description), btrim(p_provider_name), p_cost_points,
    array(select distinct lower(btrim(x)) from unnest(p_eligible_plan_codes) x order by 1),
    p_available_from, p_available_until, null, coalesce(p_is_active, false), auth.uid(), auth.uid()
  )
  on conflict (id) do update set
    title = excluded.title,
    description = excluded.description,
    provider_name = excluded.provider_name,
    cost_points = excluded.cost_points,
    stock_count = excluded.stock_count,
    eligible_plan_codes = excluded.eligible_plan_codes,
    available_from = excluded.available_from,
    available_until = excluded.available_until,
    is_active = excluded.is_active,
    updated_by = auth.uid(),
    updated_at = now()
  returning * into v_offer;

  perform public.admin_write_audit(
    'admin_upsert_physical_reward_offer', 'wellness_reward_offer', v_offer.id::text,
    p_reason, p_idempotency_key,
    jsonb_build_object(
      'reward_type', v_offer.reward_type,
      'is_active', v_offer.is_active,
      'cost_points', v_offer.cost_points,
      'stock_count', v_offer.stock_count,
      'eligible_plan_codes', v_offer.eligible_plan_codes
    )
  );

  return jsonb_build_object(
    'success', true,
    'message', 'Đã lưu quà tặng.',
    'offer_id', v_offer.id,
    'accepted_count', 1,
    'idempotent_replay', false
  );
end;
$$;


--
-- Name: admin_write_audit("text", "text", "text", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."admin_write_audit"("p_action" "text", "p_target_type" "text", "p_target_id" "text", "p_reason" "text", "p_idempotency_key" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  if nullif(btrim(p_reason), '') is null then
    raise exception 'ADMIN_REASON_REQUIRED' using errcode = '22023';
  end if;

  insert into public.admin_audit_events (
    actor_id,
    action,
    target_type,
    target_id,
    reason,
    idempotency_key,
    metadata
  )
  values (
    auth.uid(),
    p_action,
    p_target_type,
    p_target_id,
    btrim(p_reason),
    nullif(btrim(p_idempotency_key), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (action, idempotency_key) do update
  set metadata = public.admin_audit_events.metadata
  returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: anonymize_deleted_user_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."anonymize_deleted_user_records"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.google_play_purchase_ledger
  set user_id = null, updated_at = now()
  where user_id = old.id;

  update public.ai_content_reports
  set
    user_id = null,
    installation_id = null,
    message_id = 'deleted-account',
    note = null,
    message_snapshot = '[deleted-account]'
  where user_id = old.id;

  return old;
end;
$$;


--
-- Name: assert_current_user_familyplus(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."assert_current_user_familyplus"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.membership_subscriptions ms
    where ms.user_id = v_user_id
      and ms.plan_code = 'family_plus'
      and ms.status = 'active'
      and (ms.ends_at is null or ms.ends_at > now())
  ) then
    raise exception 'FAMILYPLUS_REQUIRED' using errcode = '42501';
  end if;

  return v_user_id;
end;
$$;


--
-- Name: attach_my_referral_code("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."attach_my_referral_code"("p_referral_code" "text", "p_device_hash" "text") RETURNS TABLE("success" boolean, "message" "text", "referrer_display_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_code text := upper(replace(btrim(coalesce(p_referral_code, '')), ' ', ''));
  v_device_hash text := btrim(coalesce(p_device_hash, ''));
  v_referrer_id uuid;
  v_referrer_name text;
  v_user_email text;
  v_user_phone text;
  v_referrer_email text;
  v_referrer_phone text;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if v_code = '' then
    return query select false, 'Ma gioi thieu khong hop le.', null::text;
    return;
  end if;

  if v_device_hash = '' then
    return query select false, 'Can xac thuc thiet bi truoc khi gan ma gioi thieu.', null::text;
    return;
  end if;

  select email, phone
  into v_user_email, v_user_phone
  from public.users
  where id = v_user_id;

  select
    rc.sale_user_id,
    coalesce(nullif(u.full_name, ''), 'Sale NanoBio'),
    u.email,
    u.phone
  into v_referrer_id, v_referrer_name, v_referrer_email, v_referrer_phone
  from public.referral_codes rc
  join public.sale_profiles sp
    on sp.user_id = rc.sale_user_id
   and sp.status = 'active'
  join public.users u on u.id = rc.sale_user_id
  where rc.code = v_code
    and rc.status = 'active'
  limit 1;

  if v_referrer_id is null then
    return query select false, 'Ma gioi thieu khong ton tai hoac chua hoat dong.', null::text;
    return;
  end if;

  if v_referrer_id = v_user_id then
    return query select false, 'Khong the dung ma gioi thieu cua chinh minh.', null::text;
    return;
  end if;

  if nullif(lower(coalesce(v_user_email, '')), '') is not null
    and lower(v_user_email) = lower(coalesce(v_referrer_email, '')) then
    return query select false, 'Email co dau hieu trung voi Sale gioi thieu.', null::text;
    return;
  end if;

  if nullif(coalesce(v_user_phone, ''), '') is not null
    and v_user_phone = coalesce(v_referrer_phone, '') then
    return query select false, 'So dien thoai co dau hieu trung voi Sale gioi thieu.', null::text;
    return;
  end if;

  if exists (
    select 1
    from public.sale_profiles sp
    where sp.user_id = v_referrer_id
      and sp.participation_device_hash = v_device_hash
  ) then
    return query select false, 'Thiet bi co dau hieu trung voi Sale gioi thieu.', null::text;
    return;
  end if;

  if exists (
    select 1
    from public.referral_relationships
    where referred_user_id = v_user_id
      and status = 'active'
  ) then
    return query select false, 'Tai khoan da co ma gioi thieu.', null::text;
    return;
  end if;

  if exists (
    select 1
    from public.referral_relationships rr
    where rr.device_hash = v_device_hash
      and rr.status = 'active'
  ) then
    return query select false, 'Thiet bi nay da duoc dung de gan ma gioi thieu.', null::text;
    return;
  end if;

  if exists (
    select 1
    from public.payment_events
    where payer_user_id = v_user_id
      and status in ('pending', 'succeeded', 'refunded', 'chargeback')
  ) then
    return query select false, 'Tai khoan da co lich su payment nen khong the gan ma trong ung dung.', null::text;
    return;
  end if;

  insert into public.referral_relationships (
    referrer_user_id,
    referred_user_id,
    referral_code,
    source,
    status,
    device_hash,
    metadata
  )
  values (
    v_referrer_id,
    v_user_id,
    v_code,
    'signup',
    'active',
    v_device_hash,
    jsonb_build_object(
      'anti_fraud_checks',
      jsonb_build_array('self', 'existing_referral', 'payment_history', 'email', 'phone', 'device'),
      'attached_during',
      'account_registration'
    )
  );

  return query select true, 'Da gan ma gioi thieu.', v_referrer_name;
end;
$$;


--
-- Name: begin_my_schedule_completion("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."begin_my_schedule_completion"("p_schedule_item_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_eligibility public.schedule_reward_eligibilities%rowtype;
  v_attempt public.schedule_completion_attempts%rowtype;
  v_attempt_id uuid := gen_random_uuid();
  v_path text;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  if not public.wellness_rewards_feature_enabled() then
    raise exception using errcode = 'P0001', message = 'wellness_rewards_disabled';
  end if;
  if p_schedule_item_id is null then
    raise exception using errcode = 'P0001', message = 'schedule_item_required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:begin:' || v_user_id::text || ':' || btrim(p_idempotency_key),
    0
  ));

  select * into v_attempt
  from public.schedule_completion_attempts sca
  where sca.user_id = v_user_id
    and sca.begin_idempotency_key = btrim(p_idempotency_key);

  if v_attempt.id is not null then
    if not exists (
      select 1
      from public.schedule_reward_eligibilities sre
      where sre.id = v_attempt.eligibility_id
        and sre.schedule_item_id = p_schedule_item_id
    ) then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    if v_attempt.status = 'undone' then
      raise exception using errcode = 'P0001', message = 'eligibility_not_available';
    end if;
    return jsonb_build_object(
      'attempt_id', v_attempt.id,
      'eligibility_id', v_attempt.eligibility_id,
      'bucket_id', 'schedule-completion-proofs',
      'storage_path', v_attempt.object_path,
      'object_path', v_attempt.object_path,
      'content_type', 'image/jpeg',
      'max_bytes', 5242880,
      'window_end', (
        select window_end from public.schedule_reward_eligibilities
        where id = v_attempt.eligibility_id
      ),
      'upload_deadline', (
        select window_end from public.schedule_reward_eligibilities
        where id = v_attempt.eligibility_id
      ),
      'status', v_attempt.status,
      'idempotent_replay', true
    );
  end if;

  select * into v_eligibility
  from public.schedule_reward_eligibilities sre
  where sre.schedule_item_id = p_schedule_item_id
    and sre.user_id = v_user_id
  for update;

  if v_eligibility.id is null then
    raise exception using errcode = 'P0001', message = 'eligibility_not_found';
  end if;
  if v_eligibility.status = 'completed' then
    raise exception using errcode = 'P0001', message = 'schedule_already_completed';
  end if;
  if v_eligibility.status <> 'eligible' then
    raise exception using errcode = 'P0001', message = 'eligibility_not_available';
  end if;
  if now() < v_eligibility.window_start then
    raise exception using errcode = 'P0001', message = 'schedule_window_not_open';
  end if;
  if now() > v_eligibility.window_end then
    raise exception using errcode = 'P0001', message = 'schedule_window_locked';
  end if;

  v_path := v_user_id::text || '/' || v_eligibility.id::text || '/' || v_attempt_id::text || '.jpg';

  insert into public.schedule_completion_attempts (
    id,
    eligibility_id,
    user_id,
    begin_idempotency_key,
    object_path
  )
  values (
    v_attempt_id,
    v_eligibility.id,
    v_user_id,
    btrim(p_idempotency_key),
    v_path
  )
  returning * into v_attempt;

  return jsonb_build_object(
    'attempt_id', v_attempt.id,
    'eligibility_id', v_attempt.eligibility_id,
    'bucket_id', 'schedule-completion-proofs',
    'storage_path', v_attempt.object_path,
    'object_path', v_attempt.object_path,
    'content_type', 'image/jpeg',
    'max_bytes', 5242880,
    'window_end', v_eligibility.window_end,
    'upload_deadline', v_eligibility.window_end,
    'status', v_attempt.status,
    'idempotent_replay', false
  );
end;
$$;


--
-- Name: bootstrap_admin_by_email("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."bootstrap_admin_by_email"("p_email" "text", "p_role_code" "text" DEFAULT 'super_admin'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid;
begin
  if nullif(btrim(p_email), '') is null then
    raise exception 'ADMIN_EMAIL_REQUIRED' using errcode = '22023';
  end if;

  select id into v_user_id
  from public.users
  where lower(email) = lower(btrim(p_email))
  limit 1;

  if v_user_id is null then
    raise exception 'ADMIN_USER_NOT_FOUND' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.admin_roles where code = p_role_code and is_active = true
  ) then
    raise exception 'ADMIN_ROLE_NOT_FOUND' using errcode = '22023';
  end if;

  update public.users
  set
    app_access_mode = case
      when app_access_mode = 'admin' then 'admin'
      else 'both'
    end,
    updated_at = now()
  where id = v_user_id;

  insert into public.admin_user_roles (
    user_id,
    role_code,
    scope,
    is_active,
    granted_by,
    granted_at,
    revoked_at
  )
  values (
    v_user_id,
    p_role_code,
    'global',
    true,
    null,
    now(),
    null
  )
  on conflict (user_id, role_code, scope) do update
  set
    is_active = true,
    granted_by = null,
    granted_at = now(),
    revoked_at = null;

  return v_user_id;
end;
$$;


--
-- Name: can_access_schedule_proof_object("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."can_access_schedule_proof_object"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'storage', 'pg_temp'
    AS $$
  select
    split_part(coalesce(p_name, ''), '/', 1) = auth.uid()::text
    and exists (
      select 1
      from public.schedule_completion_attempts sca
      where sca.user_id = auth.uid()
        and sca.object_path = p_name
        and sca.status in ('begun', 'finalized', 'undone')
    )
$$;


--
-- Name: can_consume_quota("uuid", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."can_consume_quota"("p_user_id" "uuid", "p_feature_key" "text", "p_period_key" "text", "p_count" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with plan as (
    select public.current_plan_for_user(p_user_id) as plan_code
  ),
  rule as (
    select r.max_count
    from public.usage_quota_rules r
    join plan p on p.plan_code = r.plan_code
    where r.feature_key = p_feature_key
      and r.is_active = true
    order by
      case r.period_unit
        when 'none' then 0
        when 'day' then 1
        when 'month' then 2
        else 3
      end
    limit 1
  ),
  counter as (
    select used_count
    from public.usage_quota_counters
    where user_id = p_user_id
      and feature_key = p_feature_key
      and period_key = p_period_key
  )
  select case
    when not exists (select 1 from rule) then true
    when (select max_count from rule) is null then true
    else coalesce((select used_count from counter), 0) + p_count <= (select max_count from rule)
  end
$$;


--
-- Name: can_read_health_subject("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."can_read_health_subject"("p_subject_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.health_subjects hs
    where hs.id = p_subject_id
      and hs.is_active = true
      and (
        hs.owner_user_id = (select auth.uid())
        or hs.linked_user_id = (select auth.uid())
        or exists (
          select 1
          from public.family_members target_member
          join public.family_groups fg
            on fg.id = target_member.family_group_id
          left join public.family_members actor_member
            on actor_member.family_group_id = target_member.family_group_id
           and actor_member.user_id = (select auth.uid())
           and actor_member.status = 'active'
          where target_member.subject_id = hs.id
            and target_member.status = 'active'
            and fg.status = 'active'
            and (
              fg.owner_user_id = (select auth.uid())
              or actor_member.can_view = true
            )
        )
      )
  )
$$;


--
-- Name: can_write_health_subject("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."can_write_health_subject"("p_subject_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.health_subjects hs
    where hs.id = p_subject_id
      and hs.is_active = true
      and (
        hs.owner_user_id = (select auth.uid())
        or exists (
          select 1
          from public.family_members target_member
          join public.family_groups fg
            on fg.id = target_member.family_group_id
          join public.family_members actor_member
            on actor_member.family_group_id = target_member.family_group_id
           and actor_member.user_id = (select auth.uid())
           and actor_member.status = 'active'
          where target_member.subject_id = hs.id
            and target_member.status = 'active'
            and fg.status = 'active'
            and (
              fg.owner_user_id = (select auth.uid())
              or actor_member.can_edit = true
            )
        )
      )
  )
$$;


--
-- Name: cancel_my_membership_payment_request("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cancel_my_membership_payment_request"("p_payment_event_id" "uuid") RETURNS TABLE("payment_event_id" "uuid", "plan_code" "text", "billing_cycle" "text", "payer_full_name" "text", "status" "text", "can_cancel" boolean, "amount_cents" integer, "currency" "text", "transfer_reference" "text", "transfer_memo" "text", "bank_code" "text", "bank_name" "text", "bank_bin" "text", "bank_account_number" "text", "bank_account_name" "text", "bank_account_display_name" "text", "transfer_confirmed_at" timestamp with time zone, "review_reason" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_provider text := 'manual_membership_request';
  v_payment public.payment_events%rowtype;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select *
  into v_payment
  from public.payment_events pe
  where pe.id = p_payment_event_id
    and pe.payer_user_id = v_user_id
    and pe.provider = v_provider
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND' using errcode = '22023';
  end if;

  if v_payment.status = 'awaiting_transfer' then
    update public.payment_events
    set
      status = 'canceled',
      metadata = metadata || jsonb_build_object(
        'canceled_at', now(),
        'canceled_by_user_id', v_user_id,
        'cancellation_reason', 'user_canceled_before_transfer'
      )
    where id = v_payment.id
    returning * into v_payment;
  elsif v_payment.status <> 'canceled' then
    raise exception 'PAYMENT_CANCELLATION_NOT_ALLOWED'
      using errcode = '22023';
  end if;

  return query select
    v_payment.id,
    v_payment.plan_code::text,
    v_payment.metadata ->> 'billing_cycle',
    nullif(v_payment.metadata ->> 'payer_full_name', ''),
    v_payment.status,
    false,
    v_payment.amount_cents,
    v_payment.currency,
    v_payment.transfer_reference,
    v_payment.transfer_memo,
    nullif(v_payment.metadata #>> '{bank,bank_code}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_bin}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_number}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_display_name}', ''),
    nullif(v_payment.metadata ->> 'transfer_confirmed_at', '')::timestamptz,
    nullif(v_payment.review_reason, ''),
    v_payment.created_at;
end;
$$;


--
-- Name: check_personal_schedule_generation_quota("uuid", "text", "text", "text", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_personal_schedule_generation_quota"("p_user_id" "uuid", "p_request_id" "text", "p_feature_key" "text" DEFAULT 'personal_schedule_generation'::"text", "p_reset_timezone" "text" DEFAULT 'Asia/Ho_Chi_Minh'::"text", "p_requested_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("allowed" boolean, "used_count" integer, "limit_count" integer, "reset_at" timestamp with time zone, "reason_code" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.check_usage_quota(
    p_user_id,
    p_request_id,
    coalesce(nullif(p_feature_key, ''), 'personal_schedule_generation'),
    p_reset_timezone,
    p_requested_at
  )
$$;


--
-- Name: check_usage_quota("uuid", "text", "text", "text", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_usage_quota"("p_user_id" "uuid", "p_request_id" "text", "p_feature_key" "text", "p_reset_timezone" "text" DEFAULT 'Asia/Ho_Chi_Minh'::"text", "p_requested_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("allowed" boolean, "used_count" integer, "limit_count" integer, "reset_at" timestamp with time zone, "reason_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_plan public.nb_membership_plan;
  v_period_unit text;
  v_rule_timezone text;
  v_period_key text;
  v_used_count integer := 0;
begin
  if p_user_id is null or nullif(btrim(p_feature_key), '') is null then
    raise exception 'QUOTA_REQUEST_INVALID';
  end if;

  if v_actor is not null and v_actor <> p_user_id then
    raise exception 'QUOTA_USER_MISMATCH';
  end if;

  v_plan := public.current_plan_for_user(p_user_id);

  select r.period_unit, r.max_count, coalesce(nullif(r.reset_timezone, ''), p_reset_timezone)
    into v_period_unit, limit_count, v_rule_timezone
  from public.usage_quota_rules r
  where r.plan_code = v_plan
    and r.feature_key = p_feature_key
    and r.is_active = true
  order by
    case r.period_unit
      when 'none' then 0
      when 'day' then 1
      when 'month' then 2
      when 'lifetime' then 3
      else 4
    end
  limit 1;

  if not found or v_period_unit = 'none' or limit_count is null then
    return query select true, 0, null::integer, null::timestamptz, null::text;
    return;
  end if;

  v_period_key := public.usage_quota_period_key(
    v_period_unit,
    p_requested_at,
    v_rule_timezone
  );
  reset_at := public.usage_quota_reset_at(
    v_period_unit,
    p_requested_at,
    v_rule_timezone
  );

  select coalesce(uqc.used_count, 0)
    into v_used_count
  from public.usage_quota_counters uqc
  where uqc.user_id = p_user_id
    and uqc.feature_key = p_feature_key
    and uqc.period_key = v_period_key;

  v_used_count := coalesce(v_used_count, 0);
  used_count := v_used_count;
  allowed := v_used_count + 1 <= limit_count;
  reason_code := case when allowed then null else 'quota_exceeded' end;

  return next;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = "heap";

--
-- Name: nabi_notification_user_states; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."nabi_notification_user_states" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "notification_id" "text" NOT NULL,
    "content_version" integer NOT NULL,
    "source_event_id" "text" NOT NULL,
    "status" "text" NOT NULL,
    "eligible_at" timestamp with time zone NOT NULL,
    "presented_at" timestamp with time zone,
    "opened_at" timestamp with time zone,
    "deferred_until" timestamp with time zone,
    "actioned_at" timestamp with time zone,
    "converted_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "display_count" integer DEFAULT 0 NOT NULL,
    "dismiss_count" integer DEFAULT 0 NOT NULL,
    "primary_click_count" integer DEFAULT 0 NOT NULL,
    "secondary_click_count" integer DEFAULT 0 NOT NULL,
    "last_session_id" "text",
    "last_screen_key" "text",
    "membership_plan" "text",
    "billing_cycle" "text",
    "safe_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "nabi_notification_user_states_dismiss_count_check" CHECK (("dismiss_count" >= 0)),
    CONSTRAINT "nabi_notification_user_states_display_count_check" CHECK (("display_count" >= 0)),
    CONSTRAINT "nabi_notification_user_states_primary_click_count_check" CHECK (("primary_click_count" >= 0)),
    CONSTRAINT "nabi_notification_user_states_secondary_click_count_check" CHECK (("secondary_click_count" >= 0)),
    CONSTRAINT "nabi_notification_user_states_status_check" CHECK (("status" = ANY (ARRAY['eligible'::"text", 'queued'::"text", 'presented'::"text", 'collapsed'::"text", 'opened'::"text", 'deferred'::"text", 'actioned'::"text", 'converted'::"text", 'expired'::"text", 'cancelled'::"text", 'failed'::"text"])))
);


--
-- Name: claim_nabi_notification_occurrence("text", integer, "text", "text", timestamp with time zone, timestamp with time zone, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."claim_nabi_notification_occurrence"("p_notification_id" "text", "p_content_version" integer, "p_source_event_id" "text", "p_status" "text", "p_eligible_at" timestamp with time zone, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_safe_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."nabi_notification_user_states"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_state public.nabi_notification_user_states%rowtype;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if p_status not in ('eligible', 'queued') then
    raise exception 'INVALID_NOTIFICATION_STATE' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_notification_id, '')), '') is null
     or nullif(btrim(coalesce(p_source_event_id, '')), '') is null
     or p_content_version <= 0 then
    raise exception 'INVALID_NOTIFICATION_CLAIM' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.nabi_notification_definitions d
    where d.notification_id = btrim(p_notification_id)
      and d.content_version = p_content_version
      and d.status = 'active'
      and (d.effective_from is null or d.effective_from <= now())
      and (d.effective_until is null or d.effective_until > now())
  ) then
    raise exception 'NOTIFICATION_DEFINITION_INACTIVE' using errcode = '22023';
  end if;

  insert into public.nabi_notification_user_states (
    user_id, notification_id, content_version, source_event_id, status,
    eligible_at, expires_at, safe_metadata
  ) values (
    v_user_id, btrim(p_notification_id), p_content_version,
    btrim(p_source_event_id), p_status, p_eligible_at, p_expires_at,
    coalesce(p_safe_metadata, '{}'::jsonb)
  )
  on conflict (user_id, notification_id, source_event_id, content_version)
  do update set updated_at = public.nabi_notification_user_states.updated_at
  returning * into v_state;

  return v_state;
end;
$$;


--
-- Name: commit_personal_schedule_generation_quota("uuid", "text", "text", "text", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."commit_personal_schedule_generation_quota"("p_user_id" "uuid", "p_request_id" "text", "p_feature_key" "text" DEFAULT 'personal_schedule_generation'::"text", "p_reset_timezone" "text" DEFAULT 'Asia/Ho_Chi_Minh'::"text", "p_committed_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("committed" boolean, "used_count" integer, "limit_count" integer, "reset_at" timestamp with time zone, "reason_code" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.commit_usage_quota(
    p_user_id,
    p_request_id,
    coalesce(nullif(p_feature_key, ''), 'personal_schedule_generation'),
    p_reset_timezone,
    p_committed_at
  )
$$;


--
-- Name: commit_usage_quota("uuid", "text", "text", "text", timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."commit_usage_quota"("p_user_id" "uuid", "p_request_id" "text", "p_feature_key" "text", "p_reset_timezone" "text" DEFAULT 'Asia/Ho_Chi_Minh'::"text", "p_requested_at" timestamp with time zone DEFAULT "now"(), "p_count" integer DEFAULT 1) RETURNS TABLE("committed" boolean, "used_count" integer, "limit_count" integer, "reset_at" timestamp with time zone, "reason_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_decision record;
  v_plan public.nb_membership_plan;
  v_period_unit text := 'none';
  v_rule_timezone text := p_reset_timezone;
  v_period_key text := 'none';
  v_rows integer := 0;
begin
  if nullif(btrim(p_request_id), '') is null or p_count <= 0 then
    raise exception 'QUOTA_COMMIT_INVALID';
  end if;

  select *
    into v_decision
  from public.check_usage_quota(
    p_user_id,
    p_request_id,
    p_feature_key,
    p_reset_timezone,
    p_requested_at
  );

  if not coalesce(v_decision.allowed, false) then
    return query select
      false,
      v_decision.used_count,
      v_decision.limit_count,
      v_decision.reset_at,
      coalesce(v_decision.reason_code, 'quota_exceeded');
    return;
  end if;

  v_plan := public.current_plan_for_user(p_user_id);

  select r.period_unit, r.max_count, coalesce(nullif(r.reset_timezone, ''), p_reset_timezone)
    into v_period_unit, limit_count, v_rule_timezone
  from public.usage_quota_rules r
  where r.plan_code = v_plan
    and r.feature_key = p_feature_key
    and r.is_active = true
  order by
    case r.period_unit
      when 'none' then 0
      when 'day' then 1
      when 'month' then 2
      when 'lifetime' then 3
      else 4
    end
  limit 1;

  v_period_unit := coalesce(v_period_unit, 'none');
  v_period_key := public.usage_quota_period_key(
    v_period_unit,
    p_requested_at,
    v_rule_timezone
  );
  reset_at := public.usage_quota_reset_at(
    v_period_unit,
    p_requested_at,
    v_rule_timezone
  );

  insert into public.usage_events (
    user_id,
    feature_key,
    period_key,
    count_delta,
    idempotency_key,
    event_source,
    metadata
  )
  values (
    p_user_id,
    p_feature_key,
    v_period_key,
    p_count,
    p_request_id,
    'trusted_backend',
    jsonb_build_object('plan_code', v_plan)
  )
  on conflict (user_id, feature_key, idempotency_key) do nothing;

  get diagnostics v_rows = row_count;

  if v_rows > 0 and v_period_unit <> 'none' and limit_count is not null then
    insert into public.usage_quota_counters (
      user_id,
      feature_key,
      period_key,
      plan_code,
      used_count,
      limit_count,
      reset_at
    )
    values (
      p_user_id,
      p_feature_key,
      v_period_key,
      v_plan,
      p_count,
      limit_count,
      reset_at
    )
    on conflict (user_id, feature_key, period_key) do update
    set
      used_count = public.usage_quota_counters.used_count + excluded.used_count,
      plan_code = excluded.plan_code,
      limit_count = excluded.limit_count,
      reset_at = excluded.reset_at,
      updated_at = now();
  end if;

  if v_period_unit <> 'none' and limit_count is not null then
    select coalesce(uqc.used_count, 0)
      into used_count
    from public.usage_quota_counters uqc
    where uqc.user_id = p_user_id
      and uqc.feature_key = p_feature_key
      and uqc.period_key = v_period_key;
  else
    used_count := 0;
    limit_count := null;
    reset_at := null;
  end if;

  committed := true;
  reason_code := null;
  return next;
end;
$$;


--
-- Name: confirm_my_membership_payment_transfer("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."confirm_my_membership_payment_transfer"("p_payment_event_id" "uuid") RETURNS TABLE("payment_event_id" "uuid", "plan_code" "text", "billing_cycle" "text", "payer_full_name" "text", "status" "text", "can_cancel" boolean, "amount_cents" integer, "currency" "text", "transfer_reference" "text", "transfer_memo" "text", "bank_code" "text", "bank_name" "text", "bank_bin" "text", "bank_account_number" "text", "bank_account_name" "text", "bank_account_display_name" "text", "transfer_confirmed_at" timestamp with time zone, "review_reason" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_provider text := 'manual_membership_request';
  v_confirmed_at timestamptz;
  v_payment public.payment_events%rowtype;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select *
  into v_payment
  from public.payment_events pe
  where pe.id = p_payment_event_id
    and pe.payer_user_id = v_user_id
    and pe.provider = v_provider
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND' using errcode = '22023';
  end if;

  if v_payment.status = 'awaiting_transfer' then
    if v_payment.transfer_reference is null
      or v_payment.transfer_memo is distinct from v_payment.transfer_reference then
      raise exception 'PAYMENT_TRANSFER_DETAILS_MISSING' using errcode = '22023';
    end if;

    v_confirmed_at := now();
    update public.payment_events
    set
      status = 'pending_review',
      metadata = metadata || jsonb_build_object(
        'transfer_confirmed_at', v_confirmed_at,
        'transfer_confirmation', jsonb_build_object(
          'confirmed_at', v_confirmed_at,
          'confirmed_by_user_id', v_user_id,
          'transfer_reference', transfer_reference,
          'transfer_memo', transfer_memo,
          'bank', metadata -> 'bank'
        )
      )
    where id = v_payment.id
    returning * into v_payment;
  elsif v_payment.status <> 'pending_review' then
    raise exception 'PAYMENT_TRANSFER_NOT_AWAITING_CONFIRMATION'
      using errcode = '22023';
  end if;

  return query select
    v_payment.id,
    v_payment.plan_code::text,
    v_payment.metadata ->> 'billing_cycle',
    nullif(v_payment.metadata ->> 'payer_full_name', ''),
    v_payment.status,
    false,
    v_payment.amount_cents,
    v_payment.currency,
    v_payment.transfer_reference,
    v_payment.transfer_memo,
    nullif(v_payment.metadata #>> '{bank,bank_code}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_bin}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_number}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_display_name}', ''),
    nullif(v_payment.metadata ->> 'transfer_confirmed_at', '')::timestamptz,
    nullif(v_payment.review_reason, ''),
    v_payment.created_at;
end;
$$;


--
-- Name: consume_early_access_rate_limit("text", timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."consume_early_access_rate_limit"("p_ip_hash" "text", "p_window_started_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_request_count integer;
begin
  if p_ip_hash is null or p_ip_hash !~ '^[0-9a-f]{64}$'
     or p_window_started_at is null
     or mod(extract(epoch from p_window_started_at)::bigint, 3600) <> 0 then
    raise exception 'INVALID_EARLY_ACCESS_RATE_LIMIT_KEY' using errcode = '22023';
  end if;

  insert into early_access_private.rate_limits as rate_limits (
    ip_hash, window_started_at, request_count, expires_at
  ) values (
    p_ip_hash, p_window_started_at, 1, p_window_started_at + interval '23 hours 55 minutes'
  )
  on conflict (ip_hash, window_started_at) do update
    set request_count = rate_limits.request_count + 1,
        expires_at = excluded.expires_at
    where rate_limits.request_count < 10
  returning request_count into v_request_count;

  return v_request_count is not null;
end;
$_$;


--
-- Name: consume_member_phone_signup_rate_limit("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."consume_member_phone_signup_rate_limit"("p_ip_hash" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'private', 'auth', 'pg_temp'
    AS $_$
declare
  v_count integer;
  v_bucket timestamptz := date_trunc('hour', now());
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if coalesce(p_ip_hash, '') !~ '^[0-9a-f]{64}$' then
    return false;
  end if;

  delete from private.member_phone_signup_rate_limits
  where bucket_start < now() - interval '30 days';
  insert into private.member_phone_signup_rate_limits(
    key_hash, bucket_start, request_count
  ) values (
    'signup:' || p_ip_hash, v_bucket, 1
  )
  on conflict (key_hash, bucket_start) do update
    set request_count = private.member_phone_signup_rate_limits.request_count + 1
  returning request_count into v_count;
  return v_count <= 10;
end;
$_$;


--
-- Name: create_commission_records_for_payment("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_commission_records_for_payment"("p_payment_event_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_payment public.payment_events%rowtype;
  v_direct public.referral_relationships%rowtype;
  v_rate numeric(5, 4);
  v_base_cents integer;
begin
  select * into v_payment
  from public.payment_events
  where id = p_payment_event_id
    and status = 'succeeded'
    and paid_at is not null;

  if not found then
    return;
  end if;

  select * into v_direct
  from public.referral_relationships
  where referred_user_id = v_payment.payer_user_id
    and status = 'active'
  limit 1;

  if not found then
    return;
  end if;

  select rate into v_rate
  from public.commission_rates
  where code = 'direct_referral' and is_active = true;

  if v_rate is null then
    return;
  end if;

  v_base_cents := coalesce(
    v_payment.commission_base_cents,
    v_payment.list_price_cents,
    nullif(v_payment.metadata ->> 'commission_base_cents', '')::integer,
    nullif(v_payment.metadata ->> 'list_price_cents', '')::integer,
    v_payment.amount_cents
  );

  if exists (
    select 1 from public.sale_profiles
    where user_id = v_direct.referrer_user_id
      and status = 'active'
  ) then
    insert into public.commission_records (
      payment_event_id,
      receiver_user_id,
      payer_user_id,
      source_referral_id,
      rate,
      amount_cents,
      currency,
      status,
      available_at
    )
    values (
      v_payment.id,
      v_direct.referrer_user_id,
      v_payment.payer_user_id,
      v_direct.id,
      v_rate,
      round(v_base_cents * v_rate)::integer,
      v_payment.currency,
      'pending',
      coalesce(v_payment.paid_at, now()) + interval '24 hours'
    )
    on conflict (payment_event_id, receiver_user_id) do nothing;
  end if;
end;
$$;


--
-- Name: create_membership_payment_request("public"."nb_membership_plan", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_membership_payment_request"("p_plan_code" "public"."nb_membership_plan", "p_billing_cycle" "text", "p_idempotency_key" "text", "p_payer_full_name" "text") RETURNS TABLE("payment_event_id" "uuid", "plan_code" "text", "billing_cycle" "text", "payer_full_name" "text", "status" "text", "can_cancel" boolean, "amount_cents" integer, "currency" "text", "transfer_reference" "text", "transfer_memo" "text", "bank_code" "text", "bank_name" "text", "bank_bin" "text", "bank_account_number" "text", "bank_account_name" "text", "bank_account_display_name" "text", "transfer_confirmed_at" timestamp with time zone, "review_reason" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_price_config jsonb;
  v_bank_config jsonb;
  v_billing_cycle text;
  v_amount_cents integer;
  v_currency text;
  v_provider text := 'manual_membership_request';
  v_provider_event_id text;
  v_payer_full_name text;
  v_bank_code text;
  v_bank_name text;
  v_bank_bin text;
  v_bank_account_number text;
  v_bank_account_name text;
  v_bank_account_display_name text;
  v_transfer_reference text;
  v_transfer_memo text;
  v_attempt integer := 0;
  v_payment public.payment_events%rowtype;
  v_open_payment public.payment_events%rowtype;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  if p_plan_code not in ('plus', 'family_plus') then
    raise exception 'INVALID_MEMBERSHIP_PLAN' using errcode = '22023';
  end if;

  v_billing_cycle := lower(btrim(coalesce(p_billing_cycle, '')));
  if v_billing_cycle not in ('monthly', 'yearly') then
    raise exception 'INVALID_BILLING_CYCLE' using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode = '22023';
  end if;

  v_payer_full_name := btrim(coalesce(p_payer_full_name, ''));
  if v_payer_full_name = '' then
    raise exception 'PAYER_FULL_NAME_REQUIRED' using errcode = '22023';
  end if;

  -- Serialize create/retry/cancel transitions per payer. The partial unique
  -- index below remains the final concurrency backstop across sessions.
  perform 1
  from public.users u
  where u.id = v_user_id
  for update;

  if not found then
    raise exception 'USER_PROFILE_NOT_FOUND' using errcode = '22023';
  end if;

  v_provider_event_id := concat(v_user_id::text, ':', btrim(p_idempotency_key));

  select *
  into v_payment
  from public.payment_events pe
  where pe.provider = v_provider
    and pe.provider_event_id = v_provider_event_id
  for update;

  if found then
    update public.payment_events
    set metadata = metadata || jsonb_build_object('idempotent_replay', true)
    where id = v_payment.id
    returning * into v_payment;
  else
    select *
    into v_open_payment
    from public.payment_events pe
    where pe.payer_user_id = v_user_id
      and pe.provider = v_provider
      and pe.status in ('awaiting_transfer', 'pending_review')
    for update;

    if found then
      raise exception 'MEMBERSHIP_PAYMENT_REQUEST_ALREADY_OPEN'
        using errcode = 'P0001',
          hint = 'Load the current membership payment request instead of creating another one.';
    end if;

    select scv.config_value
    into v_price_config
    from public.system_config_versions scv
    where scv.config_key = 'membership_payment_prices'
      and scv.status = 'active'
    order by scv.created_at desc
    limit 1;

    v_amount_cents := nullif(
      v_price_config #>> array['prices', p_plan_code::text, v_billing_cycle],
      ''
    )::integer;
    v_currency := upper(coalesce(nullif(v_price_config ->> 'currency', ''), ''));

    if v_amount_cents is null or v_amount_cents <= 0 or v_currency <> 'VND' then
      raise exception 'MEMBERSHIP_PAYMENT_PRICE_NOT_CONFIGURED'
        using errcode = '22023';
    end if;

    select scv.config_value
    into v_bank_config
    from public.system_config_versions scv
    where scv.config_key = 'membership_payment_bank'
      and scv.status = 'active'
    order by scv.created_at desc
    limit 1;

    v_bank_code := upper(btrim(coalesce(v_bank_config ->> 'bank_code', '')));
    v_bank_name := btrim(coalesce(v_bank_config ->> 'bank_name', ''));
    v_bank_bin := btrim(coalesce(v_bank_config ->> 'bank_bin', ''));
    v_bank_account_number := btrim(
      coalesce(v_bank_config ->> 'bank_account_number', '')
    );
    v_bank_account_name := btrim(
      coalesce(v_bank_config ->> 'bank_account_name', '')
    );
    v_bank_account_display_name := btrim(
      coalesce(v_bank_config ->> 'bank_account_display_name', '')
    );

    if v_bank_code = ''
      or v_bank_name = ''
      or v_bank_bin !~ '^[0-9]{6}$'
      or v_bank_account_number !~ '^[0-9]{4,32}$'
      or v_bank_account_name = ''
      or v_bank_account_display_name = '' then
      raise exception 'MEMBERSHIP_PAYMENT_BANK_NOT_CONFIGURED'
        using errcode = '22023';
    end if;

    loop
      v_attempt := v_attempt + 1;
      v_transfer_reference := concat(
        'NB',
        upper(encode(extensions.gen_random_bytes(6), 'hex'))
      );
      -- VietQR content must be the immutable NB reconciliation key only.
      v_transfer_memo := v_transfer_reference;

      begin
        insert into public.payment_events (
          payer_user_id,
          plan_code,
          provider,
          provider_event_id,
          amount_cents,
          list_price_cents,
          commission_base_cents,
          currency,
          status,
          transfer_reference,
          transfer_memo,
          idempotency_key,
          metadata
        )
        values (
          v_user_id,
          p_plan_code,
          v_provider,
          v_provider_event_id,
          v_amount_cents,
          v_amount_cents,
          v_amount_cents,
          v_currency,
          'awaiting_transfer',
          v_transfer_reference,
          v_transfer_memo,
          btrim(p_idempotency_key),
          jsonb_build_object(
            'billing_cycle', v_billing_cycle,
            'payer_full_name', v_payer_full_name,
            'manual_approval_required', true,
            'grants_access_before_approval', false,
            'transfer_reference', v_transfer_reference,
            'transfer_memo', v_transfer_memo,
            'transfer_memo_contract', 'reference_only_v2',
            'bank', jsonb_build_object(
              'bank_code', v_bank_code,
              'bank_name', v_bank_name,
              'bank_bin', v_bank_bin,
              'bank_account_number', v_bank_account_number,
              'bank_account_name', v_bank_account_name,
              'bank_account_display_name', v_bank_account_display_name
            )
          )
        )
        returning * into v_payment;
        exit;
      exception
        when unique_violation then
          -- The user row lock makes an open-request conflict impossible here;
          -- this loop only retries an extremely unlikely NB reference collision.
          select *
          into v_payment
          from public.payment_events pe
          where pe.provider = v_provider
            and pe.provider_event_id = v_provider_event_id
          for update;

          if found then
            update public.payment_events
            set metadata = metadata || jsonb_build_object('idempotent_replay', true)
            where id = v_payment.id
            returning * into v_payment;
            exit;
          end if;

          if v_attempt >= 5 then
            raise;
          end if;
      end;
    end loop;
  end if;

  return query select
    v_payment.id,
    v_payment.plan_code::text,
    coalesce(v_payment.metadata ->> 'billing_cycle', v_billing_cycle),
    nullif(v_payment.metadata ->> 'payer_full_name', ''),
    v_payment.status,
    v_payment.status = 'awaiting_transfer',
    v_payment.amount_cents,
    v_payment.currency,
    v_payment.transfer_reference,
    v_payment.transfer_memo,
    nullif(v_payment.metadata #>> '{bank,bank_code}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_bin}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_number}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_display_name}', ''),
    nullif(v_payment.metadata ->> 'transfer_confirmed_at', '')::timestamptz,
    nullif(v_payment.review_reason, ''),
    v_payment.created_at;
end;
$_$;


--
-- Name: create_sale_point_reversal_for_payment("uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."create_sale_point_reversal_for_payment"("p_payment_event_id" "uuid", "p_decision" "text", "p_reason" "text", "p_idempotency_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_record record;
begin
  for v_record in
    select
      cr.id,
      cr.receiver_user_id,
      cr.amount_cents,
      cr.currency
    from public.commission_records cr
    where cr.payment_event_id = p_payment_event_id
      and cr.amount_cents > 0
  loop
    insert into public.sale_point_adjustments (
      sale_user_id,
      point_delta_cents,
      currency,
      reason,
      reviewed_by,
      idempotency_key,
      metadata
    )
    values (
      v_record.receiver_user_id,
      -v_record.amount_cents,
      v_record.currency,
      btrim(p_reason),
      auth.uid(),
      concat('sale-reversal-', v_record.id::text),
      jsonb_build_object(
        'payment_event_id',
        p_payment_event_id,
        'commission_record_id',
        v_record.id,
        'reversal_decision',
        p_decision,
        'ledger_policy',
        'negative_adjustment_without_overwriting_commission'
      )
    )
    on conflict (idempotency_key) do nothing;
  end loop;
end;
$$;


--
-- Name: current_plan_for_user("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."current_plan_for_user"("p_user_id" "uuid") RETURNS "public"."nb_membership_plan"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    (
      select ms.plan_code
      from public.membership_subscriptions ms
      where ms.user_id = p_user_id
        and ms.status in ('trialing', 'active')
        and ms.starts_at <= now()
        and (ms.ends_at is null or ms.ends_at > now())
      order by
        case ms.plan_code
          when 'family_plus' then 3
          when 'plus' then 2
          else 1
        end desc,
        ms.starts_at desc
      limit 1
    ),
    'free'::public.nb_membership_plan
  )
$$;


--
-- Name: current_wellness_reward_program(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."current_wellness_reward_program"() RETURNS TABLE("program_config_id" "uuid", "contract_version" "text", "reward_points" integer, "expiry_days" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_config public.system_config_versions%rowtype;
  v_expiry_text text;
begin
  select * into v_config
  from public.system_config_versions scv
  where scv.config_key = 'wellness_reward_program'
    and scv.status = 'active'
  order by scv.created_at desc
  limit 1;

  if v_config.id is null then
    raise exception using errcode = 'P0001', message = 'reward_program_not_configured';
  end if;

  v_expiry_text := v_config.config_value ->> 'expiry_days';
  if coalesce(v_expiry_text, '') !~ '^[0-9]{1,4}$'
     or v_expiry_text::integer not between 1 and 3650 then
    raise exception using errcode = 'P0001', message = 'reward_program_invalid';
  end if;

  return query select
    v_config.id,
    coalesce(nullif(v_config.config_value ->> 'contract_version', ''), 'wellness_schedule_v2'),
    10,
    v_expiry_text::integer;
end;
$_$;


--
-- Name: default_self_subject_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."default_self_subject_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select hs.id
  from public.health_subjects hs
  where hs.owner_user_id = (select auth.uid())
    and hs.subject_type = 'self'
    and hs.is_active = true
  limit 1
$$;


--
-- Name: delete_sleep_safety_contact("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."delete_sleep_safety_contact"("p_contact_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'authentication_required';
  end if;
  delete from public.sleep_safety_contacts
  where id = p_contact_id and user_id = v_uid;
end;
$$;


--
-- Name: familyplus_context_for_user("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."familyplus_context_for_user"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_group public.family_groups%rowtype;
  v_self_subject_id uuid;
  v_has_familyplus boolean;
  v_members jsonb := '[]'::jsonb;
begin
  select exists (
    select 1
    from public.membership_subscriptions ms
    where ms.user_id = p_user_id
      and ms.plan_code = 'family_plus'
      and ms.status = 'active'
      and (ms.ends_at is null or ms.ends_at > now())
  ) into v_has_familyplus;

  select hs.id into v_self_subject_id
  from public.health_subjects hs
  where hs.owner_user_id = p_user_id
    and hs.subject_type = 'self'
    and hs.is_active = true
  limit 1;

  select * into v_group
  from public.family_groups fg
  where fg.owner_user_id = p_user_id
    and fg.status = 'active'
  order by fg.created_at desc
  limit 1;

  if v_group.id is not null then
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'id', fm.id,
        'family_group_id', fm.family_group_id,
        'subject_id', fm.subject_id,
        'user_id', fm.user_id,
        'display_name', fm.display_name,
        'role', fm.role,
        'status', fm.status,
        'can_view', fm.can_view,
        'can_edit', fm.can_edit
      )
      order by fm.created_at asc
    ), '[]'::jsonb)
    into v_members
    from public.family_members fm
    where fm.family_group_id = v_group.id;
  end if;

  return jsonb_build_object(
    'actor_id', p_user_id,
    'self_subject_id', v_self_subject_id,
    'has_family_plus', coalesce(v_has_familyplus, false),
    'group', case when v_group.id is null then null else jsonb_build_object(
      'id', v_group.id,
      'owner_user_id', v_group.owner_user_id,
      'display_name', v_group.display_name,
      'status', v_group.status
    ) end,
    'members', v_members,
    'selected_subject_id', v_self_subject_id
  );
end;
$$;


--
-- Name: finalize_google_play_purchase("uuid", "text", "text", "text", "text", "text", timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."finalize_google_play_purchase"("p_user_id" "uuid", "p_package_name" "text", "p_product_id" "text", "p_purchase_token_hash" "text", "p_order_id" "text", "p_purchase_state" "text", "p_purchase_started_at" timestamp with time zone, "p_entitlement_ends_at" timestamp with time zone, "p_acknowledged" boolean DEFAULT false) RETURNS TABLE("status" "text", "plan_code" "public"."nb_membership_plan", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_plan public.nb_membership_plan;
  v_ledger public.google_play_purchase_ledger%rowtype;
  v_provider_subscription_id text;
begin
  if p_user_id is null
     or nullif(btrim(p_package_name), '') is null
     or nullif(btrim(p_product_id), '') is null
     or nullif(btrim(p_purchase_token_hash), '') is null
     or nullif(btrim(p_purchase_state), '') is null then
    raise exception using errcode = '22023', message = 'INVALID_GOOGLE_PLAY_PURCHASE';
  end if;

  if p_package_name <> 'com.nanobioai.app' then
    raise exception using errcode = '22023', message = 'GOOGLE_PLAY_PACKAGE_MISMATCH';
  end if;

  v_plan := case p_product_id
    when 'nanobio_plus_monthly' then 'plus'::public.nb_membership_plan
    when 'nanobio_plus_yearly' then 'plus'::public.nb_membership_plan
    when 'nanobio_family_plus_monthly' then 'family_plus'::public.nb_membership_plan
    when 'nanobio_family_plus_yearly' then 'family_plus'::public.nb_membership_plan
    else null
  end;
  if v_plan is null then
    raise exception using errcode = '22023', message = 'GOOGLE_PLAY_PRODUCT_UNKNOWN';
  end if;

  select * into v_ledger
  from public.google_play_purchase_ledger
  where provider = 'google_play'
    and purchase_token_hash = p_purchase_token_hash
  for update;

  if found and v_ledger.user_id is not null and v_ledger.user_id <> p_user_id then
    raise exception using errcode = '42501', message = 'GOOGLE_PLAY_PURCHASE_USER_MISMATCH';
  end if;

  if found and v_ledger.verification_status = 'verified' then
    return query select
      'verified'::text,
      case
        when coalesce(v_ledger.product_id, p_product_id) like 'nanobio_family_plus_%'
          then 'family_plus'::public.nb_membership_plan
        else v_plan
      end,
      v_ledger.entitlement_ends_at;
    return;
  end if;

  insert into public.google_play_purchase_ledger (
    user_id,
    package_name,
    product_id,
    purchase_token_hash,
    order_id,
    purchase_state,
    verification_status,
    purchase_started_at,
    entitlement_ends_at,
    acknowledged
  ) values (
    p_user_id,
    p_package_name,
    p_product_id,
    p_purchase_token_hash,
    nullif(btrim(p_order_id), ''),
    p_purchase_state,
    case
      when p_purchase_state = 'verified' then 'verified'
      when p_purchase_state = 'pending' then 'pending'
      else 'rejected'
    end,
    p_purchase_started_at,
    p_entitlement_ends_at,
    coalesce(p_acknowledged, false)
  )
  on conflict (provider, purchase_token_hash) do update set
    user_id = excluded.user_id,
    package_name = excluded.package_name,
    product_id = excluded.product_id,
    order_id = coalesce(excluded.order_id, public.google_play_purchase_ledger.order_id),
    purchase_state = excluded.purchase_state,
    verification_status = excluded.verification_status,
    purchase_started_at = excluded.purchase_started_at,
    entitlement_ends_at = excluded.entitlement_ends_at,
    acknowledged = excluded.acknowledged,
    updated_at = now()
  returning * into v_ledger;

  if p_purchase_state = 'verified' then
    v_provider_subscription_id := 'google-play:' || p_purchase_token_hash;
    insert into public.membership_subscriptions (
      user_id,
      plan_code,
      status,
      source,
      starts_at,
      ends_at,
      current_period_start,
      current_period_end,
      provider,
      provider_subscription_id,
      metadata
    ) values (
      p_user_id,
      v_plan,
      'active',
      'payment_provider',
      coalesce(p_purchase_started_at, now()),
      p_entitlement_ends_at,
      coalesce(p_purchase_started_at, now()),
      p_entitlement_ends_at,
      'google_play',
      v_provider_subscription_id,
      jsonb_build_object('product_id', p_product_id, 'order_id', nullif(btrim(p_order_id), ''))
    )
    on conflict (provider, provider_subscription_id) do update set
      plan_code = excluded.plan_code,
      status = excluded.status,
      ends_at = excluded.ends_at,
      current_period_start = excluded.current_period_start,
      current_period_end = excluded.current_period_end,
      metadata = excluded.metadata,
      updated_at = now();

    return query select 'verified'::text, v_plan, p_entitlement_ends_at;
    return;
  end if;

  if p_purchase_state in ('canceled', 'expired', 'refunded', 'revoked') then
    update public.membership_subscriptions
    set
      status = case
        when p_purchase_state = 'expired' then 'expired'
        else 'canceled'
      end,
      ends_at = least(coalesce(ends_at, now()), now()),
      current_period_end = least(coalesce(current_period_end, now()), now()),
      updated_at = now()
    where provider = 'google_play'
      and provider_subscription_id = 'google-play:' || p_purchase_token_hash;
    return query select 'rejected'::text, v_plan, p_entitlement_ends_at;
    return;
  end if;

  return query select 'pending'::text, v_plan, p_entitlement_ends_at;
end;
$$;


--
-- Name: finalize_my_schedule_completion("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."finalize_my_schedule_completion"("p_attempt_id" "uuid", "p_storage_path" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'storage', 'pg_temp'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_attempt public.schedule_completion_attempts%rowtype;
  v_eligibility public.schedule_reward_eligibilities%rowtype;
  v_object storage.objects%rowtype;
  v_proof public.schedule_completion_proofs%rowtype;
  v_allocation public.wellness_point_allocations%rowtype;
  v_wallet public.wellness_reward_wallets%rowtype;
  v_program record;
  v_ledger_id uuid := gen_random_uuid();
  v_allocation_id uuid := gen_random_uuid();
  v_size_text text;
  v_content_type text;
  v_byte_size integer;
  v_reward_status text;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  if not public.wellness_rewards_feature_enabled() then
    raise exception using errcode = 'P0001', message = 'wellness_rewards_disabled';
  end if;
  if p_attempt_id is null then
    raise exception using errcode = 'P0001', message = 'completion_attempt_required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;
  if nullif(btrim(coalesce(p_storage_path, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'storage_path_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:finalize:' || v_user_id::text || ':' || btrim(p_idempotency_key),
    0
  ));

  if exists (
    select 1
    from public.schedule_completion_attempts sca
    where sca.user_id = v_user_id
      and sca.finalize_idempotency_key = btrim(p_idempotency_key)
      and sca.id <> p_attempt_id
  ) then
    raise exception using errcode = 'P0001', message = 'idempotency_conflict';
  end if;

  select * into v_attempt
  from public.schedule_completion_attempts sca
  where sca.id = p_attempt_id
    and sca.user_id = v_user_id
  for update;

  if v_attempt.id is null then
    raise exception using errcode = 'P0001', message = 'completion_attempt_not_found';
  end if;
  if v_attempt.object_path <> btrim(p_storage_path) then
    raise exception using errcode = 'P0001', message = 'storage_path_mismatch';
  end if;

  select * into v_eligibility
  from public.schedule_reward_eligibilities sre
  where sre.id = v_attempt.eligibility_id
    and sre.user_id = v_user_id
  for update;

  if v_attempt.status = 'finalized' then
    if v_attempt.finalize_idempotency_key <> btrim(p_idempotency_key) then
      raise exception using errcode = 'P0001', message = 'schedule_already_completed';
    end if;

    select * into v_proof
    from public.schedule_completion_proofs scp
    where scp.attempt_id = v_attempt.id;

    select * into v_allocation
    from public.wellness_point_allocations wpa
    where wpa.source_type = 'schedule_reward'
      and wpa.source_id = v_attempt.id;

    perform public.refresh_wellness_reward_wallet(v_user_id);
    select * into v_wallet
    from public.wellness_reward_wallets where user_id = v_user_id;

    return jsonb_build_object(
      'attempt_id', v_attempt.id,
      'eligibility_id', v_attempt.eligibility_id,
      'proof_id', v_proof.id,
      'proof_status', v_proof.status,
      'reward_points', v_allocation.original_points,
      'points_delta', v_allocation.original_points,
      'reward_status', v_allocation.status,
      'available_at', v_allocation.available_at,
      'expires_at', v_allocation.expires_at,
      'pending_points', v_wallet.pending_points,
      'available_points', v_wallet.available_points,
      'idempotent_replay', true
    );
  end if;

  if v_eligibility.id is null then
    raise exception using errcode = 'P0001', message = 'eligibility_not_available';
  end if;
  if exists (
    select 1
    from public.wellness_point_allocations wpa
    where wpa.eligibility_id = v_eligibility.id
  ) then
    raise exception using errcode = 'P0001', message = 'eligibility_reward_already_awarded';
  end if;
  if v_eligibility.status <> 'eligible' then
    raise exception using errcode = 'P0001', message = 'eligibility_not_available';
  end if;
  if v_attempt.status <> 'begun' then
    raise exception using errcode = 'P0001', message = 'completion_attempt_not_active';
  end if;

  select * into v_object
  from storage.objects so
  where so.bucket_id = 'schedule-completion-proofs'
    and so.name = v_attempt.object_path
  limit 1;

  if v_object.id is null then
    raise exception using errcode = 'P0001', message = 'proof_not_uploaded';
  end if;
  if v_object.created_at < greatest(v_attempt.began_at, v_eligibility.window_start)
     or v_object.created_at > v_eligibility.window_end then
    raise exception using errcode = 'P0001', message = 'proof_upload_outside_window';
  end if;

  v_content_type := lower(coalesce(
    v_object.metadata ->> 'mimetype',
    v_object.metadata ->> 'contentType',
    ''
  ));
  v_size_text := coalesce(v_object.metadata ->> 'size', '');

  if v_content_type <> 'image/jpeg' then
    raise exception using errcode = 'P0001', message = 'proof_content_type_invalid';
  end if;
  if v_size_text !~ '^[0-9]{1,7}$' then
    raise exception using errcode = 'P0001', message = 'proof_size_invalid';
  end if;
  v_byte_size := v_size_text::integer;
  if v_byte_size < 1 or v_byte_size > 5242880 then
    raise exception using errcode = 'P0001', message = 'proof_size_invalid';
  end if;

  select * into v_program
  from public.current_wellness_reward_program();

  perform public.refresh_wellness_reward_wallet(v_user_id);
  select * into v_wallet
  from public.wellness_reward_wallets
  where user_id = v_user_id
  for update;

  v_reward_status := case
    when now() > v_eligibility.window_end then 'available'
    else 'pending'
  end;

  insert into public.schedule_completion_proofs (
    eligibility_id,
    attempt_id,
    user_id,
    object_path,
    content_type,
    byte_size,
    captured_at,
    uploaded_at
  )
  values (
    v_eligibility.id,
    v_attempt.id,
    v_user_id,
    v_attempt.object_path,
    v_content_type,
    v_byte_size,
    greatest(
      v_attempt.began_at,
      v_eligibility.window_start,
      v_object.created_at
    ),
    v_object.created_at
  )
  returning * into v_proof;

  insert into public.wellness_point_ledgers (
    id,
    user_id,
    subject_id,
    source_type,
    source_id,
    schedule_date,
    points_delta,
    program_code,
    idempotency_key,
    event_type,
    status,
    title,
    is_redeemable,
    available_at,
    expires_at,
    program_config_id,
    eligibility_id,
    metadata
  )
  values (
    v_ledger_id,
    v_user_id,
    v_eligibility.subject_id,
    'schedule_completion_attempt',
    v_attempt.id,
    v_eligibility.schedule_date,
    v_program.reward_points,
    v_program.contract_version,
    'schedule_reward:' || v_attempt.id::text,
    'schedule_award',
    v_reward_status,
    'Hoàn thành nhiệm vụ: ' || v_eligibility.title_snapshot,
    true,
    v_eligibility.window_end,
    v_eligibility.window_end + make_interval(days => v_program.expiry_days),
    v_program.program_config_id,
    v_eligibility.id,
    jsonb_build_object(
      'attempt_id', v_attempt.id,
      'proof_id', v_proof.id,
      'client_idempotency_key', btrim(p_idempotency_key)
    )
  );

  insert into public.wellness_point_allocations (
    id,
    user_id,
    subject_id,
    ledger_id,
    eligibility_id,
    source_type,
    source_id,
    original_points,
    remaining_points,
    status,
    available_at,
    expires_at,
    program_config_id
  )
  values (
    v_allocation_id,
    v_user_id,
    v_eligibility.subject_id,
    v_ledger_id,
    v_eligibility.id,
    'schedule_reward',
    v_attempt.id,
    v_program.reward_points,
    v_program.reward_points,
    v_reward_status,
    v_eligibility.window_end,
    v_eligibility.window_end + make_interval(days => v_program.expiry_days),
    v_program.program_config_id
  )
  returning * into v_allocation;

  update public.wellness_reward_wallets
  set
    pending_points = pending_points + case when v_reward_status = 'pending' then v_program.reward_points else 0 end,
    available_points = available_points + case when v_reward_status = 'available' then v_program.reward_points else 0 end,
    lifetime_earned_points = lifetime_earned_points + v_program.reward_points,
    lock_version = lock_version + 1,
    updated_at = now()
  where user_id = v_user_id
  returning * into v_wallet;

  update public.schedule_completion_attempts
  set
    finalize_idempotency_key = btrim(p_idempotency_key),
    status = 'finalized',
    finalized_at = now(),
    updated_at = now()
  where id = v_attempt.id;

  update public.schedule_reward_eligibilities
  set status = 'completed', updated_at = now()
  where id = v_eligibility.id;

  update public.lifestyle_schedule_items
  set
    is_completed = true,
    current_value = greatest(current_value, target_value),
    updated_at = now()
  where id = v_eligibility.schedule_item_id
    and user_id = v_user_id;

  return jsonb_build_object(
    'attempt_id', v_attempt.id,
    'eligibility_id', v_eligibility.id,
    'proof_id', v_proof.id,
    'proof_status', v_proof.status,
    'reward_points', v_allocation.original_points,
    'points_delta', v_allocation.original_points,
    'reward_status', v_allocation.status,
    'available_at', v_allocation.available_at,
    'expires_at', v_allocation.expires_at,
    'pending_points', v_wallet.pending_points,
    'available_points', v_wallet.available_points,
    'idempotent_replay', false
  );
end;
$_$;


--
-- Name: finalize_my_schedule_health_checkin("jsonb", "text", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."finalize_my_schedule_health_checkin"("p_item" "jsonb", "p_action_type" "text", "p_checkin" "jsonb", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_subject_id uuid;
  v_item_id uuid;
  v_item public.lifestyle_schedule_items%rowtype;
  v_eligibility public.schedule_reward_eligibilities%rowtype;
  v_checkin public.schedule_health_checkins%rowtype;
  v_existing_checkin public.schedule_health_checkins%rowtype;
  v_allocation public.wellness_point_allocations%rowtype;
  v_wallet public.wellness_reward_wallets%rowtype;
  v_program record;
  v_action text := btrim(coalesce(p_action_type, ''));
  v_idempotency text := btrim(coalesce(p_idempotency_key, ''));
  v_source_type text;
  v_source_id text;
  v_category text;
  v_window_start timestamptz;
  v_window_end timestamptz;
  v_points integer;
  v_reward_status text := 'pending';
  v_ledger_id uuid := gen_random_uuid();
  v_allocation_id uuid := gen_random_uuid();
  v_checkin_id uuid := gen_random_uuid();
  v_amount_ml integer;
  v_stress integer;
  v_sleep double precision;
  v_weight double precision;
  v_mood text;
  v_manual_count integer;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  if not public.wellness_rewards_feature_enabled() then
    raise exception using errcode = 'P0001', message = 'wellness_rewards_disabled';
  end if;
  if jsonb_typeof(p_item) <> 'object'
     or jsonb_typeof(coalesce(p_checkin, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
  end if;
  if v_idempotency = '' then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;

  v_points := public.schedule_health_action_reward_points(v_action);
  if v_points <= 0 then
    raise exception using errcode = 'P0001', message = 'health_action_not_rewardable';
  end if;

  begin
    v_item_id := (p_item ->> 'schedule_item_id')::uuid;
  exception when others then
    raise exception using errcode = 'P0001', message = 'schedule_item_id_invalid';
  end;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:health-checkin:' || v_user_id::text || ':' || v_item_id::text,
    0
  ));

  select * into v_checkin
  from public.schedule_health_checkins shc
  where shc.user_id = v_user_id
    and shc.idempotency_key = v_idempotency;

  if v_checkin.id is not null then
    if v_checkin.schedule_item_id <> v_item_id or v_checkin.action_type <> v_action then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    perform public.refresh_wellness_reward_wallet(v_user_id);
    select * into v_wallet
    from public.wellness_reward_wallets where user_id = v_user_id;
    select * into v_allocation
    from public.wellness_point_allocations wpa
    where wpa.source_type = 'schedule_reward'
      and wpa.source_id = v_checkin.id;
    return jsonb_build_object(
      'checkin_id', v_checkin.id,
      'schedule_item_id', v_item_id,
      'points_delta', case when v_checkin.status = 'active' then v_checkin.reward_points else 0 end,
      'reward_status', case
        when v_checkin.status = 'reversed' then 'reversed'
        else coalesce(v_allocation.status, 'pending')
      end,
      'pending_points', coalesce(v_wallet.pending_points, 0),
      'available_points', coalesce(v_wallet.available_points, 0),
      'idempotent_replay', true
    );
  end if;

  select * into v_item
  from public.lifestyle_schedule_items lsi
  where lsi.id = v_item_id
    and lsi.user_id = v_user_id
  for update;

  v_source_type := btrim(coalesce(p_item ->> 'source_type', ''));
  v_source_id := nullif(btrim(coalesce(p_item ->> 'source_id', '')), '');
  v_category := btrim(coalesce(p_item ->> 'category', ''));

  -- Manual tasks are local-first. The reward RPC may race the mobile snapshot,
  -- so it can create only the single validated occurrence that is being completed.
  if v_item.id is null then
    if v_source_type <> 'manual_health_task' then
      raise exception using errcode = 'P0001', message = 'schedule_item_not_found';
    end if;
    if v_source_id is null
       or v_source_id !~ '^manual_health\\|[0-9a-fA-F-]{36}\\|(quick_complete|hydration|mood_stress|sleep_checkin|weight_checkin)\\|[01]\\|(once|daily|weekdays|weekends)$'
       or split_part(v_source_id, '|', 3) <> v_action then
      raise exception using errcode = 'P0001', message = 'manual_health_task_invalid';
    end if;
    if v_category not in ('routine', 'water', 'body', 'mind', 'brain', 'sleep', 'metric') then
      raise exception using errcode = 'P0001', message = 'manual_health_task_invalid';
    end if;

    select hs.id into v_subject_id
    from public.health_subjects hs
    where hs.owner_user_id = v_user_id
      and hs.subject_type = 'self'
      and hs.is_active = true
    limit 1;

    if v_subject_id is null then
      raise exception using errcode = 'P0001', message = 'health_subject_required';
    end if;

    begin
      insert into public.lifestyle_schedule_items (
        id, user_id, subject_id, schedule_date, start_time, end_time,
        title, description, category, source_type, source_id,
        target_value, current_value, unit, is_completed, sort_order,
        ai_generated, encouragement
      ) values (
        v_item_id,
        v_user_id,
        v_subject_id,
        (p_item ->> 'schedule_date')::date,
        (p_item ->> 'start_time')::time,
        nullif(p_item ->> 'end_time', '')::time,
        left(btrim(coalesce(p_item ->> 'title', 'Nhiệm vụ chăm sóc')), 120),
        left(coalesce(p_item ->> 'description', ''), 500),
        v_category,
        'manual_health_task',
        v_source_id,
        greatest(coalesce(nullif(p_item ->> 'target_value', '')::numeric, 1), 1),
        0,
        left(coalesce(nullif(p_item ->> 'unit', ''), 'lần'), 30),
        false,
        900,
        false,
        ''
      );
    exception when others then
      raise exception using errcode = 'P0001', message = 'manual_health_task_invalid';
    end;

    select * into v_item
    from public.lifestyle_schedule_items lsi
    where lsi.id = v_item_id and lsi.user_id = v_user_id
    for update;
  end if;

  v_subject_id := v_item.subject_id;
  if v_subject_id is null then
    raise exception using errcode = 'P0001', message = 'health_subject_required';
  end if;

  if v_item.source_type in ('meal_plan', 'exercise_task') then
    raise exception using errcode = 'P0001', message = 'photo_proof_required';
  end if;

  if v_item.source_type = 'manual_health_task' then
    if v_item.source_id is null
       or v_item.source_id !~ '^manual_health\\|[0-9a-fA-F-]{36}\\|(quick_complete|hydration|mood_stress|sleep_checkin|weight_checkin)\\|[01]\\|(once|daily|weekdays|weekends)$'
       or split_part(v_item.source_id, '|', 3) <> v_action then
      raise exception using errcode = 'P0001', message = 'health_action_mismatch';
    end if;
  else
    if v_action = 'hydration' and v_item.category <> 'water' then
      raise exception using errcode = 'P0001', message = 'health_action_mismatch';
    end if;
    if v_action <> 'hydration' and v_action <> 'quick_complete' then
      raise exception using errcode = 'P0001', message = 'health_action_mismatch';
    end if;
    if v_action = 'quick_complete'
       and v_item.category not in ('routine', 'mind', 'brain', 'body', 'sleep') then
      raise exception using errcode = 'P0001', message = 'health_action_mismatch';
    end if;
  end if;

  if v_action = 'hydration' then
    if jsonb_typeof(p_checkin -> 'amount_ml') <> 'number' then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
    v_amount_ml := (p_checkin ->> 'amount_ml')::integer;
    if v_amount_ml < 50 or v_amount_ml > 2000 then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
  elsif v_action = 'mood_stress' then
    v_mood := btrim(coalesce(p_checkin ->> 'mood', ''));
    if v_mood not in ('very_good', 'good', 'neutral', 'tired', 'stressed')
       or jsonb_typeof(p_checkin -> 'stress_level') <> 'number' then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
    v_stress := (p_checkin ->> 'stress_level')::integer;
    if v_stress < 1 or v_stress > 5 then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
  elsif v_action = 'sleep_checkin' then
    if jsonb_typeof(p_checkin -> 'sleep_hours') <> 'number' then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
    v_sleep := (p_checkin ->> 'sleep_hours')::double precision;
    if v_sleep < 0 or v_sleep > 24 then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
  elsif v_action = 'weight_checkin' then
    if jsonb_typeof(p_checkin -> 'weight_kg') <> 'number' then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
    v_weight := (p_checkin ->> 'weight_kg')::double precision;
    if v_weight < 20 or v_weight > 500 then
      raise exception using errcode = 'P0001', message = 'health_checkin_invalid';
    end if;
  end if;

  v_window_start := ((v_item.schedule_date + v_item.start_time) at time zone 'Asia/Ho_Chi_Minh');
  v_window_end := v_window_start + interval '30 minutes';
  if now() < v_window_start then
    raise exception using errcode = 'P0001', message = 'schedule_window_not_open';
  end if;
  if now() > v_window_end then
    raise exception using errcode = 'P0001', message = 'schedule_window_locked';
  end if;

  select * into v_existing_checkin
  from public.schedule_health_checkins shc
  where shc.user_id = v_user_id
    and shc.schedule_item_id = v_item.id
    and shc.status = 'active'
  for update;

  if v_existing_checkin.id is not null then
    raise exception using errcode = 'P0001', message = 'health_checkin_already_recorded';
  end if;

  if v_item.source_type <> 'manual_health_task' then
    select * into v_eligibility
    from public.schedule_reward_eligibilities sre
    where sre.user_id = v_user_id
      and sre.schedule_item_id = v_item.id
    for update;

    if v_eligibility.id is null then
      raise exception using errcode = 'P0001', message = 'eligibility_not_found';
    end if;
    if v_eligibility.status <> 'eligible' then
      raise exception using errcode = 'P0001', message = 'eligibility_not_available';
    end if;
    if exists (
      select 1 from public.wellness_point_allocations wpa
      where wpa.eligibility_id = v_eligibility.id
    ) then
      raise exception using errcode = 'P0001', message = 'eligibility_reward_already_awarded';
    end if;
  else
    -- Manual tasks never mint schedule_reward_eligibilities. Keeping eligibility
    -- NULL prevents user-created tasks from being misclassified as generated
    -- photo-proof tasks by the existing mobile snapshot hardening layer.
    v_eligibility.id := null;
    select count(*)::integer into v_manual_count
    from public.schedule_health_checkins shc
    where shc.user_id = v_user_id
      and shc.source_type_snapshot = 'manual_health_task'
      and shc.schedule_date_snapshot = v_item.schedule_date
      and shc.status = 'active';
    if v_manual_count >= 4 then
      raise exception using errcode = 'P0001', message = 'manual_reward_daily_limit';
    end if;
  end if;

  select * into v_program from public.current_wellness_reward_program();

  perform public.refresh_wellness_reward_wallet(v_user_id);
  select * into v_wallet
  from public.wellness_reward_wallets
  where user_id = v_user_id
  for update;

  insert into public.schedule_health_checkins (
    id, eligibility_id, user_id, subject_id, schedule_item_id,
    action_type, checkin_payload, reward_points,
    schedule_date_snapshot, start_time_snapshot, end_time_snapshot,
    window_start_snapshot, window_end_snapshot,
    title_snapshot, description_snapshot, category_snapshot,
    source_type_snapshot, source_id_snapshot, target_value_snapshot,
    unit_snapshot, sort_order_snapshot, ai_generated_snapshot,
    idempotency_key
  ) values (
    v_checkin_id,
    case when v_item.source_type = 'manual_health_task' then null else v_eligibility.id end,
    v_user_id,
    v_subject_id,
    v_item.id,
    v_action,
    coalesce(p_checkin, '{}'::jsonb),
    v_points,
    v_item.schedule_date,
    v_item.start_time,
    v_item.end_time,
    v_window_start,
    v_window_end,
    v_item.title,
    coalesce(v_item.description, ''),
    v_item.category,
    v_item.source_type,
    v_item.source_id,
    greatest(v_item.target_value, 1),
    coalesce(nullif(v_item.unit, ''), 'lần'),
    v_item.sort_order,
    v_item.ai_generated,
    v_idempotency
  ) returning * into v_checkin;

  -- Health metrics remain local-first and are synchronized through the existing
  -- user-data outbox. This RPC validates and stores structured evidence only;
  -- it deliberately does not insert public.health_tracking_logs.

  insert into public.wellness_point_ledgers (
    id, user_id, subject_id, source_type, source_id, schedule_date,
    points_delta, program_code, idempotency_key, event_type, status,
    title, is_redeemable, available_at, expires_at, program_config_id,
    eligibility_id, metadata
  ) values (
    v_ledger_id,
    v_user_id,
    v_subject_id,
    'schedule_health_checkin',
    v_checkin.id,
    v_item.schedule_date,
    v_points,
    v_program.contract_version,
    'schedule_health_checkin:' || v_checkin.id::text,
    'schedule_award',
    v_reward_status,
    'Hoàn thành nhiệm vụ: ' || v_item.title,
    true,
    v_window_end,
    v_window_end + make_interval(days => v_program.expiry_days),
    v_program.program_config_id,
    case when v_item.source_type = 'manual_health_task' then null else v_eligibility.id end,
    jsonb_build_object(
      'evidence_kind', 'health_checkin',
      'action_type', v_action,
      'manual_task', v_item.source_type = 'manual_health_task'
    )
  );

  insert into public.wellness_point_allocations (
    id, user_id, subject_id, ledger_id, eligibility_id,
    source_type, source_id, original_points, remaining_points,
    status, available_at, expires_at, program_config_id
  ) values (
    v_allocation_id,
    v_user_id,
    v_subject_id,
    v_ledger_id,
    case when v_item.source_type = 'manual_health_task' then null else v_eligibility.id end,
    'schedule_reward',
    v_checkin.id,
    v_points,
    v_points,
    v_reward_status,
    v_window_end,
    v_window_end + make_interval(days => v_program.expiry_days),
    v_program.program_config_id
  ) returning * into v_allocation;

  update public.wellness_reward_wallets
  set
    pending_points = pending_points + v_points,
    lifetime_earned_points = lifetime_earned_points + v_points,
    lock_version = lock_version + 1,
    updated_at = now()
  where user_id = v_user_id
  returning * into v_wallet;

  if v_item.source_type <> 'manual_health_task' then
    update public.schedule_reward_eligibilities
    set status = 'completed', updated_at = now()
    where id = v_eligibility.id;
  end if;

  update public.lifestyle_schedule_items
  set
    is_completed = true,
    current_value = greatest(current_value, target_value),
    updated_at = now()
  where id = v_item.id and user_id = v_user_id;

  return jsonb_build_object(
    'checkin_id', v_checkin.id,
    'schedule_item_id', v_item.id,
    'points_delta', v_points,
    'reward_status', v_allocation.status,
    'pending_points', v_wallet.pending_points,
    'available_points', v_wallet.available_points,
    'idempotent_replay', false
  );
end;
$_$;


--
-- Name: nabi_notification_definitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."nabi_notification_definitions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "notification_id" "text" NOT NULL,
    "content_version" integer NOT NULL,
    "category" "text" NOT NULL,
    "priority" integer NOT NULL,
    "policy_key" "text" NOT NULL,
    "primary_action_key" "text" NOT NULL,
    "secondary_action_key" "text",
    "allowed_channels" "text"[] DEFAULT ARRAY['in_app'::"text"] NOT NULL,
    "title_template" "text" DEFAULT 'Nabi nhắn bạn'::"text" NOT NULL,
    "body_template" "text" NOT NULL,
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "effective_from" timestamp with time zone,
    "effective_until" timestamp with time zone,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "reason" "text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "nabi_notification_definitions_category_check" CHECK (("category" = ANY (ARRAY['contextual'::"text", 'milestone'::"text", 'subscription'::"text", 'retention'::"text", 'reward'::"text", 'report'::"text", 'care'::"text", 'profile'::"text"]))),
    CONSTRAINT "nabi_notification_definitions_content_version_check" CHECK (("content_version" > 0)),
    CONSTRAINT "nabi_notification_definitions_priority_check" CHECK ((("priority" >= 0) AND ("priority" <= 1000))),
    CONSTRAINT "nabi_notification_definitions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'archived'::"text"])))
);


--
-- Name: get_active_nabi_notification_definitions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_active_nabi_notification_definitions"() RETURNS SETOF "public"."nabi_notification_definitions"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select d.*
  from public.nabi_notification_definitions d
  where auth.uid() is not null
    and d.status = 'active'
    and (d.effective_from is null or d.effective_from <= now())
    and (d.effective_until is null or d.effective_until > now())
  order by d.priority desc, d.notification_id, d.content_version desc
$$;


--
-- Name: get_admin_dashboard_summary(timestamp with time zone, timestamp with time zone, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_admin_dashboard_summary"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_scope" "text" DEFAULT 'global'::"text", "p_time_zone" "text" DEFAULT 'Asia/Ho_Chi_Minh'::"text") RETURNS TABLE("metric_key" "text", "label" "text", "metric_value" integer, "status" "text", "target_section" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_time_zone text := coalesce(nullif(p_time_zone, ''), 'Asia/Ho_Chi_Minh');
begin
  perform public.admin_assert_permission('dashboard.read');
  v_time_zone := case
    when v_time_zone = 'Asia/Ho_Chi_Minh' then v_time_zone
    else 'Asia/Ho_Chi_Minh'
  end;

  return query
  select 'users_total', 'Nguoi dung', count(*)::integer, 'ready', 'users'
  from public.users
  union all
  select 'onboarding_completed', 'Da hoan thanh onboarding', count(*)::integer, 'ready', 'users'
  from public.users u
  where u.onboarding_status = 'completed'
  union all
  select 'packages_active', 'Goi thanh vien active', count(*)::integer, 'active', 'plans'
  from public.membership_subscriptions ms
  where ms.status in ('trialing', 'active')
  union all
  select 'payments_pending', 'Payment cho duyet', count(*)::integer, 'pending', 'payments'
  from public.payment_events pe
  where pe.status = 'pending'
    and pe.created_at between p_from and p_to
  union all
  select 'payments_succeeded', 'Payment hop le', count(*)::integer, 'ready', 'payments'
  from public.payment_events pe
  where pe.status = 'succeeded'
    and coalesce(pe.paid_at, pe.created_at) between p_from and p_to
  union all
  select
    'revenue_succeeded',
    'Doanh thu da duyet',
    coalesce(sum(pe.amount_cents), 0)::integer,
    'ready',
    'reports'
  from public.payment_events pe
  where pe.status = 'succeeded'
    and coalesce(pe.paid_at, pe.created_at) between p_from and p_to
  union all
  select 'sales_active', 'Sale active', count(*)::integer, 'active', 'sales'
  from public.sale_profiles sp
  where sp.status = 'active'
  union all
  select 'familyplus_active', 'FamilyPlus active', count(*)::integer, 'active', 'users'
  from public.family_groups fg
  where fg.status = 'active'
  union all
  select
    'commission_available',
    'Diem Sale kha dung',
    coalesce(sum(cr.amount_cents), 0)::integer,
    'approved',
    'sale_conversions'
  from public.commission_records cr
  where cr.status in ('pending', 'approved')
    and cr.available_at <= now()
    and cr.created_at between p_from and p_to
  union all
  select
    'admin_alerts',
    'Can Admin xu ly',
    (
      (select count(*) from public.admin_reconciliation_discrepancies ard
       where ard.status in ('open', 'needs_follow_up'))
      + (select count(*) from public.payment_events pe
         where pe.status = 'pending' and pe.created_at between p_from and p_to)
    )::integer,
    'pending',
    'reconciliation';
end;
$$;


--
-- Name: get_my_admin_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_admin_session"() RETURNS TABLE("user_id" "uuid", "roles" "text"[], "permissions" "text"[], "is_active" boolean, "app_access_mode" "text", "can_use_user_app" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    u.id as user_id,
    coalesce(
      array_agg(distinct aur.role_code)
        filter (where aur.role_code is not null),
      array[]::text[]
    ) as roles,
    coalesce(
      array_agg(distinct arp.permission_code)
        filter (where arp.permission_code is not null),
      array[]::text[]
    ) as permissions,
    exists (
      select 1
      from public.admin_user_roles active_aur
      where active_aur.user_id = u.id
        and active_aur.is_active = true
        and active_aur.revoked_at is null
    ) as is_active,
    u.app_access_mode,
    u.app_access_mode in ('user', 'both') as can_use_user_app
  from public.users u
  left join public.admin_user_roles aur
    on aur.user_id = u.id
   and aur.is_active = true
   and aur.revoked_at is null
  left join public.admin_role_permissions arp
    on arp.role_code = aur.role_code
  where u.id = auth.uid()
  group by u.id, u.app_access_mode
$$;


--
-- Name: get_my_familyplus_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_familyplus_context"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select public.familyplus_context_for_user(public.assert_current_user_familyplus())
$$;


--
-- Name: get_my_membership_payment_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_membership_payment_request"() RETURNS TABLE("payment_event_id" "uuid", "plan_code" "text", "billing_cycle" "text", "payer_full_name" "text", "status" "text", "can_cancel" boolean, "amount_cents" integer, "currency" "text", "transfer_reference" "text", "transfer_memo" "text", "bank_code" "text", "bank_name" "text", "bank_bin" "text", "bank_account_number" "text", "bank_account_name" "text", "bank_account_display_name" "text", "transfer_confirmed_at" timestamp with time zone, "review_reason" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_provider text := 'manual_membership_request';
  v_payment public.payment_events%rowtype;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;

  select *
  into v_payment
  from public.payment_events pe
  where pe.payer_user_id = v_user_id
    and pe.provider = v_provider
  order by
    case
      when pe.status in ('awaiting_transfer', 'pending_review', 'pending') then 0
      else 1
    end,
    pe.created_at desc
  limit 1;

  if not found then
    return;
  end if;

  return query select
    v_payment.id,
    v_payment.plan_code::text,
    v_payment.metadata ->> 'billing_cycle',
    nullif(v_payment.metadata ->> 'payer_full_name', ''),
    v_payment.status,
    v_payment.status = 'awaiting_transfer',
    v_payment.amount_cents,
    v_payment.currency,
    v_payment.transfer_reference,
    v_payment.transfer_memo,
    nullif(v_payment.metadata #>> '{bank,bank_code}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_bin}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_number}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_name}', ''),
    nullif(v_payment.metadata #>> '{bank,bank_account_display_name}', ''),
    nullif(v_payment.metadata ->> 'transfer_confirmed_at', '')::timestamptz,
    nullif(v_payment.review_reason, ''),
    v_payment.created_at;
end;
$$;


--
-- Name: get_my_reward_code("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_reward_code"("p_redemption_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_redemption public.wellness_reward_redemptions%rowtype;
  v_code public.wellness_reward_codes%rowtype;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  select * into v_redemption
  from public.wellness_reward_redemptions wrr
  where wrr.id = p_redemption_id
    and wrr.user_id = v_user_id;

  if v_redemption.id is null then
    raise exception using errcode = 'P0001', message = 'redemption_not_found';
  end if;

  select * into v_code
  from public.wellness_reward_codes wrc
  where wrc.id = v_redemption.reward_code_id;

  return jsonb_build_object(
    'redemption_id', v_redemption.id,
    'status', v_redemption.status,
    'voucher_code', case when v_redemption.status = 'issued' then v_code.code_value else null end,
    'voucher_expires_at', v_redemption.voucher_expires_at
  );
end;
$$;


--
-- Name: get_my_sale_conversions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_sale_conversions"() RETURNS TABLE("id" "text", "requested_point_cents" integer, "money_amount_cents" integer, "currency" "text", "status" "text", "requested_at" timestamp with time zone, "reviewed_at" timestamp with time zone, "note" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := public.require_active_sale_user();
begin
  return query
  select
    spc.id::text,
    spc.requested_point_cents,
    spc.money_amount_cents,
    spc.currency,
    spc.status,
    spc.requested_at,
    spc.reviewed_at,
    spc.review_reason
  from public.sale_point_conversions spc
  where spc.sale_user_id = v_user_id
  order by spc.created_at desc;
end;
$$;


--
-- Name: get_my_sale_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_sale_dashboard"() RETURNS TABLE("direct_customers" integer, "successful_payments" integer, "pending_point_cents" integer, "approved_point_cents" integer, "paid_point_cents" integer, "converted_point_cents" integer, "available_point_cents" integer, "currency" "text", "conversion_enabled" boolean, "conversion_rate" numeric, "conversion_minimum_point_cents" integer, "conversion_currency" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := public.require_active_sale_user();
  v_config jsonb := '{}'::jsonb;
  v_enabled boolean := false;
  v_rate numeric := 0;
  v_minimum integer := 0;
  v_conversion_currency text := 'VND';
begin
  select config_value into v_config
  from public.system_config_versions
  where config_key = 'sale_point_conversion'
    and status = 'active'
  order by created_at desc
  limit 1;

  v_config := coalesce(v_config, '{}'::jsonb);
  v_enabled := coalesce((v_config ->> 'enabled')::boolean, false);
  v_rate := coalesce((v_config ->> 'point_to_money_rate')::numeric, 0);
  v_minimum := coalesce((v_config ->> 'minimum_point_cents')::integer, 0);
  v_conversion_currency := coalesce(nullif(v_config ->> 'currency', ''), 'VND');

  return query
  with direct_nodes as (
    select rr.referred_user_id
    from public.referral_relationships rr
    where rr.referrer_user_id = v_user_id
      and rr.status = 'active'
  ), payment_summary as (
    select count(distinct pe.id)::integer as success_count
    from public.payment_events pe
    join direct_nodes dn on dn.referred_user_id = pe.payer_user_id
    where pe.status = 'succeeded'
  ), point_summary as (
    select
      coalesce(sum(amount_cents) filter (
        where status in ('pending', 'approved')
          and available_at > now()
      ), 0)::integer as pending_cents,
      coalesce(sum(amount_cents) filter (
        where status in ('pending', 'approved')
          and available_at <= now()
      ), 0)::integer as approved_cents,
      coalesce(sum(amount_cents) filter (where status = 'paid'), 0)::integer as paid_cents,
      coalesce(max(public.commission_records.currency), 'VND') as result_currency
    from public.commission_records
    where receiver_user_id = v_user_id
  ), adjustment_summary as (
    select coalesce(sum(point_delta_cents), 0)::integer as adjustment_cents
    from public.sale_point_adjustments
    where sale_user_id = v_user_id
      and status = 'approved'
  ), conversion_summary as (
    select coalesce(sum(requested_point_cents), 0)::integer as converted_cents
    from public.sale_point_conversions
    where sale_user_id = v_user_id
      and status in ('requested', 'pending_review', 'approved', 'paid')
  )
  select
    (select count(*)::integer from direct_nodes),
    coalesce(ps.success_count, 0),
    pts.pending_cents,
    (pts.approved_cents + ads.adjustment_cents)::integer,
    pts.paid_cents,
    cs.converted_cents,
    (pts.approved_cents + ads.adjustment_cents - cs.converted_cents)::integer,
    pts.result_currency,
    v_enabled,
    v_rate,
    v_minimum,
    v_conversion_currency
  from payment_summary ps
  cross join point_summary pts
  cross join adjustment_summary ads
  cross join conversion_summary cs;
end;
$$;


--
-- Name: get_my_sale_direct_customers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_sale_direct_customers"() RETURNS TABLE("display_name" "text", "full_name" "text", "age" integer, "phone" "text", "accepted_at" timestamp with time zone, "successful_payments" integer, "approved_point_cents" integer, "currency" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := public.require_active_sale_user();
begin
  return query
  with direct_nodes as (
    select rr.referred_user_id, rr.accepted_at
    from public.referral_relationships rr
    where rr.referrer_user_id = v_user_id
      and rr.status = 'active'
  ), payments as (
    select payer_user_id, count(*)::integer as success_count
    from public.payment_events
    where status = 'succeeded'
    group by payer_user_id
  ), points as (
    select
      payer_user_id,
      coalesce(sum(amount_cents) filter (
        where status in ('pending', 'approved')
          and available_at <= now()
      ), 0)::integer as approved_cents,
      coalesce(max(public.commission_records.currency), 'VND') as result_currency
    from public.commission_records
    where receiver_user_id = v_user_id
    group by payer_user_id
  )
  select
    coalesce(nullif(u.full_name, ''), 'Nguoi dung NanoBio'),
    coalesce(nullif(u.full_name, ''), 'Nguoi dung NanoBio'),
    case
      when coalesce(u.birth_year, hs_self.birth_year) is null then null
      else extract(year from age(make_date(coalesce(u.birth_year, hs_self.birth_year), 1, 1)))::integer
    end,
    u.phone,
    dn.accepted_at,
    coalesce(p.success_count, 0),
    coalesce(pt.approved_cents, 0),
    coalesce(pt.result_currency, 'VND')
  from direct_nodes dn
  join public.users u on u.id = dn.referred_user_id
  left join public.health_subjects hs_self
    on hs_self.owner_user_id = dn.referred_user_id
   and hs_self.subject_type = 'self'
   and hs_self.is_active = true
  left join payments p on p.payer_user_id = dn.referred_user_id
  left join points pt on pt.payer_user_id = dn.referred_user_id
  order by dn.accepted_at desc;
end;
$$;


--
-- Name: get_my_sale_payout_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_sale_payout_profile"() RETURNS TABLE("citizen_id" "text", "bank_bin" "text", "bank_name" "text", "bank_account_number" "text", "bank_account_name" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := public.require_active_sale_user();
begin
  return query
  select
    spp.citizen_id,
    spp.bank_bin,
    spp.bank_name,
    spp.bank_account_number,
    spp.bank_account_name,
    spp.updated_at
  from public.sale_payout_profiles spp
  where spp.sale_user_id = v_user_id;
end;
$$;


--
-- Name: get_my_sale_point_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_sale_point_ledger"() RETURNS TABLE("id" "text", "customer_name" "text", "plan_code" "text", "payment_amount_cents" integer, "point_amount_cents" integer, "currency" "text", "status" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := public.require_active_sale_user();
begin
  return query
  select
    cr.id::text,
    coalesce(nullif(u.full_name, ''), 'Nguoi dung NanoBio') as customer_name,
    pe.plan_code::text,
    pe.amount_cents,
    cr.amount_cents,
    cr.currency,
    cr.status,
    cr.created_at
  from public.commission_records cr
  join public.payment_events pe on pe.id = cr.payment_event_id
  join public.users u on u.id = cr.payer_user_id
  where cr.receiver_user_id = v_user_id
  union all
  select
    spa.id::text,
    'Dieu chinh Admin' as customer_name,
    'manual_adjustment' as plan_code,
    0 as payment_amount_cents,
    spa.point_delta_cents,
    spa.currency,
    spa.status,
    spa.created_at
  from public.sale_point_adjustments spa
  where spa.sale_user_id = v_user_id
  order by created_at desc;
end;
$$;


--
-- Name: get_my_sale_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_sale_state"() RETURNS TABLE("sale_status" "text", "referral_code" "text", "terms_version" "text", "approved_at" timestamp with time zone, "note" "text", "payout_profile_complete" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    coalesce(sp.status::text, u.sale_status::text, 'none') as sale_status,
    rc.code as referral_code,
    sp.terms_version,
    sp.approved_at,
    sp.note,
    (spp.sale_user_id is not null) as payout_profile_complete
  from public.users u
  left join public.sale_profiles sp on sp.user_id = u.id
  left join public.sale_payout_profiles spp on spp.sale_user_id = u.id
  left join lateral (
    select code
    from public.referral_codes
    where sale_user_id = u.id and status = 'active'
    order by created_at asc
    limit 1
  ) rc on true
  where u.id = auth.uid()
$$;


--
-- Name: get_my_wellness_reward_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_my_wellness_reward_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_wallet public.wellness_reward_wallets%rowtype;
  v_expiring integer := 0;
  v_next_expiry timestamptz;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  perform public.refresh_wellness_reward_wallet(v_user_id);
  select * into v_wallet
  from public.wellness_reward_wallets
  where user_id = v_user_id;

  select
    coalesce(sum(remaining_points), 0)::integer,
    min(expires_at)
  into v_expiring, v_next_expiry
  from public.wellness_point_allocations
  where user_id = v_user_id
    and status = 'available'
    and remaining_points > 0
    and expires_at > now()
    and expires_at <= now() + interval '30 days';

  return jsonb_build_object(
    'pending_points', v_wallet.pending_points,
    'available_points', v_wallet.available_points,
    'expiring_soon_points', v_expiring,
    'next_expiry_at', v_next_expiry,
    'synced_at', now(),
    'program_enabled', public.wellness_rewards_feature_enabled()
  );
end;
$$;


--
-- Name: guard_wellness_point_ledger_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_wellness_point_ledger_append_only"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if current_setting('nanobio.wellness_ledger_maintenance', true) = 'on' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'DELETE'
     and not exists (select 1 from public.users where id = old.user_id) then
    return old;
  end if;

  raise exception using
    errcode = 'P0001',
    message = 'wellness_ledger_append_only';
end;
$$;


--
-- Name: guard_wellness_reward_code_offer_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_wellness_reward_code_offer_type"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (
    select 1
    from public.wellness_reward_offers wro
    where wro.id = new.offer_id
      and wro.reward_type = 'voucher'
  ) then
    raise exception using errcode = 'P0001', message = 'reward_type_mismatch';
  end if;
  return new;
end;
$$;


--
-- Name: guard_wellness_reward_redemption_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."guard_wellness_reward_redemption_type"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_offer_type text;
begin
  select reward_type into v_offer_type
  from public.wellness_reward_offers
  where id = new.offer_id;

  if v_offer_type is null or v_offer_type <> new.reward_type_snapshot then
    raise exception using errcode = 'P0001', message = 'reward_type_mismatch';
  end if;

  if v_offer_type = 'voucher' and new.reward_code_id is null then
    raise exception using errcode = 'P0001', message = 'reward_code_required';
  end if;

  if v_offer_type = 'physical' and new.reward_code_id is not null then
    raise exception using errcode = 'P0001', message = 'reward_code_not_allowed';
  end if;

  return new;
end;
$$;


--
-- Name: handle_auth_user_contact_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_auth_user_contact_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.users
  set
    email = new.email,
    phone = coalesce(new.phone, public.users.phone),
    updated_at = now()
  where id = new.id;

  return new;
end;
$$;


--
-- Name: handle_auth_user_created(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_auth_user_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_is_anonymous boolean;
  v_product_status public.nb_product_access_status;
  v_referral_code text;
  v_device_hash text;
  v_phone text;
  v_referrer_id uuid;
  v_referrer_email text;
  v_referrer_phone text;
begin
  v_is_anonymous := coalesce(
    (new.raw_app_meta_data ->> 'provider') = 'anonymous',
    new.email is null and new.phone is null
  );
  v_product_status := case when v_is_anonymous then 'guest' else 'free' end;
  v_referral_code := upper(
    nullif(btrim(new.raw_user_meta_data ->> 'referral_code'), '')
  );
  v_device_hash := nullif(
    btrim(new.raw_user_meta_data ->> 'device_fingerprint'),
    ''
  );
  v_phone := coalesce(
    nullif(btrim(new.phone), ''),
    nullif(btrim(new.raw_user_meta_data ->> 'phone'), '')
  );

  -- All referral checks happen inside the auth.users insert transaction. Any
  -- exception below rolls back auth.users, public.users and the self subject.
  if v_referral_code is not null then
    if v_is_anonymous then
      raise exception using errcode = 'P0001', message = 'invalid_referral_code';
    end if;

    if v_device_hash is null then
      raise exception using errcode = 'P0001', message = 'referral_device_missing';
    end if;

    select
      rc.sale_user_id,
      u.email,
      u.phone
    into
      v_referrer_id,
      v_referrer_email,
      v_referrer_phone
    from public.referral_codes rc
    join public.sale_profiles sp
      on sp.user_id = rc.sale_user_id
     and sp.status = 'active'
    join public.users u
      on u.id = rc.sale_user_id
    where upper(rc.code) = v_referral_code
      and rc.status = 'active'
    limit 1;

    if v_referrer_id is null then
      raise exception using errcode = 'P0001', message = 'invalid_referral_code';
    end if;

    if v_referrer_id = new.id then
      raise exception using errcode = 'P0001', message = 'referral_collision';
    end if;

    if new.email is not null
       and v_referrer_email is not null
       and lower(new.email) = lower(v_referrer_email) then
      raise exception using errcode = 'P0001', message = 'referral_collision';
    end if;

    if v_phone is not null
       and v_referrer_phone is not null
       and v_phone = v_referrer_phone then
      raise exception using errcode = 'P0001', message = 'referral_collision';
    end if;

    if exists (
      select 1
      from public.sale_profiles sp
      where sp.user_id = v_referrer_id
        and sp.participation_device_hash = v_device_hash
    ) then
      raise exception using errcode = 'P0001', message = 'referral_collision';
    end if;

    if exists (
      select 1
      from public.referral_relationships rr
      where rr.status = 'active'
        and rr.device_hash = v_device_hash
    ) then
      raise exception using errcode = 'P0001', message = 'referral_already_used';
    end if;

    if new.email is not null and exists (
      select 1
      from public.referral_relationships rr
      join public.users referred on referred.id = rr.referred_user_id
      where rr.status = 'active'
        and referred.email is not null
        and lower(referred.email) = lower(new.email)
    ) then
      raise exception using errcode = 'P0001', message = 'referral_already_used';
    end if;

    if v_phone is not null and exists (
      select 1
      from public.referral_relationships rr
      join public.users referred on referred.id = rr.referred_user_id
      where rr.status = 'active'
        and referred.phone = v_phone
    ) then
      raise exception using errcode = 'P0001', message = 'referral_already_used';
    end if;
  end if;

  insert into public.users (
    id,
    email,
    phone,
    full_name,
    avatar_url,
    subscription_tier,
    product_access_status,
    is_anonymous
  )
  values (
    new.id,
    new.email,
    v_phone,
    coalesce(
      nullif(new.raw_user_meta_data ->> 'full_name', ''),
      nullif(new.raw_user_meta_data ->> 'name', '')
    ),
    nullif(new.raw_user_meta_data ->> 'avatar_url', ''),
    'free',
    v_product_status,
    v_is_anonymous
  )
  on conflict (id) do update
  set
    email = excluded.email,
    phone = coalesce(excluded.phone, public.users.phone),
    full_name = coalesce(public.users.full_name, excluded.full_name),
    avatar_url = coalesce(public.users.avatar_url, excluded.avatar_url),
    product_access_status = excluded.product_access_status,
    is_anonymous = excluded.is_anonymous,
    updated_at = now();

  insert into public.health_subjects (
    owner_user_id,
    linked_user_id,
    subject_type,
    display_name,
    relationship
  )
  values (
    new.id,
    new.id,
    'self',
    coalesce(
      nullif(new.raw_user_meta_data ->> 'full_name', ''),
      nullif(new.raw_user_meta_data ->> 'name', ''),
      new.email,
      'Bạn'
    ),
    'self'
  )
  on conflict (owner_user_id) where subject_type = 'self'
  do update
  set
    linked_user_id = excluded.linked_user_id,
    display_name = coalesce(public.health_subjects.display_name, excluded.display_name),
    is_active = true,
    updated_at = now();

  if v_referral_code is not null then
    insert into public.referral_relationships (
      referrer_user_id,
      referred_user_id,
      referral_code,
      source,
      status,
      device_hash,
      metadata
    )
    values (
      v_referrer_id,
      new.id,
      v_referral_code,
      'signup',
      'active',
      v_device_hash,
      jsonb_build_object(
        'contract_version', 'auth_v2_atomic_signup_v1',
        'policy', 'direct_only',
        'validated_at', now()
      )
    );
  end if;

  return new;
end;
$$;


--
-- Name: handle_successful_payment_commission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."handle_successful_payment_commission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status = 'succeeded' and new.paid_at is not null then
    perform public.create_commission_records_for_payment(new.id);
  end if;

  return new;
end;
$$;


--
-- Name: insert_mobile_snapshot_row("text", "uuid", "uuid", "jsonb", "text"[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."insert_mobile_snapshot_row"("p_table_name" "text", "p_user_id" "uuid", "p_subject_id" "uuid", "p_row" "jsonb", "p_allowed_columns" "text"[], "p_include_subject" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_allowed_columns text[] := p_allowed_columns;
  v_payload jsonb;
  v_payload_columns text[];
  v_insert_columns text[];
  v_column_names text;
  v_select_names text;
  v_column_definitions text;
  v_matched_column_count integer;
begin
  if jsonb_typeof(p_row) <> 'object' then
    raise exception 'INVALID_SNAPSHOT_ROW for table %', p_table_name
      using errcode = '22023';
  end if;

  if p_include_subject and p_subject_id is null then
    raise exception 'SNAPSHOT_SUBJECT_REQUIRED for table %', p_table_name
      using errcode = '22023';
  end if;

  if p_table_name = 'meal_plans' then
    v_allowed_columns := v_allowed_columns || array[
      'sugar_g', 'saturated_fat_g', 'sodium_mg', 'cholesterol_mg',
      'potassium_mg', 'calcium_mg', 'iron_mg', 'nutrition_status'
    ];
  end if;

  select coalesce(array_agg(c.column_name order by c.ordinality), array[]::text[])
  into v_payload_columns
  from unnest(v_allowed_columns) with ordinality as c(column_name, ordinality)
  where c.column_name not in ('user_id', 'subject_id')
    and p_row ? c.column_name
    and (p_row -> c.column_name) <> 'null'::jsonb;

  select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
  into v_payload
  from jsonb_each(p_row) as e(key, value)
  where e.key = any(v_allowed_columns)
    and e.key not in ('user_id', 'subject_id')
    and e.value <> 'null'::jsonb;

  v_payload := v_payload || jsonb_build_object('user_id', p_user_id);
  v_insert_columns := array['user_id']::text[] || v_payload_columns;

  if p_include_subject then
    v_payload := v_payload || jsonb_build_object('subject_id', p_subject_id);
    v_insert_columns := array['user_id', 'subject_id']::text[] || v_payload_columns;
  end if;

  select
    string_agg(format('%I', c.column_name), ', ' order by c.ordinality),
    string_agg(format('x.%I', c.column_name), ', ' order by c.ordinality)
  into v_column_names, v_select_names
  from unnest(v_insert_columns) with ordinality as c(column_name, ordinality);

  select
    string_agg(
      format('%I %s', c.column_name, pg_catalog.format_type(a.atttypid, a.atttypmod)),
      ', ' order by c.ordinality
    ),
    count(*)
  into v_column_definitions, v_matched_column_count
  from unnest(v_insert_columns) with ordinality as c(column_name, ordinality)
  join pg_catalog.pg_class cls
    on cls.relname = p_table_name
  join pg_catalog.pg_namespace ns
    on ns.oid = cls.relnamespace and ns.nspname = 'public'
  join pg_catalog.pg_attribute a
    on a.attrelid = cls.oid
   and a.attname = c.column_name
   and a.attnum > 0
   and not a.attisdropped;

  if v_matched_column_count <> cardinality(v_insert_columns) then
    raise exception 'SNAPSHOT_SCHEMA_MISMATCH for table %', p_table_name
      using errcode = '22023';
  end if;

  execute format(
    'insert into public.%I (%s) select %s from jsonb_to_record($1) as x(%s)',
    p_table_name,
    v_column_names,
    v_select_names,
    v_column_definitions
  ) using v_payload;
end;
$_$;


--
-- Name: list_my_reward_catalog_v2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_my_reward_catalog_v2"("p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "offer_id" "uuid", "offer_code" "text", "reward_type" "text", "title" "text", "description" "text", "provider_name" "text", "cost_points" integer, "available_codes" integer, "stock_count" integer, "eligible_plan_codes" "text"[], "available_from" timestamp with time zone, "available_until" timestamp with time zone, "voucher_expires_at" timestamp with time zone, "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_plan text;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  v_plan := public.current_plan_for_user(v_user_id)::text;

  return query
  select
    wro.id,
    wro.id,
    wro.offer_code,
    wro.reward_type,
    wro.title,
    wro.description,
    wro.provider_name,
    wro.cost_points,
    count(wrc.id) filter (
      where wrc.status = 'available'
        and coalesce(wrc.voucher_expires_at, wro.voucher_expires_at) > now()
    )::integer,
    wro.stock_count,
    wro.eligible_plan_codes,
    wro.available_from,
    wro.available_until,
    wro.voucher_expires_at,
    wro.is_active
  from public.wellness_reward_offers wro
  left join public.wellness_reward_codes wrc
    on wrc.offer_id = wro.id
  where public.wellness_rewards_feature_enabled()
    and wro.is_active = true
    and (wro.available_from is null or wro.available_from <= now())
    and (wro.available_until is null or wro.available_until > now())
    and v_plan = any(wro.eligible_plan_codes)
  group by wro.id
  order by wro.cost_points, wro.created_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
end;
$$;


--
-- Name: list_my_reward_offers(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_my_reward_offers"("p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "offer_id" "uuid", "offer_code" "text", "title" "text", "description" "text", "provider_name" "text", "cost_points" integer, "available_codes" integer, "eligible_plan_codes" "text"[], "available_from" timestamp with time zone, "available_until" timestamp with time zone, "voucher_expires_at" timestamp with time zone, "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_plan text;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  v_plan := public.current_plan_for_user(v_user_id)::text;

  return query
  select
    wro.id, wro.id, wro.offer_code, wro.title, wro.description,
    wro.provider_name, wro.cost_points,
    count(wrc.id) filter (
      where wrc.status = 'available'
        and coalesce(wrc.voucher_expires_at, wro.voucher_expires_at) > now()
    )::integer,
    wro.eligible_plan_codes, wro.available_from, wro.available_until,
    wro.voucher_expires_at, wro.is_active
  from public.wellness_reward_offers wro
  left join public.wellness_reward_codes wrc on wrc.offer_id = wro.id
  where public.wellness_rewards_feature_enabled()
    and wro.reward_type = 'voucher'
    and wro.is_active = true
    and (wro.available_from is null or wro.available_from <= now())
    and (wro.available_until is null or wro.available_until > now())
    and v_plan = any(wro.eligible_plan_codes)
  group by wro.id
  order by wro.cost_points, wro.created_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
end;
$$;


--
-- Name: list_my_reward_redemptions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_my_reward_redemptions"("p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "redemption_id" "uuid", "offer_id" "uuid", "title" "text", "provider_name" "text", "points_spent" integer, "status" "text", "voucher_expires_at" timestamp with time zone, "created_at" timestamp with time zone, "cancelled_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  return query
  select
    wrr.id, wrr.id, wrr.offer_id, wrr.offer_title_snapshot,
    wrr.provider_name_snapshot, wrr.points_spent, wrr.status,
    wrr.voucher_expires_at, wrr.created_at, wrr.cancelled_at
  from public.wellness_reward_redemptions wrr
  where wrr.user_id = v_user_id and wrr.reward_type_snapshot = 'voucher'
  order by wrr.created_at desc, wrr.id desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
end;
$$;


--
-- Name: list_my_reward_redemptions_v2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_my_reward_redemptions_v2"("p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "redemption_id" "uuid", "offer_id" "uuid", "reward_type" "text", "title" "text", "provider_name" "text", "points_spent" integer, "status" "text", "voucher_expires_at" timestamp with time zone, "created_at" timestamp with time zone, "cancelled_at" timestamp with time zone, "received_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  return query
  select
    wrr.id,
    wrr.id,
    wrr.offer_id,
    wrr.reward_type_snapshot,
    wrr.offer_title_snapshot,
    wrr.provider_name_snapshot,
    wrr.points_spent,
    wrr.status,
    wrr.voucher_expires_at,
    wrr.created_at,
    wrr.cancelled_at,
    wrr.received_at
  from public.wellness_reward_redemptions wrr
  where wrr.user_id = v_user_id
  order by wrr.created_at desc, wrr.id desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
end;
$$;


--
-- Name: list_my_wellness_point_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."list_my_wellness_point_history"("p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "points_delta" integer, "event_type" "text", "status" "text", "title" "text", "is_redeemable" boolean, "available_at" timestamp with time zone, "expires_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  perform public.refresh_wellness_reward_wallet(v_user_id);

  return query
  select
    wpl.id,
    wpl.points_delta,
    wpl.event_type,
    case
      when wpl.event_type = 'schedule_award' then coalesce(wpa.status, wpl.status)
      else wpl.status
    end,
    wpl.title,
    wpl.is_redeemable,
    wpl.available_at,
    wpl.expires_at,
    wpl.created_at
  from public.wellness_point_ledgers wpl
  left join public.wellness_point_allocations wpa
    on wpa.ledger_id = wpl.id
  where wpl.user_id = v_user_id
  order by wpl.created_at desc, wpl.id desc
  limit greatest(1, least(coalesce(p_limit, 100), 200));
end;
$$;


--
-- Name: purge_early_access_closed_leads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."purge_early_access_closed_leads"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'early_access_private'
    AS $$
declare
  v_candidate record;
  v_deleted integer := 0;
  v_row_count integer;
begin
  for v_candidate in
    select id, phone_hash
    from public.early_access_leads
    where created_at < now() - interval '12 months'
      and status in ('registered','converted','rejected')
  loop
    if v_candidate.phone_hash is not null then
      perform pg_advisory_xact_lock(hashtextextended(v_candidate.phone_hash, 0));
      insert into early_access_private.promo_phone_suppressions(phone_hash)
      values (v_candidate.phone_hash)
      on conflict (phone_hash) do nothing;
    end if;
    delete from public.early_access_leads
    where id = v_candidate.id
      and created_at < now() - interval '12 months'
      and status in ('registered','converted','rejected');
    get diagnostics v_row_count = row_count;
    v_deleted := v_deleted + v_row_count;
  end loop;
  return v_deleted;
end;
$$;


--
-- Name: purge_early_access_rate_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."purge_early_access_rate_limits"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_deleted integer;
begin
  delete from early_access_private.rate_limits where expires_at <= now();
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


--
-- Name: record_nabi_notification_events("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."record_nabi_notification_events"("p_events" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_event jsonb;
  v_count integer := 0;
  v_event_name text;
  v_occurrence_id uuid;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if jsonb_typeof(coalesce(p_events, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_events, '[]'::jsonb)) > 100 then
    raise exception 'INVALID_EVENT_BATCH' using errcode = '22023';
  end if;
  if not coalesce((
    select p.analytics_upload_enabled
    from public.nabi_notification_preferences p
    where p.user_id = v_user_id
  ), false) then
    return 0;
  end if;

  for v_event in select value from jsonb_array_elements(p_events)
  loop
    v_event_name := v_event ->> 'event_name';
    if v_event_name not in (
      'nabi_notification_eligible', 'nabi_notification_shown',
      'nabi_notification_opened', 'nabi_notification_dismissed',
      'nabi_notification_primary_clicked', 'nabi_notification_secondary_clicked',
      'nabi_upgrade_page_viewed', 'nabi_checkout_started',
      'nabi_conversion_completed', 'nabi_notification_failed'
    ) then
      continue;
    end if;
    v_occurrence_id := nullif(v_event ->> 'occurrence_id', '')::uuid;
    if v_occurrence_id is not null and not exists (
      select 1 from public.nabi_notification_user_states s
      where s.id = v_occurrence_id and s.user_id = v_user_id
    ) then
      continue;
    end if;

    insert into public.nabi_notification_events (
      id, user_id, occurrence_id, notification_id, event_name,
      session_id, screen_key, app_version, result_code, safe_metadata, created_at
    ) values (
      (v_event ->> 'id')::uuid,
      v_user_id,
      v_occurrence_id,
      coalesce(v_event ->> 'notification_id', 'unknown'),
      v_event_name,
      nullif(v_event ->> 'session_id', ''),
      nullif(v_event ->> 'screen_key', ''),
      nullif(v_event ->> 'app_version', ''),
      nullif(v_event ->> 'result_code', ''),
      coalesce(v_event -> 'safe_metadata', '{}'::jsonb),
      coalesce(nullif(v_event ->> 'created_at', '')::timestamptz, now())
    ) on conflict (id) do nothing;
    if found then v_count := v_count + 1; end if;
  end loop;
  return v_count;
end;
$$;


--
-- Name: record_trusted_payment_event("uuid", "public"."nb_membership_plan", "text", "text", integer, integer, integer, "text", boolean, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."record_trusted_payment_event"("p_payer_user_id" "uuid", "p_plan_code" "public"."nb_membership_plan", "p_provider" "text", "p_provider_event_id" "text", "p_amount_cents" integer, "p_list_price_cents" integer DEFAULT NULL::integer, "p_commission_base_cents" integer DEFAULT NULL::integer, "p_currency" "text" DEFAULT 'VND'::"text", "p_auto_approve" boolean DEFAULT false, "p_raw_event_hash" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_payment_id uuid;
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_list_price_cents integer;
  v_commission_base_cents integer;
begin
  v_list_price_cents := coalesce(
    p_list_price_cents,
    nullif(v_metadata ->> 'list_price_cents', '')::integer
  );
  v_commission_base_cents := coalesce(
    p_commission_base_cents,
    v_list_price_cents,
    nullif(v_metadata ->> 'commission_base_cents', '')::integer,
    p_amount_cents
  );

  insert into public.payment_events (
    payer_user_id,
    plan_code,
    provider,
    provider_event_id,
    amount_cents,
    list_price_cents,
    commission_base_cents,
    currency,
    status,
    paid_at,
    raw_event_hash,
    metadata
  )
  values (
    p_payer_user_id,
    p_plan_code,
    p_provider,
    p_provider_event_id,
    p_amount_cents,
    v_list_price_cents,
    v_commission_base_cents,
    coalesce(nullif(p_currency, ''), 'VND'),
    'pending',
    null,
    p_raw_event_hash,
    v_metadata || jsonb_build_object(
      'manual_approval_required',
      true,
      'auto_approve_requested',
      coalesce(p_auto_approve, false),
      'commission_base_policy',
      'list_price_owner_package_only'
    )
  )
  on conflict (provider, provider_event_id) do update
  set
    list_price_cents = coalesce(public.payment_events.list_price_cents, excluded.list_price_cents),
    commission_base_cents = coalesce(public.payment_events.commission_base_cents, excluded.commission_base_cents),
    metadata = public.payment_events.metadata || excluded.metadata
  returning id into v_payment_id;

  return v_payment_id;
end;
$$;


--
-- Name: redeem_my_reward_offer("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."redeem_my_reward_offer"("p_offer_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_plan text;
  v_offer public.wellness_reward_offers%rowtype;
  v_code public.wellness_reward_codes%rowtype;
  v_existing public.wellness_reward_redemptions%rowtype;
  v_redemption_id uuid := gen_random_uuid();
  v_subject_id uuid;
  v_wallet public.wellness_reward_wallets%rowtype;
  v_allocation record;
  v_needed integer;
  v_take integer;
  v_voucher_expires_at timestamptz;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  if not public.wellness_rewards_feature_enabled() then
    raise exception using errcode = 'P0001', message = 'wellness_rewards_disabled';
  end if;
  if p_offer_id is null then
    raise exception using errcode = 'P0001', message = 'offer_required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:redeem:' || v_user_id::text || ':' || btrim(p_idempotency_key),
    0
  ));

  select * into v_existing
  from public.wellness_reward_redemptions wrr
  where wrr.user_id = v_user_id
    and wrr.idempotency_key = btrim(p_idempotency_key)
  for update;

  if v_existing.id is not null then
    if v_existing.offer_id <> p_offer_id then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    select * into v_code
    from public.wellness_reward_codes
    where id = v_existing.reward_code_id;
    return jsonb_build_object(
      'id', v_existing.id,
      'redemption_id', v_existing.id,
      'offer_id', v_existing.offer_id,
      'title', v_existing.offer_title_snapshot,
      'provider_name', v_existing.provider_name_snapshot,
      'points_spent', v_existing.points_spent,
      'status', v_existing.status,
      'voucher_code', case when v_existing.status = 'issued' then v_code.code_value else null end,
      'voucher_expires_at', v_existing.voucher_expires_at,
      'created_at', v_existing.created_at,
      'cancelled_at', v_existing.cancelled_at,
      'idempotent_replay', true
    );
  end if;

  select * into v_offer
  from public.wellness_reward_offers wro
  where wro.id = p_offer_id
  for update;

  if v_offer.id is null
     or not v_offer.is_active
     or (v_offer.available_from is not null and v_offer.available_from > now())
     or (v_offer.available_until is not null and v_offer.available_until <= now()) then
    raise exception using errcode = 'P0001', message = 'offer_unavailable';
  end if;

  v_plan := public.current_plan_for_user(v_user_id)::text;
  if not (v_plan = any(v_offer.eligible_plan_codes)) then
    raise exception using errcode = 'P0001', message = 'offer_ineligible';
  end if;

  perform public.refresh_wellness_reward_wallet(v_user_id);
  select * into v_wallet
  from public.wellness_reward_wallets
  where user_id = v_user_id
  for update;

  if v_wallet.available_points < v_offer.cost_points then
    raise exception using errcode = 'P0001', message = 'insufficient_points';
  end if;

  select * into v_code
  from public.wellness_reward_codes wrc
  where wrc.offer_id = v_offer.id
    and wrc.status = 'available'
    and coalesce(wrc.voucher_expires_at, v_offer.voucher_expires_at) > now()
  order by coalesce(wrc.voucher_expires_at, v_offer.voucher_expires_at), wrc.created_at
  for update skip locked
  limit 1;

  if v_code.id is null then
    raise exception using errcode = 'P0001', message = 'offer_out_of_stock';
  end if;

  v_voucher_expires_at := coalesce(v_code.voucher_expires_at, v_offer.voucher_expires_at);
  select hs.id into v_subject_id
  from public.health_subjects hs
  where hs.owner_user_id = v_user_id
    and hs.subject_type = 'self'
    and hs.is_active = true
  limit 1;

  if v_subject_id is null then
    raise exception using errcode = 'P0001', message = 'health_subject_required';
  end if;

  insert into public.wellness_reward_redemptions (
    id,
    user_id,
    offer_id,
    reward_code_id,
    offer_title_snapshot,
    provider_name_snapshot,
    points_spent,
    voucher_expires_at,
    idempotency_key
  )
  values (
    v_redemption_id,
    v_user_id,
    v_offer.id,
    v_code.id,
    v_offer.title,
    v_offer.provider_name,
    v_offer.cost_points,
    v_voucher_expires_at,
    btrim(p_idempotency_key)
  );

  v_needed := v_offer.cost_points;
  for v_allocation in
    select wpa.id, wpa.remaining_points
    from public.wellness_point_allocations wpa
    where wpa.user_id = v_user_id
      and wpa.status = 'available'
      and wpa.remaining_points > 0
      and wpa.expires_at > now()
    order by wpa.expires_at, wpa.created_at, wpa.id
    for update
  loop
    exit when v_needed = 0;
    v_take := least(v_needed, v_allocation.remaining_points);

    insert into public.wellness_redemption_allocation_usages (
      redemption_id,
      allocation_id,
      points_used
    )
    values (v_redemption_id, v_allocation.id, v_take);

    update public.wellness_point_allocations
    set
      remaining_points = remaining_points - v_take,
      status = case when remaining_points - v_take = 0 then 'spent' else status end,
      updated_at = now()
    where id = v_allocation.id;

    v_needed := v_needed - v_take;
  end loop;

  if v_needed <> 0 then
    raise exception using errcode = 'P0001', message = 'wallet_allocation_mismatch';
  end if;

  update public.wellness_reward_codes
  set
    status = 'issued',
    assigned_user_id = v_user_id,
    assigned_redemption_id = v_redemption_id,
    issued_at = now()
  where id = v_code.id;

  insert into public.wellness_point_ledgers (
    user_id,
    subject_id,
    source_type,
    source_id,
    schedule_date,
    points_delta,
    program_code,
    idempotency_key,
    event_type,
    status,
    title,
    is_redeemable,
    redemption_id,
    metadata
  )
  values (
    v_user_id,
    v_subject_id,
    'reward_redemption',
    v_redemption_id,
    (now() at time zone 'Asia/Ho_Chi_Minh')::date,
    -v_offer.cost_points,
    'wellness_rewards_v2',
    'reward_redemption:' || v_redemption_id::text,
    'redemption',
    'redeemed',
    'Đổi ưu đãi: ' || v_offer.title,
    true,
    v_redemption_id,
    jsonb_build_object('offer_id', v_offer.id)
  );

  update public.wellness_reward_wallets
  set
    available_points = available_points - v_offer.cost_points,
    lifetime_spent_points = lifetime_spent_points + v_offer.cost_points,
    lock_version = lock_version + 1,
    updated_at = now()
  where user_id = v_user_id
  returning * into v_wallet;

  return jsonb_build_object(
    'id', v_redemption_id,
    'redemption_id', v_redemption_id,
    'offer_id', v_offer.id,
    'title', v_offer.title,
    'provider_name', v_offer.provider_name,
    'points_spent', v_offer.cost_points,
    'status', 'issued',
    'voucher_code', v_code.code_value,
    'voucher_expires_at', v_voucher_expires_at,
    'available_points', v_wallet.available_points,
    'created_at', now(),
    'idempotent_replay', false
  );
end;
$$;


--
-- Name: redeem_my_reward_v2("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."redeem_my_reward_v2"("p_offer_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_plan text;
  v_offer public.wellness_reward_offers%rowtype;
  v_wallet public.wellness_reward_wallets%rowtype;
  v_existing public.wellness_reward_redemptions%rowtype;
  v_response jsonb;
  v_ledger_id uuid;
  v_redemption_id uuid := gen_random_uuid();
  v_subject_id uuid;
  v_allocation record;
  v_needed integer;
  v_take integer;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  if p_offer_id is null then
    raise exception using errcode = 'P0001', message = 'offer_required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:redeem:v2:' || v_user_id::text || ':' || btrim(p_idempotency_key),
    0
  ));

  select * into v_existing
  from public.wellness_reward_redemptions wrr
  where wrr.user_id = v_user_id
    and wrr.idempotency_key = btrim(p_idempotency_key);

  if v_existing.id is not null then
    if v_existing.offer_id <> p_offer_id then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    if v_existing.reward_type_snapshot = 'voucher' then
      v_response := public.redeem_my_reward_offer(p_offer_id, p_idempotency_key);
      select id into v_ledger_id
      from public.wellness_point_ledgers
      where redemption_id = v_existing.id
      order by created_at desc
      limit 1;
      return v_response || jsonb_build_object('point_ledger_id', v_ledger_id);
    end if;
    select available_points into v_wallet.available_points
    from public.wellness_reward_wallets
    where user_id = v_user_id;
    select id into v_ledger_id
    from public.wellness_point_ledgers
    where redemption_id = v_existing.id
    order by created_at desc
    limit 1;
    return jsonb_build_object(
      'success', true,
      'id', v_existing.id,
      'redemption_id', v_existing.id,
      'offer_id', v_existing.offer_id,
      'reward_type', 'physical',
      'title', v_existing.offer_title_snapshot,
      'provider_name', v_existing.provider_name_snapshot,
      'points_spent', v_existing.points_spent,
      'status', v_existing.status,
      'point_ledger_id', v_ledger_id,
      'available_points', coalesce(v_wallet.available_points, 0),
      'created_at', v_existing.created_at,
      'received_at', v_existing.received_at,
      'idempotent_replay', true
    );
  end if;

  if not public.wellness_rewards_feature_enabled() then
    raise exception using errcode = 'P0001', message = 'wellness_rewards_disabled';
  end if;

  select * into v_offer
  from public.wellness_reward_offers wro
  where wro.id = p_offer_id
  for update;

  if v_offer.id is null
     or not v_offer.is_active
     or (v_offer.available_from is not null and v_offer.available_from > now())
     or (v_offer.available_until is not null and v_offer.available_until <= now()) then
    raise exception using errcode = 'P0001', message = 'offer_unavailable';
  end if;

  if v_offer.reward_type = 'voucher' then
    v_response := public.redeem_my_reward_offer(p_offer_id, p_idempotency_key);
    select id into v_ledger_id
    from public.wellness_point_ledgers
    where redemption_id = (v_response ->> 'redemption_id')::uuid
    order by created_at desc
    limit 1;
    return v_response || jsonb_build_object('point_ledger_id', v_ledger_id);
  end if;

  if v_offer.stock_count <= 0 then
    raise exception using errcode = 'P0001', message = 'offer_out_of_stock';
  end if;

  v_plan := public.current_plan_for_user(v_user_id)::text;
  if not (v_plan = any(v_offer.eligible_plan_codes)) then
    raise exception using errcode = 'P0001', message = 'offer_ineligible';
  end if;

  perform public.refresh_wellness_reward_wallet(v_user_id);
  select * into v_wallet
  from public.wellness_reward_wallets
  where user_id = v_user_id
  for update;

  if v_wallet.available_points < v_offer.cost_points then
    raise exception using errcode = 'P0001', message = 'insufficient_points';
  end if;

  select hs.id into v_subject_id
  from public.health_subjects hs
  where hs.owner_user_id = v_user_id
    and hs.subject_type = 'self'
    and hs.is_active = true
  limit 1;
  if v_subject_id is null then
    raise exception using errcode = 'P0001', message = 'health_subject_required';
  end if;

  update public.wellness_reward_offers
  set stock_count = stock_count - 1, updated_at = now()
  where id = v_offer.id and stock_count > 0;
  if not found then
    raise exception using errcode = 'P0001', message = 'offer_out_of_stock';
  end if;

  insert into public.wellness_reward_redemptions (
    id, user_id, offer_id, reward_code_id, reward_type_snapshot,
    offer_title_snapshot, provider_name_snapshot, points_spent, status,
    voucher_expires_at, idempotency_key
  ) values (
    v_redemption_id, v_user_id, v_offer.id, null, 'physical',
    v_offer.title, v_offer.provider_name, v_offer.cost_points, 'redeemed',
    null, btrim(p_idempotency_key)
  );

  v_needed := v_offer.cost_points;
  for v_allocation in
    select wpa.id, wpa.remaining_points
    from public.wellness_point_allocations wpa
    where wpa.user_id = v_user_id
      and wpa.status = 'available'
      and wpa.remaining_points > 0
      and wpa.expires_at > now()
    order by wpa.expires_at, wpa.created_at, wpa.id
    for update
  loop
    exit when v_needed = 0;
    v_take := least(v_needed, v_allocation.remaining_points);
    insert into public.wellness_redemption_allocation_usages (
      redemption_id, allocation_id, points_used
    ) values (v_redemption_id, v_allocation.id, v_take);
    update public.wellness_point_allocations
    set remaining_points = remaining_points - v_take,
        status = case when remaining_points - v_take = 0 then 'spent' else status end,
        updated_at = now()
    where id = v_allocation.id;
    v_needed := v_needed - v_take;
  end loop;

  if v_needed <> 0 then
    raise exception using errcode = 'P0001', message = 'wallet_allocation_mismatch';
  end if;

  insert into public.wellness_point_ledgers (
    user_id, subject_id, source_type, source_id, schedule_date, points_delta,
    program_code, idempotency_key, event_type, status, title, is_redeemable,
    redemption_id, metadata
  ) values (
    v_user_id, v_subject_id, 'reward_redemption', v_redemption_id,
    (now() at time zone 'Asia/Ho_Chi_Minh')::date, -v_offer.cost_points,
    'wellness_rewards_v2', 'reward_redemption:' || v_redemption_id::text,
    'redemption', 'redeemed', 'Đổi quà: ' || v_offer.title, true,
    v_redemption_id, jsonb_build_object('offer_id', v_offer.id, 'reward_type', 'physical')
  ) returning id into v_ledger_id;

  update public.wellness_reward_wallets
  set available_points = available_points - v_offer.cost_points,
      lifetime_spent_points = lifetime_spent_points + v_offer.cost_points,
      lock_version = lock_version + 1,
      updated_at = now()
  where user_id = v_user_id
  returning * into v_wallet;

  return jsonb_build_object(
    'success', true,
    'id', v_redemption_id,
    'redemption_id', v_redemption_id,
    'offer_id', v_offer.id,
    'reward_type', 'physical',
    'title', v_offer.title,
    'provider_name', v_offer.provider_name,
    'points_spent', v_offer.cost_points,
    'status', 'redeemed',
    'point_ledger_id', v_ledger_id,
    'available_points', v_wallet.available_points,
    'created_at', now(),
    'idempotent_replay', false
  );
end;
$$;


--
-- Name: refresh_wellness_reward_wallet("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refresh_wellness_reward_wallet"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_newly_available integer := 0;
  v_expired integer := 0;
begin
  if p_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  insert into public.wellness_reward_wallets (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  perform 1
  from public.wellness_reward_wallets
  where user_id = p_user_id
  for update;

  perform 1
  from public.wellness_point_allocations
  where user_id = p_user_id
    and status = 'pending'
    and available_at <= now()
    and remaining_points > 0
  for update;

  select coalesce(sum(remaining_points), 0)::integer
  into v_newly_available
  from public.wellness_point_allocations
  where user_id = p_user_id
    and status = 'pending'
    and available_at <= now()
    and remaining_points > 0;

  update public.wellness_point_allocations
  set status = 'available', updated_at = now()
  where user_id = p_user_id
    and status = 'pending'
    and available_at <= now()
    and remaining_points > 0;

  if v_newly_available > 0 then
    update public.wellness_reward_wallets
    set
      pending_points = pending_points - v_newly_available,
      available_points = available_points + v_newly_available,
      lock_version = lock_version + 1,
      updated_at = now()
    where user_id = p_user_id;
  end if;

  perform 1
  from public.wellness_point_allocations
  where user_id = p_user_id
    and status = 'available'
    and expires_at <= now()
    and remaining_points > 0
  for update;

  select coalesce(sum(remaining_points), 0)::integer
  into v_expired
  from public.wellness_point_allocations
  where user_id = p_user_id
    and status = 'available'
    and expires_at <= now()
    and remaining_points > 0;

  insert into public.wellness_point_ledgers (
    user_id,
    subject_id,
    source_type,
    source_id,
    schedule_date,
    points_delta,
    program_code,
    idempotency_key,
    event_type,
    status,
    title,
    is_redeemable,
    available_at,
    expires_at,
    program_config_id,
    metadata
  )
  select
    wpa.user_id,
    wpa.subject_id,
    'wellness_point_allocation',
    wpa.id,
    (wpa.expires_at at time zone 'Asia/Ho_Chi_Minh')::date,
    -wpa.remaining_points,
    'wellness_rewards_v2',
    'wellness_expiry:' || wpa.id::text,
    'expiry',
    'expired',
    'Điểm chăm sóc đã hết hạn',
    true,
    wpa.available_at,
    wpa.expires_at,
    wpa.program_config_id,
    jsonb_build_object('allocation_id', wpa.id)
  from public.wellness_point_allocations wpa
  where wpa.user_id = p_user_id
    and wpa.status = 'available'
    and wpa.expires_at <= now()
    and wpa.remaining_points > 0
  on conflict (user_id, idempotency_key) do nothing;

  update public.wellness_point_allocations
  set remaining_points = 0, status = 'expired', updated_at = now()
  where user_id = p_user_id
    and status = 'available'
    and expires_at <= now()
    and remaining_points > 0;

  if v_expired > 0 then
    update public.wellness_reward_wallets
    set
      available_points = available_points - v_expired,
      lock_version = lock_version + 1,
      updated_at = now()
    where user_id = p_user_id;
  end if;
end;
$$;


--
-- Name: register_my_schedule_reward_eligibilities("text", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."register_my_schedule_reward_eligibilities"("p_request_id" "text", "p_items" "jsonb", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_subject_id uuid;
  v_request public.personal_schedule_ai_requests%rowtype;
  v_guest_marker public.guest_schedule_reward_registrations%rowtype;
  v_member_marker public.member_schedule_reward_registrations%rowtype;
  v_item_count integer;
  v_matched_count integer;
  v_full_item_count integer;
  v_full_day_count integer;
  v_request_eligible_count integer;
  v_manifest_hash text;
  v_full_item_id_hash text;
  v_full_manifest_hash text;
  v_full_item_ids uuid[];
  v_guest_eligible_item_ids uuid[];
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;
  if not public.wellness_rewards_feature_enabled() then
    raise exception using errcode = 'P0001', message = 'wellness_rewards_disabled';
  end if;
  if nullif(btrim(coalesce(p_request_id, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'schedule_request_required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'idempotency_key_required';
  end if;
  if jsonb_typeof(p_items) <> 'array' then
    raise exception using errcode = 'P0001', message = 'schedule_items_invalid';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:register:' || v_user_id::text || ':' || btrim(p_idempotency_key),
    0
  ));

  v_item_count := jsonb_array_length(p_items);
  if v_item_count < 1 or v_item_count > 70 then
    raise exception using errcode = 'P0001', message = 'schedule_items_invalid';
  end if;

  if exists (
    select 1 from public.users
    where id = v_user_id and is_anonymous = true
  ) then
    raise exception using errcode = 'P0001', message = 'member_account_required';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'eligibility_id', sre.id,
        'schedule_item_id', sre.schedule_item_id,
        'schedule_date', sre.schedule_date,
        'window_start', sre.window_start,
        'window_end', sre.window_end,
        'status', sre.status
      ) order by sre.window_start
    ),
    '[]'::jsonb
  )
  into v_result
  from public.schedule_reward_eligibilities sre
  where sre.user_id = v_user_id
    and sre.registration_idempotency_key = btrim(p_idempotency_key);

  if jsonb_array_length(v_result) > 0 then
    if exists (
      select 1
      from public.schedule_reward_eligibilities sre
      where sre.user_id = v_user_id
        and sre.registration_idempotency_key = btrim(p_idempotency_key)
        and sre.schedule_request_id <> btrim(p_request_id)
    ) then
      raise exception using errcode = 'P0001', message = 'idempotency_conflict';
    end if;
    return jsonb_build_object(
      'request_id', btrim(p_request_id),
      'registered_count', jsonb_array_length(v_result),
      'eligibilities', v_result,
      'idempotent_replay', true
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    where coalesce(item ->> 'schedule_item_id', item ->> 'id', '')
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) then
    raise exception using errcode = 'P0001', message = 'schedule_item_id_invalid';
  end if;

  select encode(
    extensions.digest(string_agg(parsed.schedule_item_id::text, ',' order by parsed.schedule_item_id), 'sha256'),
    'hex'
  )
  into v_manifest_hash
  from (
    select distinct
      coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid as schedule_item_id
    from jsonb_array_elements(p_items) item
  ) parsed;

  select * into v_request
  from public.personal_schedule_ai_requests psar
  where psar.request_id = btrim(p_request_id)
    and psar.user_id = v_user_id
    and psar.actor_mode in ('member_new', 'initial_guest')
    and psar.status = 'succeeded';

  if v_request.request_id is null
     or v_request.start_date is null
     or v_request.days not between 1 and 7
     or v_request.schedule_item_count < v_request.days * 10
     or v_request.schedule_item_count > v_request.days * 11 then
    raise exception using errcode = 'P0001', message = 'schedule_request_not_eligible';
  end if;

  -- This request-scoped lock is independent of the client key. It prevents a
  -- second key racing the first registration before its immutable marker is
  -- visible.
  perform pg_advisory_xact_lock(hashtextextended(
    'wellness:register-request:' || btrim(p_request_id),
    0
  ));

  if v_request.actor_mode = 'member_new' then
    if v_request.schedule_item_count <> v_item_count then
      raise exception using errcode = 'P0001', message = 'schedule_request_not_eligible';
    end if;

    if not exists (
      select 1
      from public.usage_events ue
      where ue.user_id = v_user_id
        and ue.feature_key = 'personal_schedule_generation'
        and ue.idempotency_key = btrim(p_request_id)
        and ue.event_source in ('trusted_backend', 'edge_function', 'sql_job', 'admin')
    ) then
      raise exception using errcode = 'P0001', message = 'schedule_quota_commit_required';
    end if;

    select * into v_member_marker
    from public.member_schedule_reward_registrations msrr
    where msrr.schedule_request_id = btrim(p_request_id)
    for update;

    if v_member_marker.schedule_request_id is not null then
      if v_member_marker.user_id <> v_user_id then
        raise exception using errcode = 'P0001', message = 'member_schedule_request_claimed';
      end if;
      raise exception using errcode = 'P0001', message = 'member_schedule_request_already_registered';
    end if;
  else
    -- Different idempotency keys for the same account/request must still
    -- serialize against the lifetime Guest marker and its unique request ID.
    perform pg_advisory_xact_lock(hashtextextended(
      'wellness:guest-register:' || v_user_id::text,
      0
    ));
    if (
      select count(*)
      from public.personal_schedule_ai_requests psar
      where psar.user_id = v_user_id
        and psar.actor_mode = 'initial_guest'
        and psar.status = 'succeeded'
    ) <> 1 then
      raise exception using errcode = 'P0001', message = 'guest_schedule_request_ambiguous';
    end if;

    select * into v_guest_marker
    from public.guest_schedule_reward_registrations gsrr
    where gsrr.user_id = v_user_id
    for update;

    if v_guest_marker.user_id is not null
       and v_guest_marker.schedule_request_id <> btrim(p_request_id) then
      raise exception using errcode = 'P0001', message = 'guest_schedule_request_already_registered';
    end if;
    if v_guest_marker.user_id is not null
       and (
         v_guest_marker.plan_start_date <> v_request.start_date
         or v_guest_marker.plan_days <> v_request.days
         or v_guest_marker.plan_item_count <> v_request.schedule_item_count
       ) then
      raise exception using errcode = 'P0001', message = 'guest_schedule_request_changed';
    end if;
    if exists (
      select 1
      from public.guest_schedule_reward_registrations gsrr
      where gsrr.schedule_request_id = btrim(p_request_id)
        and gsrr.user_id <> v_user_id
    ) then
      raise exception using errcode = 'P0001', message = 'guest_schedule_request_claimed';
    end if;

  end if;

  -- Validate the complete server-side schedule range for both modes. Member
  -- manifests must enumerate this exact set; Guest manifests may be a future,
  -- incomplete subset of it.
  select
    count(*)::integer,
    count(distinct lsi.schedule_date)::integer,
    array_agg(lsi.id order by lsi.id),
    encode(extensions.digest(string_agg(lsi.id::text, ',' order by lsi.id), 'sha256'), 'hex'),
    encode(extensions.digest(string_agg(
      jsonb_build_array(
        lsi.id,
        lsi.schedule_date,
        lsi.start_time::text,
        lsi.title,
        lsi.category,
        lsi.source_type,
        lsi.source_id
      )::text,
      E'\n' order by lsi.id
    ), 'sha256'), 'hex')
  into
    v_full_item_count,
    v_full_day_count,
    v_full_item_ids,
    v_full_item_id_hash,
    v_full_manifest_hash
  from public.lifestyle_schedule_items lsi
  where lsi.user_id = v_user_id
    and lsi.ai_generated = true
    and lsi.schedule_date >= v_request.start_date
    and lsi.schedule_date < v_request.start_date + v_request.days;

  if v_full_item_count <> v_request.schedule_item_count
     or v_full_day_count <> v_request.days
     or exists (
       select 1
       from public.lifestyle_schedule_items lsi
       where lsi.user_id = v_user_id
         and lsi.ai_generated = true
         and lsi.schedule_date >= v_request.start_date
         and lsi.schedule_date < v_request.start_date + v_request.days
       group by lsi.schedule_date
       having count(*) not between 10 and 11
           or count(distinct lsi.start_time) <> count(*)
     ) then
    if v_request.actor_mode = 'initial_guest' then
      raise exception using errcode = 'P0001', message = 'guest_schedule_plan_invalid';
    end if;
    raise exception using errcode = 'P0001', message = 'member_schedule_plan_invalid';
  end if;

  if v_request.actor_mode = 'member_new'
     and v_manifest_hash <> v_full_item_id_hash then
    raise exception using errcode = 'P0001', message = 'member_schedule_manifest_mismatch';
  end if;
  if v_request.actor_mode = 'initial_guest'
     and v_guest_marker.user_id is not null
     and v_guest_marker.manifest_hash <> v_full_manifest_hash then
    raise exception using errcode = 'P0001', message = 'guest_schedule_request_changed';
  end if;

  if v_request.actor_mode = 'initial_guest' then
    if v_guest_marker.user_id is null then
      select coalesce(array_agg(lsi.id order by lsi.id), '{}'::uuid[])
      into v_guest_eligible_item_ids
      from public.lifestyle_schedule_items lsi
      where lsi.user_id = v_user_id
        and lsi.id = any(v_full_item_ids)
        and lsi.is_completed = false
        and ((lsi.schedule_date + lsi.start_time) at time zone 'Asia/Ho_Chi_Minh') > now();
    else
      v_guest_eligible_item_ids := v_guest_marker.eligible_item_ids;
    end if;
  end if;

  select count(distinct lsi.id)::integer
  into v_matched_count
  from jsonb_array_elements(p_items) item
  join public.lifestyle_schedule_items lsi
    on lsi.id = coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
   and lsi.user_id = v_user_id
  where lsi.is_completed = false
    and lsi.ai_generated = true;

  if v_matched_count <> v_item_count then
    raise exception using errcode = 'P0001', message = 'schedule_items_not_found';
  end if;

  if v_request.actor_mode = 'initial_guest' and exists (
    select 1
    from jsonb_array_elements(p_items) item
    where not (
      coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
      = any(v_guest_eligible_item_ids)
    )
  ) then
    raise exception using errcode = 'P0001', message = 'guest_schedule_item_not_in_pinned_plan';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    join public.lifestyle_schedule_items lsi
      on lsi.id = coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
     and lsi.user_id = v_user_id
    where lsi.schedule_date < v_request.start_date
       or lsi.schedule_date >= v_request.start_date + v_request.days
  ) then
    raise exception using errcode = 'P0001', message = 'schedule_items_outside_request_range';
  end if;

  if v_request.actor_mode = 'member_new' and exists (
    select 1
    from jsonb_array_elements(p_items) item
    join public.lifestyle_schedule_items lsi
      on lsi.id = coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
     and lsi.user_id = v_user_id
    group by lsi.schedule_date
    having count(*) <> 10
        or count(distinct lsi.id) <> 10
        or count(distinct lsi.start_time) <> 10
  ) then
    raise exception using errcode = 'P0001', message = 'schedule_day_must_have_10_items';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    join public.lifestyle_schedule_items lsi
      on lsi.id = coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
     and lsi.user_id = v_user_id
    where ((lsi.schedule_date + lsi.start_time) at time zone 'Asia/Ho_Chi_Minh') <= now()
  ) then
    raise exception using errcode = 'P0001', message = 'schedule_window_must_be_future';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    join public.schedule_reward_eligibilities sre
      on sre.user_id = v_user_id
     and sre.schedule_item_id = coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
    where sre.schedule_request_id <> btrim(p_request_id)
  ) then
    raise exception using errcode = 'P0001', message = 'schedule_item_already_registered';
  end if;

  select hs.id into v_subject_id
  from public.health_subjects hs
  where hs.owner_user_id = v_user_id
    and hs.subject_type = 'self'
    and hs.is_active = true
  limit 1;

  if v_subject_id is null then
    raise exception using errcode = 'P0001', message = 'health_subject_required';
  end if;

  if v_request.actor_mode = 'initial_guest' then
    insert into public.guest_schedule_reward_registrations (
      user_id,
      schedule_request_id,
      plan_start_date,
      plan_days,
      plan_item_count,
      manifest_hash,
      plan_item_ids,
      eligible_item_ids,
      first_registration_idempotency_key
    )
    values (
      v_user_id,
      btrim(p_request_id),
      v_request.start_date,
      v_request.days,
      v_request.schedule_item_count,
      v_full_manifest_hash,
      v_full_item_ids,
      v_guest_eligible_item_ids,
      btrim(p_idempotency_key)
    )
    on conflict (user_id) do nothing;
  else
    insert into public.member_schedule_reward_registrations (
      schedule_request_id,
      user_id,
      plan_start_date,
      plan_days,
      plan_item_count,
      manifest_hash,
      registration_idempotency_key
    )
    values (
      btrim(p_request_id),
      v_user_id,
      v_request.start_date,
      v_request.days,
      v_request.schedule_item_count,
      v_full_manifest_hash,
      btrim(p_idempotency_key)
    );
  end if;

  insert into public.schedule_reward_eligibilities (
    user_id,
    subject_id,
    schedule_item_id,
    schedule_request_id,
    schedule_date,
    start_time,
    window_start,
    window_end,
    title_snapshot,
    category_snapshot,
    source_type_snapshot,
    source_id_snapshot,
    registration_idempotency_key
  )
  select
    v_user_id,
    v_subject_id,
    lsi.id,
    btrim(p_request_id),
    lsi.schedule_date,
    lsi.start_time,
    ((lsi.schedule_date + lsi.start_time) at time zone 'Asia/Ho_Chi_Minh'),
    ((lsi.schedule_date + lsi.start_time) at time zone 'Asia/Ho_Chi_Minh') + interval '30 minutes',
    lsi.title,
    lsi.category,
    lsi.source_type,
    lsi.source_id,
    btrim(p_idempotency_key)
  from jsonb_array_elements(p_items) item
  join public.lifestyle_schedule_items lsi
    on lsi.id = coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
   and lsi.user_id = v_user_id
  on conflict (user_id, schedule_item_id) do nothing;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'eligibility_id', sre.id,
        'schedule_item_id', sre.schedule_item_id,
        'schedule_date', sre.schedule_date,
        'window_start', sre.window_start,
        'window_end', sre.window_end,
        'status', sre.status
      ) order by sre.window_start
    ),
    '[]'::jsonb
  )
  into v_result
  from public.schedule_reward_eligibilities sre
  where sre.user_id = v_user_id
    and sre.schedule_request_id = btrim(p_request_id)
    and sre.schedule_item_id in (
      select coalesce(item ->> 'schedule_item_id', item ->> 'id')::uuid
      from jsonb_array_elements(p_items) item
    );

  if jsonb_array_length(v_result) <> v_item_count then
    raise exception using errcode = 'P0001', message = 'eligibility_registration_conflict';
  end if;

  select count(*)::integer
  into v_request_eligible_count
  from public.schedule_reward_eligibilities sre
  where sre.user_id = v_user_id
    and sre.schedule_request_id = btrim(p_request_id);

  if v_request_eligible_count > v_request.schedule_item_count then
    raise exception using errcode = 'P0001', message = 'schedule_request_eligibility_limit_exceeded';
  end if;

  if v_request.actor_mode = 'initial_guest' then
    update public.guest_schedule_reward_registrations gsrr
    set registered_item_count = v_request_eligible_count
    where gsrr.user_id = v_user_id
      and gsrr.schedule_request_id = btrim(p_request_id);
  else
    if v_request_eligible_count <> v_request.schedule_item_count then
      raise exception using errcode = 'P0001', message = 'member_schedule_manifest_incomplete';
    end if;
    update public.member_schedule_reward_registrations msrr
    set registered_item_count = v_request_eligible_count
    where msrr.schedule_request_id = btrim(p_request_id)
      and msrr.user_id = v_user_id;
  end if;

  return jsonb_build_object(
    'request_id', btrim(p_request_id),
    'registered_count', v_item_count,
    'eligibilities', v_result,
    'idempotent_replay', false
  );
end;
$_$;


--
-- Name: remove_my_familyplus_member("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."remove_my_familyplus_member"("p_member_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := public.assert_current_user_familyplus();
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
begin
  if p_member_id is null or v_idempotency_key is null then
    raise exception 'INVALID_FAMILYPLUS_REMOVE' using errcode = '22023';
  end if;

  update public.family_members fm
  set
    status = 'removed',
    last_idempotency_key = v_idempotency_key,
    updated_at = now()
  from public.family_groups fg
  where fm.id = p_member_id
    and fm.family_group_id = fg.id
    and fg.owner_user_id = v_user_id
    and fg.status = 'active';

  if not found then
    raise exception 'FAMILYPLUS_MEMBER_NOT_FOUND' using errcode = '22023';
  end if;

  return public.familyplus_context_for_user(v_user_id);
end;
$$;


--
-- Name: request_sale_participation("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."request_sale_participation"("p_terms_version" "text", "p_device_hash" "text") RETURNS TABLE("sale_status" "text", "referral_code" "text", "terms_version" "text", "approved_at" timestamp with time zone, "note" "text", "payout_profile_complete" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_existing_status public.nb_sale_status;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;

  if nullif(btrim(p_terms_version), '') is null then
    raise exception 'TERMS_VERSION_REQUIRED' using errcode = '22023';
  end if;

  if nullif(btrim(p_device_hash), '') is null then
    raise exception 'DEVICE_HASH_REQUIRED' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.membership_subscriptions ms
    where ms.user_id = v_user_id
      and ms.plan_code in ('plus', 'family_plus')
      and ms.status = 'active'
      and ms.starts_at <= now()
      and (ms.ends_at is null or ms.ends_at > now())
  ) then
    raise exception 'SALE_REQUIRES_ACTIVE_PAID_PLAN' using errcode = '42501';
  end if;

  select status into v_existing_status
  from public.sale_profiles
  where user_id = v_user_id
  for update;

  if v_existing_status in ('suspended', 'closed') then
    raise exception 'SALE_STATUS_REQUIRES_SUPPORT' using errcode = '42501';
  end if;

  if v_existing_status = 'active' then
    update public.sale_profiles
    set
      terms_version = btrim(p_terms_version),
      terms_accepted_at = now(),
      participation_device_hash = btrim(p_device_hash),
      note = 'Da cap nhat dieu le Sale trong ung dung.',
      updated_at = now()
    where user_id = v_user_id;
  else
    insert into public.sale_profiles (
      user_id,
      status,
      terms_version,
      terms_accepted_at,
      participation_device_hash,
      note
    )
    values (
      v_user_id,
      'pending',
      btrim(p_terms_version),
      now(),
      btrim(p_device_hash),
      'Da gui yeu cau Sale; dang cho Admin duyet.'
    )
    on conflict (user_id) do update
    set
      status = 'pending',
      terms_version = excluded.terms_version,
      terms_accepted_at = excluded.terms_accepted_at,
      participation_device_hash = excluded.participation_device_hash,
      note = excluded.note,
      updated_at = now();
  end if;

  return query select * from public.get_my_sale_state();
end;
$$;


--
-- Name: request_sale_point_conversion(integer, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."request_sale_point_conversion"("p_requested_point_cents" integer, "p_idempotency_key" "text") RETURNS TABLE("id" "text", "requested_point_cents" integer, "money_amount_cents" integer, "currency" "text", "status" "text", "requested_at" timestamp with time zone, "reviewed_at" timestamp with time zone, "note" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := public.require_active_sale_user();
  v_config jsonb := '{}'::jsonb;
  v_enabled boolean := false;
  v_rate numeric := 0;
  v_minimum integer := 0;
  v_currency text := 'VND';
  v_approved integer := 0;
  v_held integer := 0;
  v_available integer := 0;
  v_conversion_id uuid;
  v_payout public.sale_payout_profiles%rowtype;
begin
  if p_requested_point_cents is null or p_requested_point_cents <= 0 then
    raise exception 'INVALID_CONVERSION_POINTS' using errcode = '22023';
  end if;

  select config_value into v_config
  from public.system_config_versions
  where config_key = 'sale_point_conversion'
    and status = 'active'
  order by created_at desc
  limit 1;

  v_config := coalesce(v_config, '{}'::jsonb);
  v_enabled := coalesce((v_config ->> 'enabled')::boolean, false);
  v_rate := coalesce((v_config ->> 'point_to_money_rate')::numeric, 0);
  v_minimum := coalesce((v_config ->> 'minimum_point_cents')::integer, 0);
  v_currency := coalesce(nullif(v_config ->> 'currency', ''), 'VND');

  if not v_enabled or v_rate <= 0 then
    raise exception 'SALE_CONVERSION_DISABLED' using errcode = '42501';
  end if;

  select * into v_payout
  from public.sale_payout_profiles spp
  where spp.sale_user_id = v_user_id;

  if not found then
    raise exception 'SALE_PAYOUT_PROFILE_REQUIRED' using errcode = '42501';
  end if;

  if p_requested_point_cents < v_minimum then
    raise exception 'SALE_CONVERSION_MINIMUM_NOT_MET' using errcode = '22023';
  end if;

  select (
    select coalesce(sum(amount_cents), 0)::integer
    from public.commission_records
    where receiver_user_id = v_user_id
      and status in ('pending', 'approved')
      and available_at <= now()
  ) + (
    select coalesce(sum(point_delta_cents), 0)::integer
    from public.sale_point_adjustments
    where sale_user_id = v_user_id
      and status = 'approved'
  ) into v_approved;

  select coalesce(sum(requested_point_cents), 0)::integer into v_held
  from public.sale_point_conversions
  where sale_user_id = v_user_id
    and status in ('requested', 'pending_review', 'approved', 'paid');

  v_available := greatest(v_approved - v_held, 0);

  if p_requested_point_cents > v_available then
    raise exception 'SALE_CONVERSION_POINTS_EXCEED_AVAILABLE' using errcode = '22023';
  end if;

  insert into public.sale_point_conversions (
    sale_user_id,
    requested_point_cents,
    point_to_money_rate,
    money_amount_cents,
    currency,
    status,
    idempotency_key,
    metadata
  )
  values (
    v_user_id,
    p_requested_point_cents,
    v_rate,
    round(p_requested_point_cents * v_rate)::integer,
    v_currency,
    'requested',
    nullif(btrim(p_idempotency_key), ''),
    jsonb_build_object(
      'citizen_id',
      v_payout.citizen_id,
      'bank_bin',
      v_payout.bank_bin,
      'bank_name',
      v_payout.bank_name,
      'bank_account_number',
      v_payout.bank_account_number,
      'bank_account_name',
      v_payout.bank_account_name,
      'payment_content',
      concat('SALE ', substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))
    )
  )
  on conflict (sale_user_id, idempotency_key)
  where idempotency_key is not null
  do update set metadata = public.sale_point_conversions.metadata
  returning public.sale_point_conversions.id into v_conversion_id;

  return query
  select
    spc.id::text,
    spc.requested_point_cents,
    spc.money_amount_cents,
    spc.currency,
    spc.status,
    spc.requested_at,
    spc.reviewed_at,
    spc.review_reason
  from public.sale_point_conversions spc
  where spc.id = v_conversion_id;
end;
$$;


--
-- Name: require_active_sale_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."require_active_sale_user"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null or not exists (
    select 1
    from public.sale_profiles sp
    where sp.user_id = v_user_id
      and sp.status = 'active'
  ) then
    raise exception 'SALE_ACCESS_REQUIRED' using errcode = '42501';
  end if;

  return v_user_id;
end;
$$;


--
-- Name: reward_text_is_vietnamese("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reward_text_is_vietnamese"("p_text" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    nullif(btrim(coalesce(p_text, '')), '') is not null
    and p_text ~ '[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ]'
    and p_text !~ '(Ã.|Â.|Ä.|Æ.|�)'
$$;


--
-- Name: save_early_access_lead("jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."save_early_access_lead"("p_lead" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'early_access_private'
    AS $_$
declare
  v_phone text := p_lead ->> 'phone_e164';
  v_phone_hash text := p_lead ->> 'phone_hash';
  v_inserted integer;
begin
  if jsonb_typeof(p_lead) <> 'object'
     or v_phone is null or v_phone !~ '^\+84(3|5|7|8|9)[0-9]{8}$'
     or v_phone_hash is null or v_phone_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'INVALID_EARLY_ACCESS_LEAD' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_phone_hash, 0));
  if exists (
    select 1 from early_access_private.promo_phone_suppressions
    where phone_hash = v_phone_hash
  ) then
    return false;
  end if;

  insert into public.early_access_leads (
    phone_e164, phone_display, source, app_version, vip_support_requested,
    privacy_consent, promotion_code, requested_plan, vip_duration_days,
    vip_grant_status, phone_hash, full_name, age, gender, address, status,
    utm_source, utm_medium, utm_campaign, referrer, landing_path, user_agent
  ) values (
    v_phone, p_lead ->> 'phone_display', 'nanobio_web', p_lead ->> 'app_version',
    true, true, 'EARLY_ACCESS_PLUS_30D', 'plus', 30, 'pending_account_link',
    v_phone_hash, p_lead ->> 'full_name', (p_lead ->> 'age')::smallint,
    p_lead ->> 'gender', p_lead ->> 'address', 'new',
    p_lead ->> 'utm_source', p_lead ->> 'utm_medium', p_lead ->> 'utm_campaign',
    p_lead ->> 'referrer', coalesce(p_lead ->> 'landing_path', '/nanobio'),
    p_lead ->> 'user_agent'
  ) on conflict (phone_e164) do nothing;
  get diagnostics v_inserted = row_count;
  return v_inserted = 1;
end;
$_$;


--
-- Name: schedule_health_action_reward_points("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."schedule_health_action_reward_points"("p_action_type" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case btrim(coalesce(p_action_type, ''))
    when 'hydration' then 4
    when 'mood_stress' then 5
    when 'sleep_checkin' then 6
    when 'weight_checkin' then 4
    when 'quick_complete' then 5
    else 0
  end
$$;


