--
-- Name: early_access_leads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."early_access_leads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "phone_e164" "text" NOT NULL,
    "phone_display" "text",
    "source" "text" DEFAULT 'nanobio_web'::"text" NOT NULL,
    "app_version" "text",
    "vip_support_requested" boolean DEFAULT true NOT NULL,
    "privacy_consent" boolean DEFAULT false NOT NULL,
    "promotion_code" "text" DEFAULT 'EARLY_ACCESS_PLUS_30D'::"text" NOT NULL,
    "requested_plan" "text" DEFAULT 'plus'::"text" NOT NULL,
    "vip_duration_days" integer DEFAULT 30 NOT NULL,
    "vip_grant_status" "text" DEFAULT 'pending_account_link'::"text" NOT NULL,
    "claimed_user_id" "uuid",
    "vip_granted_at" timestamp with time zone,
    "vip_expires_at" timestamp with time zone,
    "full_name" "text",
    "status" "text" DEFAULT 'new'::"text" NOT NULL,
    "utm_source" "text",
    "utm_medium" "text",
    "utm_campaign" "text",
    "referrer" "text",
    "landing_path" "text" DEFAULT '/nanobio'::"text" NOT NULL,
    "user_agent" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "phone_hash" "text",
    "age" smallint,
    "gender" "text",
    "address" "text",
    CONSTRAINT "early_access_address_length_ck" CHECK ((("address" IS NULL) OR ("char_length"("address") <= 512))),
    CONSTRAINT "early_access_age_ck" CHECK ((("age" IS NULL) OR (("age" >= 18) AND ("age" <= 120)))),
    CONSTRAINT "early_access_consent_ck" CHECK (("privacy_consent" = true)),
    CONSTRAINT "early_access_full_name_length_ck" CHECK ((("full_name" IS NULL) OR ("char_length"("full_name") <= 120))),
    CONSTRAINT "early_access_gender_ck" CHECK ((("gender" IS NULL) OR ("gender" = ANY (ARRAY['male'::"text", 'female'::"text", 'other'::"text", 'prefer_not_to_say'::"text"])))),
    CONSTRAINT "early_access_landing_path_ck" CHECK (("landing_path" = ANY (ARRAY['/nanobio'::"text", '/nanobio/privacy'::"text"]))),
    CONSTRAINT "early_access_lead_status_ck" CHECK (("status" = ANY (ARRAY['new'::"text", 'contacted'::"text", 'registered'::"text", 'converted'::"text", 'rejected'::"text"]))),
    CONSTRAINT "early_access_phone_e164_ck" CHECK (("phone_e164" ~ '^\+84(3|5|7|8|9)[0-9]{8}$'::"text")),
    CONSTRAINT "early_access_phone_hash_ck" CHECK ((("phone_hash" IS NULL) OR ("phone_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "early_access_plan_ck" CHECK (("requested_plan" = 'plus'::"text")),
    CONSTRAINT "early_access_referrer_length_ck" CHECK ((("referrer" IS NULL) OR ("char_length"("referrer") <= 512))),
    CONSTRAINT "early_access_user_agent_length_ck" CHECK ((("user_agent" IS NULL) OR ("char_length"("user_agent") <= 512))),
    CONSTRAINT "early_access_utm_campaign_length_ck" CHECK ((("utm_campaign" IS NULL) OR ("char_length"("utm_campaign") <= 100))),
    CONSTRAINT "early_access_utm_medium_length_ck" CHECK ((("utm_medium" IS NULL) OR ("char_length"("utm_medium") <= 100))),
    CONSTRAINT "early_access_utm_source_length_ck" CHECK ((("utm_source" IS NULL) OR ("char_length"("utm_source") <= 100))),
    CONSTRAINT "early_access_vip_days_ck" CHECK (("vip_duration_days" = 30)),
    CONSTRAINT "early_access_vip_status_ck" CHECK (("vip_grant_status" = ANY (ARRAY['pending_account_link'::"text", 'pending_activation'::"text", 'active'::"text", 'expired'::"text", 'cancelled'::"text"])))
);


