    "product_access_status" "public"."nb_product_access_status" DEFAULT 'guest'::"text" NOT NULL,
    "sale_status" "public"."nb_sale_status" DEFAULT 'none'::"text" NOT NULL,
    "is_anonymous" boolean DEFAULT false NOT NULL,
    "onboarding_status" "public"."nb_onboarding_status" DEFAULT 'not_started'::"text" NOT NULL,
    "onboarding_completed_at" timestamp with time zone,
