);


--
-- Name: effective_user_access; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."effective_user_access" WITH ("security_invoker"='true') AS
 SELECT "id" AS "user_id",
    "is_anonymous",
        CASE
            WHEN ("is_anonymous" AND (("product_access_status")::"text" = 'guest'::"text")) THEN 'guest'::"text"
            ELSE ("public"."current_plan_for_user"("id"))::"text"
        END AS "product_access",
    "public"."current_plan_for_user"("id") AS "membership_plan",
    "sale_status",
    "onboarding_status",
    "updated_at"
   FROM "public"."users" "u";


