    "reward_type_snapshot" "text" DEFAULT 'voucher'::"text" NOT NULL,
    "received_at" timestamp with time zone,
    "received_by" "uuid",
    CONSTRAINT "wellness_reward_redemptions_points_spent_check" CHECK (("points_spent" > 0)),
    CONSTRAINT "wellness_reward_redemptions_reward_type_snapshot_check" CHECK (("reward_type_snapshot" = ANY (ARRAY['voucher'::"text", 'physical'::"text"]))),
    CONSTRAINT "wellness_reward_redemptions_status_check" CHECK (("status" = ANY (ARRAY['issued'::"text", 'cancelled'::"text", 'redeemed'::"text", 'received'::"text"])))
);


--
-- Name: wellness_reward_wallets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."wellness_reward_wallets" (
    "user_id" "uuid" NOT NULL,
    "pending_points" integer DEFAULT 0 NOT NULL,
    "available_points" integer DEFAULT 0 NOT NULL,
    "lifetime_earned_points" integer DEFAULT 0 NOT NULL,
    "lifetime_spent_points" integer DEFAULT 0 NOT NULL,
    "lifetime_refunded_points" integer DEFAULT 0 NOT NULL,
    "lock_version" bigint DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "wellness_reward_wallets_available_points_check" CHECK (("available_points" >= 0)),
    CONSTRAINT "wellness_reward_wallets_lifetime_earned_points_check" CHECK (("lifetime_earned_points" >= 0)),
    CONSTRAINT "wellness_reward_wallets_lifetime_refunded_points_check" CHECK (("lifetime_refunded_points" >= 0)),
    CONSTRAINT "wellness_reward_wallets_lifetime_spent_points_check" CHECK (("lifetime_spent_points" >= 0)),
    CONSTRAINT "wellness_reward_wallets_pending_points_check" CHECK (("pending_points" >= 0))
);


--
-- Name: buckets; Type: TABLE; Schema: storage; Owner: -
--

CREATE TABLE "storage"."buckets" (
    "id" "text" NOT NULL,
    "name" "text" NOT NULL,
    "owner" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "public" boolean DEFAULT false,
    "avif_autodetection" boolean DEFAULT false,
    "file_size_limit" bigint,
    "allowed_mime_types" "text"[],
    "owner_id" "text",
    "type" "storage"."buckettype" DEFAULT 'STANDARD'::"storage"."buckettype" NOT NULL,
    "versioning_status" "text" DEFAULT 'DISABLED'::"text" NOT NULL,
    "lifecycle_configuration" "jsonb",
    "lifecycle_configuration_generation" "uuid",
    CONSTRAINT "buckets_lifecycle_configuration_pair_check" CHECK ((("lifecycle_configuration" IS NULL) = ("lifecycle_configuration_generation" IS NULL))),
    CONSTRAINT "buckets_lifecycle_configuration_shape_check" CHECK ((("lifecycle_configuration" IS NULL) OR (("jsonb_typeof"("lifecycle_configuration") = 'object'::"text") AND ("lifecycle_configuration" ? 'rules'::"text") AND
CASE
    WHEN ("jsonb_typeof"(("lifecycle_configuration" -> 'rules'::"text")) = 'array'::"text") THEN (("jsonb_array_length"(("lifecycle_configuration" -> 'rules'::"text")) >= 1) AND ("jsonb_array_length"(("lifecycle_configuration" -> 'rules'::"text")) <= 1000))
    ELSE false
END))),
    CONSTRAINT "buckets_lifecycle_configuration_standard_only_check" CHECK ((("type" = 'STANDARD'::"storage"."buckettype") OR (("lifecycle_configuration" IS NULL) AND ("lifecycle_configuration_generation" IS NULL)))),
    CONSTRAINT "buckets_versioning_dark_check" CHECK (("versioning_status" = 'DISABLED'::"text")),
    CONSTRAINT "buckets_versioning_standard_only_check" CHECK ((("type" = 'STANDARD'::"storage"."buckettype") OR ("versioning_status" = 'DISABLED'::"text"))),
    CONSTRAINT "buckets_versioning_status_check" CHECK (("versioning_status" = ANY (ARRAY['DISABLED'::"text", 'ENABLED'::"text", 'SUSPENDED'::"text"])))
);


