-- Name: family_groups family_groups_select_allowed; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "family_groups_select_allowed" ON "public"."family_groups" FOR SELECT TO "authenticated" USING ((("owner_user_id" = ( SELECT "auth"."uid"() AS "uid")) OR (EXISTS ( SELECT 1
   FROM "public"."family_members" "fm"
  WHERE (("fm"."family_group_id" = "fm"."id") AND ("fm"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("fm"."status" = 'active'::"text"))))));


