   FROM "public"."family_groups" "fg"
  WHERE (("fg"."id" = "family_members"."family_group_id") AND ("fg"."owner_user_id" = ( SELECT "auth"."uid"() AS "uid"))))) OR (EXISTS ( SELECT 1
   FROM "public"."family_members" "actor"
  WHERE (("actor"."family_group_id" = "family_members"."family_group_id") AND ("actor"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("actor"."status" = 'active'::"text") AND ("actor"."can_view" = true))))));


