20261006090000	{begin,"do $$\nbegin\n  if to_regclass('public.sleep_safety_runtime_config') is null\n    or to_regclass('public.sleep_safety_contacts') is null\n    or to_regclass('public.sleep_safety_dispatches') is null then\n    raise exception 'M31_SCHEMA_MISSING_APPLY_CANONICAL_SCHEMA_FIRST';\n  end if;\nend;\n$$","alter table public.sleep_safety_runtime_config\n  add column if not exists zalo_enabled boolean not null default false,\n  add column if not exists phone_fallback_enabled boolean not null default false","alter table public.sleep_safety_contacts\n  add column if not exists allow_zalo_alert boolean not null default false,\n  add column if not exists allow_phone_fallback boolean not null default true","alter table public.sleep_safety_dispatches\n  drop constraint if exists sleep_safety_dispatches_channel_check","alter table public.sleep_safety_dispatches\n  add constraint sleep_safety_dispatches_channel_check\n  check (channel in ('sms', 'voice', 'zalo'))","create or replace function public.upsert_sleep_safety_contact(\n  p_contact_id uuid,\n  p_name text,\n  p_relationship text,\n  p_phone_e164 text,\n  p_priority integer,\n  p_allow_zalo_alert boolean,\n  p_allow_phone_fallback boolean\n)\nreturns setof public.sleep_safety_contacts\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_uid uuid := (select auth.uid());\n  v_existing public.sleep_safety_contacts%rowtype;\nbegin\n  if v_uid is null then\n    raise exception 'authentication_required';\n  end if;\n  if p_priority not between 1 and 3 then\n    raise exception 'sleep_safety_priority_invalid';\n  end if;\n  if p_phone_e164 !~ '^\\\\\\\\+[1-9][0-9]{7,14}$' then\n    raise exception 'sleep_safety_phone_invalid';\n  end if;\n\n  if p_contact_id is null then\n    if (\n      select count(*)\n      from public.sleep_safety_contacts c\n      where c.user_id = v_uid and c.active = true\n    ) >= 3 then\n      raise exception 'sleep_safety_contact_limit';\n    end if;\n\n    return query\n    insert into public.sleep_safety_contacts (\n      user_id, name, relationship, phone_e164, priority,\n      allow_zalo_alert, allow_phone_fallback\n    ) values (\n      v_uid, btrim(p_name), btrim(p_relationship), p_phone_e164, p_priority,\n      coalesce(p_allow_zalo_alert, false), coalesce(p_allow_phone_fallback, true)\n    )\n    returning *;\n    return;\n  end if;\n\n  select * into v_existing\n  from public.sleep_safety_contacts c\n  where c.id = p_contact_id and c.user_id = v_uid\n  for update;\n\n  if not found then\n    raise exception 'sleep_safety_contact_not_found';\n  end if;\n\n  return query\n  update public.sleep_safety_contacts c\n  set name = btrim(p_name),\n      relationship = btrim(p_relationship),\n      phone_e164 = p_phone_e164,\n      priority = p_priority,\n      verification_status = case\n        when c.phone_e164 is distinct from p_phone_e164 then 'pending'\n        else c.verification_status\n      end,\n      verified_at = case\n        when c.phone_e164 is distinct from p_phone_e164 then null\n        else c.verified_at\n      end,\n      allow_zalo_alert = coalesce(p_allow_zalo_alert, false),\n      allow_phone_fallback = coalesce(p_allow_phone_fallback, true),\n      active = true,\n      updated_at = now()\n  where c.id = p_contact_id and c.user_id = v_uid\n  returning c.*;\nend;\n$$","revoke all on function public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean\n) from public, anon","grant execute on function public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean\n) to authenticated, service_role",commit}	m31_zalo_phone_fallback
20261006100000	{begin,"-- PostgreSQL treats backslashes literally in standard-conforming strings. The\n-- earlier `\\\\\\\\+` expression therefore rejected valid E.164 phone numbers.\n-- Replace the table constraint with an escape-free literal-plus character set.\nalter table public.sleep_safety_contacts\n  drop constraint if exists sleep_safety_contacts_phone_e164_check","alter table public.sleep_safety_contacts\n  add constraint sleep_safety_contacts_phone_e164_check\n  check (phone_e164 ~ '^[+][1-9][0-9]{7,14}$')","-- Patch both supported RPC signatures while preserving their existing logic,\n-- owner and grants. Fail closed if either function has drifted from the known\n-- faulty pattern instead of silently rewriting an unexpected definition.\ndo $fix_phone_regex$\ndeclare\n  v_oid oid;\n  v_definition text;\n  v_old_pattern text := $old$'^\\\\\\\\+[1-9][0-9]{7,14}$'$old$;\n  v_new_pattern text := $new$'^[+][1-9][0-9]{7,14}$'$new$;\nbegin\n  foreach v_oid in array array[\n    'public.upsert_sleep_safety_contact(uuid,text,text,text,integer)'::regprocedure::oid,\n    'public.upsert_sleep_safety_contact(uuid,text,text,text,integer,boolean,boolean)'::regprocedure::oid\n  ] loop\n    v_definition := pg_get_functiondef(v_oid);\n    if strpos(v_definition, v_old_pattern) = 0 then\n      raise exception 'sleep_safety_contact_phone_regex_drift_%',\n        v_oid::regprocedure;\n    end if;\n    execute replace(v_definition, v_old_pattern, v_new_pattern);\n  end loop;\nend;\n$fix_phone_regex$",commit}	m31_contact_phone_regex_fix
20261006110000	{begin,"do $$\nbegin\n  if to_regclass('public.sleep_safety_contacts') is null then\n    raise exception 'M31_SCHEMA_MISSING_APPLY_CANONICAL_SCHEMA_FIRST';\n  end if;\n  if to_regprocedure(\n    'public.upsert_sleep_safety_contact(uuid,text,text,text,integer,boolean,boolean)'\n  ) is null then\n    raise exception 'M31_CONTACT_RPC_MISSING_APPLY_CANONICAL_SCHEMA_FIRST';\n  end if;\nend;\n$$","alter table public.sleep_safety_contacts\n  add column if not exists allow_unverified_voice_alert boolean not null default false","comment on column public.sleep_safety_contacts.allow_unverified_voice_alert is\n  'Explicit opt-in for automated voice alerts while this contact number is unverified.'","-- Keep the legacy 5- and 7-argument RPCs intact. New clients use this overload.\ncreate or replace function public.upsert_sleep_safety_contact(\n  p_contact_id uuid,\n  p_name text,\n  p_relationship text,\n  p_phone_e164 text,\n  p_priority integer,\n  p_allow_zalo_alert boolean,\n  p_allow_phone_fallback boolean,\n  p_allow_unverified_voice_alert boolean\n)\nreturns setof public.sleep_safety_contacts\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_contact public.sleep_safety_contacts%rowtype;\nbegin\n  select * into v_contact\n  from public.upsert_sleep_safety_contact(\n    p_contact_id,\n    p_name,\n    p_relationship,\n    p_phone_e164,\n    p_priority,\n    p_allow_zalo_alert,\n    p_allow_phone_fallback\n  );\n\n  update public.sleep_safety_contacts c\n  set allow_unverified_voice_alert = coalesce(\n        p_allow_unverified_voice_alert,\n        false\n      ),\n      updated_at = now()\n  where c.id = v_contact.id\n    and c.user_id = (select auth.uid())\n  returning c.* into v_contact;\n\n  return next v_contact;\nend;\n$$","revoke all on function public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean, boolean\n) from public, anon","grant execute on function public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean, boolean\n) to authenticated, service_role",commit}	m31_unverified_voice_alert
20261006120000	{begin,"do $$\nbegin\n  if to_regclass('public.sleep_safety_runtime_config') is null\n    or to_regclass('public.sleep_safety_contacts') is null\n    or to_regclass('public.sleep_safety_dispatches') is null then\n    raise exception 'M31_SCHEMA_MISSING_APPLY_CANONICAL_SCHEMA_FIRST';\n  end if;\n\n  -- Preserve any historical dispatch records instead of rewriting or deleting\n  -- them. This migration can tighten the channel constraint when no legacy\n  -- Zalo rows remain in the target project.\n  if exists (\n    select 1 from public.sleep_safety_dispatches where channel = 'zalo'\n  ) then\n    raise exception 'M31_LEGACY_ZALO_DISPATCH_ROWS_REQUIRE_REVIEW';\n  end if;\nend;\n$$","alter table public.sleep_safety_runtime_config\n  drop column if exists zalo_enabled","alter table public.sleep_safety_contacts\n  drop column if exists allow_zalo_alert","alter table public.sleep_safety_dispatches\n  drop constraint if exists sleep_safety_dispatches_channel_check","alter table public.sleep_safety_dispatches\n  add constraint sleep_safety_dispatches_channel_check\n  check (channel in ('sms', 'voice'))","-- Remove the deployed Zalo RPC overloads and expose only the current contact\n-- options. The original five-argument RPC remains for older app versions.\ndrop function if exists public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean, boolean\n)","drop function if exists public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean\n)","create function public.upsert_sleep_safety_contact(\n  p_contact_id uuid,\n  p_name text,\n  p_relationship text,\n  p_phone_e164 text,\n  p_priority integer,\n  p_allow_phone_fallback boolean,\n  p_allow_unverified_voice_alert boolean\n)\nreturns setof public.sleep_safety_contacts\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_contact public.sleep_safety_contacts%rowtype;\nbegin\n  select * into v_contact\n  from public.upsert_sleep_safety_contact(\n    p_contact_id,\n    p_name,\n    p_relationship,\n    p_phone_e164,\n    p_priority\n  );\n\n  update public.sleep_safety_contacts c\n  set allow_phone_fallback = coalesce(p_allow_phone_fallback, true),\n      allow_unverified_voice_alert = coalesce(\n        p_allow_unverified_voice_alert,\n        false\n      ),\n      active = true,\n      updated_at = now()\n  where c.id = v_contact.id\n    and c.user_id = (select auth.uid())\n  returning c.* into v_contact;\n\n  return next v_contact;\nend;\n$$","revoke all on function public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean\n) from public, anon","grant execute on function public.upsert_sleep_safety_contact(\n  uuid, text, text, text, integer, boolean, boolean\n) to authenticated, service_role",commit}	m31_remove_zalo_channel
20261007000000	{"-- NanoBio Website Early Access lead capture and durable IP rate limiting.\n-- Additive forward migration; do not run the canonical destructive rebuild remotely.\nbegin","create extension if not exists pgcrypto","create extension if not exists pg_cron","create schema if not exists early_access_private","revoke all on schema early_access_private from public, anon, authenticated, service_role","create table if not exists public.early_access_leads (\n  id uuid primary key default gen_random_uuid(),\n  phone_e164 text not null unique,\n  phone_display text,\n  source text not null default 'nanobio_web',\n  app_version text,\n  vip_support_requested boolean not null default true,\n  privacy_consent boolean not null default false,\n  promotion_code text not null default 'EARLY_ACCESS_PLUS_30D',\n  requested_plan text not null default 'plus',\n  vip_duration_days integer not null default 30,\n  vip_grant_status text not null default 'pending_account_link',\n  claimed_user_id uuid null references auth.users(id) on delete set null,\n  vip_granted_at timestamptz null,\n  vip_expires_at timestamptz null,\n  full_name text null,\n  status text not null default 'new',\n  utm_source text null,\n  utm_medium text null,\n  utm_campaign text null,\n  referrer text null,\n  landing_path text not null default '/nanobio',\n  user_agent text null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint early_access_phone_e164_ck check (phone_e164 ~ '^\\\\+84(3|5|7|8|9)[0-9]{8}$'),\n  constraint early_access_consent_ck check (privacy_consent = true),\n  constraint early_access_plan_ck check (requested_plan = 'plus'),\n  constraint early_access_vip_days_ck check (vip_duration_days = 30),\n  constraint early_access_vip_status_ck check (vip_grant_status in ('pending_account_link','pending_activation','active','expired','cancelled')),\n  constraint early_access_lead_status_ck check (status in ('new','contacted','registered','converted','rejected')),\n  constraint early_access_full_name_length_ck check (full_name is null or char_length(full_name) <= 120),\n  constraint early_access_utm_source_length_ck check (utm_source is null or char_length(utm_source) <= 100),\n  constraint early_access_utm_medium_length_ck check (utm_medium is null or char_length(utm_medium) <= 100),\n  constraint early_access_utm_campaign_length_ck check (utm_campaign is null or char_length(utm_campaign) <= 100),\n  constraint early_access_referrer_length_ck check (referrer is null or char_length(referrer) <= 512),\n  constraint early_access_landing_path_ck check (landing_path in ('/nanobio','/nanobio/privacy')),\n  constraint early_access_user_agent_length_ck check (user_agent is null or char_length(user_agent) <= 512)\n)","alter table public.early_access_leads add column if not exists full_name text null","alter table public.early_access_leads add column if not exists status text not null default 'new'","alter table public.early_access_leads add column if not exists utm_source text null","alter table public.early_access_leads add column if not exists utm_medium text null","alter table public.early_access_leads add column if not exists utm_campaign text null","alter table public.early_access_leads add column if not exists referrer text null","alter table public.early_access_leads add column if not exists landing_path text not null default '/nanobio'","alter table public.early_access_leads add column if not exists user_agent text null","do $$\nbegin\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_lead_status_ck') then\n    alter table public.early_access_leads add constraint early_access_lead_status_ck check (status in ('new','contacted','registered','converted','rejected'));\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_full_name_length_ck') then\n    alter table public.early_access_leads add constraint early_access_full_name_length_ck check (full_name is null or char_length(full_name) <= 120);\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_utm_source_length_ck') then\n    alter table public.early_access_leads add constraint early_access_utm_source_length_ck check (utm_source is null or char_length(utm_source) <= 100);\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_utm_medium_length_ck') then\n    alter table public.early_access_leads add constraint early_access_utm_medium_length_ck check (utm_medium is null or char_length(utm_medium) <= 100);\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_utm_campaign_length_ck') then\n    alter table public.early_access_leads add constraint early_access_utm_campaign_length_ck check (utm_campaign is null or char_length(utm_campaign) <= 100);\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_referrer_length_ck') then\n    alter table public.early_access_leads add constraint early_access_referrer_length_ck check (referrer is null or char_length(referrer) <= 512);\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_landing_path_ck') then\n    alter table public.early_access_leads add constraint early_access_landing_path_ck check (landing_path in ('/nanobio','/nanobio/privacy'));\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_user_agent_length_ck') then\n    alter table public.early_access_leads add constraint early_access_user_agent_length_ck check (user_agent is null or char_length(user_agent) <= 512);\n  end if;\nend\n$$","create index if not exists early_access_vip_grant_status_idx\n  on public.early_access_leads(vip_grant_status, created_at desc)","create index if not exists early_access_lead_status_created_idx\n  on public.early_access_leads(status, created_at desc)","alter table public.early_access_leads enable row level security","revoke all on table public.early_access_leads from public, anon, authenticated","grant select, insert, update on table public.early_access_leads to service_role","create or replace function public.set_early_access_updated_at()\nreturns trigger\nlanguage plpgsql\nsecurity invoker\nset search_path = public\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$","revoke all on function public.set_early_access_updated_at() from public, anon, authenticated, service_role","drop trigger if exists trg_early_access_updated_at on public.early_access_leads","create trigger trg_early_access_updated_at\n  before update on public.early_access_leads\n  for each row execute function public.set_early_access_updated_at()","create table if not exists early_access_private.rate_limits (\n  ip_hash text not null check (ip_hash ~ '^[0-9a-f]{64}$'),\n  window_started_at timestamptz not null,\n  request_count integer not null check (request_count between 1 and 10),\n  expires_at timestamptz not null,\n  primary key (ip_hash, window_started_at)\n)","alter table early_access_private.rate_limits enable row level security","revoke all on table early_access_private.rate_limits from public, anon, authenticated, service_role","create or replace function public.consume_early_access_rate_limit(\n  p_ip_hash text,\n  p_window_started_at timestamptz\n)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog\nas $$\ndeclare\n  v_request_count integer;\nbegin\n  if p_ip_hash is null or p_ip_hash !~ '^[0-9a-f]{64}$'\n     or p_window_started_at is null\n     or mod(extract(epoch from p_window_started_at)::bigint, 3600) <> 0 then\n    raise exception 'INVALID_EARLY_ACCESS_RATE_LIMIT_KEY' using errcode = '22023';\n  end if;\n\n  insert into early_access_private.rate_limits as rate_limits (\n    ip_hash, window_started_at, request_count, expires_at\n  ) values (\n    p_ip_hash, p_window_started_at, 1, p_window_started_at + interval '23 hours 55 minutes'\n  )\n  on conflict (ip_hash, window_started_at) do update\n    set request_count = rate_limits.request_count + 1,\n        expires_at = excluded.expires_at\n    where rate_limits.request_count < 10\n  returning request_count into v_request_count;\n\n  return v_request_count is not null;\nend;\n$$","revoke all on function public.consume_early_access_rate_limit(text, timestamptz) from public, anon, authenticated","grant execute on function public.consume_early_access_rate_limit(text, timestamptz) to service_role","create or replace function public.purge_early_access_rate_limits()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  delete from early_access_private.rate_limits where expires_at <= now();\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$","revoke all on function public.purge_early_access_rate_limits() from public, anon, authenticated, service_role","do $cron$\ndeclare\n  v_job_id bigint;\nbegin\n  for v_job_id in\n    select jobid from cron.job where jobname = 'nanobio-purge-early-access-rate-limits'\n  loop\n    perform cron.unschedule(v_job_id);\n  end loop;\n  perform cron.schedule(\n    'nanobio-purge-early-access-rate-limits',\n    '*/5 * * * *',\n    'select public.purge_early_access_rate_limits();'\n  );\nend\n$cron$",commit}	nanobio_early_access
20261007130000	{"-- NanoBio Early Access customer profile, status administration, and retention.\n-- Forward-only additive migration; never run the canonical sandbox rebuild remotely.\nbegin","alter table public.early_access_leads\n  add column if not exists phone_hash text null,\n  add column if not exists age smallint null,\n  add column if not exists gender text null,\n  add column if not exists address text null","do $$\nbegin\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_phone_hash_ck') then\n    alter table public.early_access_leads add constraint early_access_phone_hash_ck check (phone_hash is null or phone_hash ~ '^[0-9a-f]{64}$');\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_age_ck') then\n    alter table public.early_access_leads add constraint early_access_age_ck check (age is null or age between 18 and 120);\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_gender_ck') then\n    alter table public.early_access_leads add constraint early_access_gender_ck check (gender is null or gender in ('male','female','other','prefer_not_to_say'));\n  end if;\n  if not exists (select 1 from pg_constraint where conrelid = 'public.early_access_leads'::regclass and conname = 'early_access_address_length_ck') then\n    alter table public.early_access_leads add constraint early_access_address_length_ck check (address is null or char_length(address) <= 512);\n  end if;\nend\n$$","create index if not exists early_access_lead_retention_idx\n  on public.early_access_leads(status, created_at)\n  where status in ('registered','converted','rejected')","create table if not exists early_access_private.promo_phone_suppressions (\n  phone_hash text primary key check (phone_hash ~ '^[0-9a-f]{64}$'),\n  created_at timestamptz not null default now()\n)","alter table early_access_private.promo_phone_suppressions enable row level security","revoke all on table early_access_private.promo_phone_suppressions from public, anon, authenticated, service_role","create or replace function public.save_early_access_lead(p_lead jsonb)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, public, early_access_private\nas $$\ndeclare\n  v_phone text := p_lead ->> 'phone_e164';\n  v_phone_hash text := p_lead ->> 'phone_hash';\n  v_inserted integer;\nbegin\n  if jsonb_typeof(p_lead) <> 'object'\n     or v_phone is null or v_phone !~ '^\\\\+84(3|5|7|8|9)[0-9]{8}$'\n     or v_phone_hash is null or v_phone_hash !~ '^[0-9a-f]{64}$' then\n    raise exception 'INVALID_EARLY_ACCESS_LEAD' using errcode = '22023';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(v_phone_hash, 0));\n  if exists (\n    select 1 from early_access_private.promo_phone_suppressions\n    where phone_hash = v_phone_hash\n  ) then\n    return false;\n  end if;\n\n  insert into public.early_access_leads (\n    phone_e164, phone_display, source, app_version, vip_support_requested,\n    privacy_consent, promotion_code, requested_plan, vip_duration_days,\n    vip_grant_status, phone_hash, full_name, age, gender, address, status,\n    utm_source, utm_medium, utm_campaign, referrer, landing_path, user_agent\n  ) values (\n    v_phone, p_lead ->> 'phone_display', 'nanobio_web', p_lead ->> 'app_version',\n    true, true, 'EARLY_ACCESS_PLUS_30D', 'plus', 30, 'pending_account_link',\n    v_phone_hash, p_lead ->> 'full_name', (p_lead ->> 'age')::smallint,\n    p_lead ->> 'gender', p_lead ->> 'address', 'new',\n    p_lead ->> 'utm_source', p_lead ->> 'utm_medium', p_lead ->> 'utm_campaign',\n    p_lead ->> 'referrer', coalesce(p_lead ->> 'landing_path', '/nanobio'),\n    p_lead ->> 'user_agent'\n  ) on conflict (phone_e164) do nothing;\n  get diagnostics v_inserted = row_count;\n  return v_inserted = 1;\nend;\n$$","revoke all on function public.save_early_access_lead(jsonb) from public, anon, authenticated","grant execute on function public.save_early_access_lead(jsonb) to service_role","create or replace function public.admin_update_early_access_lead_status(\n  p_lead_id uuid,\n  p_status text,\n  p_actor_id uuid,\n  p_reason text,\n  p_idempotency_key text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, public\nas $$\ndeclare\n  v_old_status text;\n  v_existing_target text;\nbegin\n  if p_status not in ('new','contacted','registered','converted','rejected')\n     or p_reason is null or char_length(btrim(p_reason)) < 5 or char_length(p_reason) > 300\n     or p_idempotency_key is null or char_length(p_idempotency_key) < 8\n     or char_length(p_idempotency_key) > 120 then\n    raise exception 'INVALID_EARLY_ACCESS_STATUS_UPDATE' using errcode = '22023';\n  end if;\n  if not exists (\n    select 1 from public.users u\n    where u.id = p_actor_id and u.admin_status = 'active'\n  ) or not exists (\n    select 1\n    from public.admin_user_roles aur\n    join public.admin_roles ar on ar.code = aur.role_code and ar.is_active = true\n    where aur.user_id = p_actor_id\n      and aur.role_code in ('super_admin','support_admin','operations_admin')\n      and aur.is_active = true and aur.revoked_at is null\n  ) then\n    raise exception 'EARLY_ACCESS_ADMIN_ROLE_REQUIRED' using errcode = '42501';\n  end if;\n\n  select target_id into v_existing_target\n  from public.admin_audit_events\n  where action = 'early_access_lead_status_updated'\n    and idempotency_key = p_idempotency_key;\n  if found then\n    if v_existing_target <> p_lead_id::text then\n      raise exception 'EARLY_ACCESS_IDEMPOTENCY_CONFLICT' using errcode = '23505';\n    end if;\n    return jsonb_build_object('success', true, 'message', 'Đã xử lý thao tác trước đó.');\n  end if;\n\n  select status into v_old_status\n  from public.early_access_leads\n  where id = p_lead_id\n  for update;\n  if not found then\n    raise exception 'EARLY_ACCESS_LEAD_NOT_FOUND' using errcode = 'P0002';\n  end if;\n\n  update public.early_access_leads set status = p_status where id = p_lead_id;\n  insert into public.admin_audit_events (\n    actor_id, action, target_type, target_id, reason, idempotency_key, metadata\n  ) values (\n    p_actor_id, 'early_access_lead_status_updated', 'early_access_lead',\n    p_lead_id::text, btrim(p_reason), p_idempotency_key,\n    jsonb_build_object('from_status', v_old_status, 'to_status', p_status)\n  );\n  return jsonb_build_object('success', true, 'message', 'Đã cập nhật trạng thái hồ sơ.');\nend;\n$$","revoke all on function public.admin_update_early_access_lead_status(uuid,text,uuid,text,text) from public, anon, authenticated","grant execute on function public.admin_update_early_access_lead_status(uuid,text,uuid,text,text) to service_role","create or replace function public.purge_early_access_closed_leads()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, public, early_access_private\nas $$\ndeclare\n  v_candidate record;\n  v_deleted integer := 0;\n  v_row_count integer;\nbegin\n  for v_candidate in\n    select id, phone_hash\n    from public.early_access_leads\n    where created_at < now() - interval '12 months'\n      and status in ('registered','converted','rejected')\n  loop\n    if v_candidate.phone_hash is not null then\n      perform pg_advisory_xact_lock(hashtextextended(v_candidate.phone_hash, 0));\n      insert into early_access_private.promo_phone_suppressions(phone_hash)\n      values (v_candidate.phone_hash)\n      on conflict (phone_hash) do nothing;\n    end if;\n    delete from public.early_access_leads\n    where id = v_candidate.id\n      and created_at < now() - interval '12 months'\n      and status in ('registered','converted','rejected');\n    get diagnostics v_row_count = row_count;\n    v_deleted := v_deleted + v_row_count;\n  end loop;\n  return v_deleted;\nend;\n$$","revoke all on function public.purge_early_access_closed_leads() from public, anon, authenticated, service_role","do $cron$\ndeclare\n  v_job_id bigint;\nbegin\n  for v_job_id in\n    select jobid from cron.job where jobname = 'nanobio-purge-closed-early-access-leads'\n  loop\n    perform cron.unschedule(v_job_id);\n  end loop;\n  perform cron.schedule(\n    'nanobio-purge-closed-early-access-leads',\n    '17 3 * * *',\n    'select public.purge_early_access_closed_leads();'\n  );\nend\n$cron$","insert into public.admin_permissions(code, description)\nvalues\n  ('early_access.read', 'Xem hồ sơ đăng ký NanoBio Early Access.'),\n  ('early_access.update', 'Cập nhật trạng thái hồ sơ NanoBio Early Access.')\non conflict (code) do update set description = excluded.description, is_active = true","insert into public.admin_role_permissions(role_code, permission_code)\nvalues\n  ('super_admin', 'early_access.read'),\n  ('super_admin', 'early_access.update'),\n  ('support_admin', 'early_access.read'),\n  ('support_admin', 'early_access.update'),\n  ('operations_admin', 'early_access.read'),\n  ('operations_admin', 'early_access.update')\non conflict (role_code, permission_code) do nothing",commit}	nanobio_early_access_customer_admin
20261014090000	{begin,"create schema if not exists private","revoke all on schema private from public, anon, authenticated","grant usage on schema private to service_role","create unique index if not exists idx_users_phone_unique_not_null\n  on public.users(phone) where phone is not null","revoke update on public.users from anon, authenticated","grant update (\n  full_name,\n  avatar_url,\n  gender,\n  birth_year,\n  onboarding_status,\n  onboarding_completed_at,\n  last_login_at\n) on public.users to authenticated","-- Preserve the currently deployed snapshot behavior while stripping the\n-- client-controlled phone field before any older SECURITY DEFINER body runs.\ndo $$\nbegin\n  if to_regprocedure('public.sync_my_mobile_snapshot_before_member_phone_auth(jsonb)') is null then\n    if to_regprocedure('public.sync_my_mobile_snapshot(jsonb)') is null then\n      raise exception 'sync_my_mobile_snapshot(jsonb) must exist before applying member phone auth migration';\n    end if;\n    execute 'alter function public.sync_my_mobile_snapshot(jsonb) rename to sync_my_mobile_snapshot_before_member_phone_auth';\n  end if;\nend\n$$","revoke all on function public.sync_my_mobile_snapshot_before_member_phone_auth(jsonb)\nfrom public, anon, authenticated","create or replace function public.sync_my_mobile_snapshot(p_snapshot jsonb)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_user_id uuid := auth.uid();\n  v_safe_snapshot jsonb;\nbegin\n  if v_user_id is null then\n    raise exception using errcode = 'P0001', message = 'auth_required';\n  end if;\n  if coalesce(jsonb_typeof(p_snapshot), '') <> 'object'\n     or (p_snapshot ? 'user' and coalesce(jsonb_typeof(p_snapshot -> 'user'), '') <> 'object') then\n    raise exception using errcode = '22023', message = 'INVALID_SNAPSHOT';\n  end if;\n\n  v_safe_snapshot := jsonb_set(\n    p_snapshot,\n    '{user}',\n    coalesce(p_snapshot -> 'user', '{}'::jsonb) - 'phone',\n    true\n  );\n  return public.sync_my_mobile_snapshot_before_member_phone_auth(v_safe_snapshot);\nend;\n$$","revoke all on function public.sync_my_mobile_snapshot(jsonb)\nfrom public, anon","grant execute on function public.sync_my_mobile_snapshot(jsonb)\nto authenticated","do $$\nbegin\n  if has_column_privilege('anon', 'public.users', 'phone', 'UPDATE')\n     or has_column_privilege('authenticated', 'public.users', 'phone', 'UPDATE') then\n    raise exception 'MEMBER_PHONE_CLIENT_UPDATE_GRANT_INVALID';\n  end if;\n  if has_function_privilege(\n       'anon',\n       'public.sync_my_mobile_snapshot(jsonb)'::regprocedure,\n       'EXECUTE'\n     )\n     or not has_function_privilege(\n       'authenticated',\n       'public.sync_my_mobile_snapshot(jsonb)'::regprocedure,\n       'EXECUTE'\n     )\n     or has_function_privilege(\n       'authenticated',\n       'public.sync_my_mobile_snapshot_before_member_phone_auth(jsonb)'::regprocedure,\n       'EXECUTE'\n     ) then\n    raise exception 'MEMBER_PHONE_SNAPSHOT_RPC_GRANT_INVALID';\n  end if;\nend\n$$",commit}	member_phone_auth_security
20261014110000	{begin,"-- Member-facing phone/password credentials use a stable internal email alias\n-- because this project keeps Supabase Phone Auth disabled. The app never asks\n-- members for this alias; it normalizes the phone and derives the same value.\ncreate table if not exists private.member_phone_signup_rate_limits (\n  key_hash text not null,\n  bucket_start timestamptz not null,\n  request_count integer not null default 0,\n  primary key (key_hash, bucket_start)\n)","revoke all on table private.member_phone_signup_rate_limits\nfrom public, anon, authenticated, service_role","create or replace function public.consume_member_phone_signup_rate_limit(\n  p_ip_hash text\n)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = private, auth, pg_temp\nas $$\ndeclare\n  v_count integer;\n  v_bucket timestamptz := date_trunc('hour', now());\nbegin\n  if coalesce(auth.role(), '') <> 'service_role' then\n    raise exception 'service_role_required' using errcode = '42501';\n  end if;\n  if coalesce(p_ip_hash, '') !~ '^[0-9a-f]{64}$' then\n    return false;\n  end if;\n\n  delete from private.member_phone_signup_rate_limits\n  where bucket_start < now() - interval '30 days';\n  insert into private.member_phone_signup_rate_limits(\n    key_hash, bucket_start, request_count\n  ) values (\n    'signup:' || p_ip_hash, v_bucket, 1\n  )\n  on conflict (key_hash, bucket_start) do update\n    set request_count = private.member_phone_signup_rate_limits.request_count + 1\n  returning request_count into v_count;\n  return v_count <= 10;\nend;\n$$","revoke all on function public.consume_member_phone_signup_rate_limit(text)\nfrom public, anon, authenticated","grant execute on function public.consume_member_phone_signup_rate_limit(text)\nto service_role","do $$\nbegin\n  if to_regclass('public.idx_users_phone_unique_not_null') is null then\n    raise exception 'MEMBER_PHONE_UNIQUE_INDEX_MISSING';\n  end if;\n  if has_function_privilege(\n    'anon',\n    'public.consume_member_phone_signup_rate_limit(text)'::regprocedure,\n    'EXECUTE'\n  ) or has_function_privilege(\n    'authenticated',\n    'public.consume_member_phone_signup_rate_limit(text)'::regprocedure,\n    'EXECUTE'\n  ) or not has_function_privilege(\n    'service_role',\n    'public.consume_member_phone_signup_rate_limit(text)'::regprocedure,\n    'EXECUTE'\n  ) then\n    raise exception 'MEMBER_PHONE_SIGNUP_RATE_LIMIT_GRANTS_INVALID';\n  end if;\nend\n$$",commit}	member_phone_login_alias
20261014130000	{begin,"alter table public.wellness_reward_offers\n  add column if not exists reward_type text not null default 'voucher',\n  add column if not exists stock_count integer not null default 0","alter table public.wellness_reward_offers\n  drop constraint if exists wellness_reward_offers_reward_type_check","alter table public.wellness_reward_offers\n  add constraint wellness_reward_offers_reward_type_check\n    check (reward_type in ('voucher', 'physical'))","alter table public.wellness_reward_offers\n  drop constraint if exists wellness_reward_offers_stock_count_check","alter table public.wellness_reward_offers\n  add constraint wellness_reward_offers_stock_count_check\n    check (stock_count >= 0)","alter table public.wellness_reward_redemptions\n  alter column reward_code_id drop not null,\n  alter column voucher_expires_at drop not null,\n  add column if not exists reward_type_snapshot text not null default 'voucher',\n  add column if not exists received_at timestamptz,\n  add column if not exists received_by uuid references public.users(id) on delete set null","alter table public.wellness_reward_redemptions\n  drop constraint if exists wellness_reward_redemptions_status_check","alter table public.wellness_reward_redemptions\n  add constraint wellness_reward_redemptions_status_check\n    check (status in ('issued', 'cancelled', 'redeemed', 'received'))","alter table public.wellness_reward_redemptions\n  drop constraint if exists wellness_reward_redemptions_reward_type_snapshot_check","alter table public.wellness_reward_redemptions\n  add constraint wellness_reward_redemptions_reward_type_snapshot_check\n    check (reward_type_snapshot in ('voucher', 'physical'))","create index if not exists idx_wellness_reward_offers_type_stock\n  on public.wellness_reward_offers (reward_type, is_active, stock_count)","create index if not exists idx_wellness_reward_redemptions_physical_status\n  on public.wellness_reward_redemptions (user_id, reward_type_snapshot, status, created_at desc)","-- Keep legacy voucher screens scoped to voucher records.\ncreate or replace function public.list_my_reward_offers(\n  p_limit integer default 100\n)\nreturns table (\n  id uuid,\n  offer_id uuid,\n  offer_code text,\n  title text,\n  description text,\n  provider_name text,\n  cost_points integer,\n  available_codes integer,\n  eligible_plan_codes text[],\n  available_from timestamptz,\n  available_until timestamptz,\n  voucher_expires_at timestamptz,\n  is_active boolean\n)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_user_id uuid := auth.uid();\n  v_plan text;\nbegin\n  if v_user_id is null then\n    raise exception using errcode = 'P0001', message = 'auth_required';\n  end if;\n  v_plan := public.current_plan_for_user(v_user_id)::text;\n\n  return query\n  select\n    wro.id, wro.id, wro.offer_code, wro.title, wro.description,\n    wro.provider_name, wro.cost_points,\n    count(wrc.id) filter (\n      where wrc.status = 'available'\n        and coalesce(wrc.voucher_expires_at, wro.voucher_expires_at) > now()\n    )::integer,\n    wro.eligible_plan_codes, wro.available_from, wro.available_until,\n    wro.voucher_expires_at, wro.is_active\n  from public.wellness_reward_offers wro\n  left join public.wellness_reward_codes wrc on wrc.offer_id = wro.id\n  where public.wellness_rewards_feature_enabled()\n    and wro.reward_type = 'voucher'\n    and wro.is_active = true\n    and (wro.available_from is null or wro.available_from <= now())\n    and (wro.available_until is null or wro.available_until > now())\n    and v_plan = any(wro.eligible_plan_codes)\n  group by wro.id\n  order by wro.cost_points, wro.created_at desc\n  limit greatest(1, least(coalesce(p_limit, 100), 200));\nend;\n$$","create or replace function public.list_my_reward_redemptions(\n  p_limit integer default 100\n)\nreturns table (\n  id uuid,\n  redemption_id uuid,\n  offer_id uuid,\n  title text,\n  provider_name text,\n  points_spent integer,\n  status text,\n  voucher_expires_at timestamptz,\n  created_at timestamptz,\n  cancelled_at timestamptz\n)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_user_id uuid := auth.uid();\nbegin\n  if v_user_id is null then\n    raise exception using errcode = 'P0001', message = 'auth_required';\n  end if;\n  return query\n  select\n    wrr.id, wrr.id, wrr.offer_id, wrr.offer_title_snapshot,\n    wrr.provider_name_snapshot, wrr.points_spent, wrr.status,\n    wrr.voucher_expires_at, wrr.created_at, wrr.cancelled_at\n  from public.wellness_reward_redemptions wrr\n  where wrr.user_id = v_user_id and wrr.reward_type_snapshot = 'voucher'\n  order by wrr.created_at desc, wrr.id desc\n  limit greatest(1, least(coalesce(p_limit, 100), 200));\nend;\n$$","create or replace function public.guard_wellness_reward_redemption_type()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_offer_type text;\nbegin\n  select reward_type into v_offer_type\n  from public.wellness_reward_offers\n  where id = new.offer_id;\n\n  if v_offer_type is null or v_offer_type <> new.reward_type_snapshot then\n    raise exception using errcode = 'P0001', message = 'reward_type_mismatch';\n  end if;\n\n  if v_offer_type = 'voucher' and new.reward_code_id is null then\n    raise exception using errcode = 'P0001', message = 'reward_code_required';\n  end if;\n\n  if v_offer_type = 'physical' and new.reward_code_id is not null then\n    raise exception using errcode = 'P0001', message = 'reward_code_not_allowed';\n  end if;\n\n  return new;\nend;\n$$","drop trigger if exists trg_wellness_reward_redemption_type\n  on public.wellness_reward_redemptions","create trigger trg_wellness_reward_redemption_type\n  before insert or update of offer_id, reward_code_id, reward_type_snapshot\n  on public.wellness_reward_redemptions\n  for each row execute function public.guard_wellness_reward_redemption_type()","create or replace function public.guard_wellness_reward_code_offer_type()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  if not exists (\n    select 1\n    from public.wellness_reward_offers wro\n    where wro.id = new.offer_id\n      and wro.reward_type = 'voucher'\n  ) then\n    raise exception using errcode = 'P0001', message = 'reward_type_mismatch';\n  end if;\n  return new;\nend;\n$$","drop trigger if exists trg_wellness_reward_code_offer_type\n  on public.wellness_reward_codes","create trigger trg_wellness_reward_code_offer_type\n  before insert or update of offer_id on public.wellness_reward_codes\n  for each row execute function public.guard_wellness_reward_code_offer_type()","create or replace function public.list_my_reward_catalog_v2(\n  p_limit integer default 100\n)\nreturns table (\n  id uuid,\n  offer_id uuid,\n  offer_code text,\n  reward_type text,\n  title text,\n  description text,\n  provider_name text,\n  cost_points integer,\n  available_codes integer,\n  stock_count integer,\n  eligible_plan_codes text[],\n  available_from timestamptz,\n  available_until timestamptz,\n  voucher_expires_at timestamptz,\n  is_active boolean\n)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_user_id uuid := auth.uid();\n  v_plan text;\nbegin\n  if v_user_id is null then\n    raise exception using errcode = 'P0001', message = 'auth_required';\n  end if;\n\n  v_plan := public.current_plan_for_user(v_user_id)::text;\n\n  return query\n  select\n    wro.id,\n    wro.id,\n    wro.offer_code,\n    wro.reward_type,\n    wro.title,\n    wro.description,\n    wro.provider_name,\n    wro.cost_points,\n    count(wrc.id) filter (\n      where wrc.status = 'available'\n        and coalesce(wrc.voucher_expires_at, wro.voucher_expires_at) > now()\n    )::integer,\n    wro.stock_count,\n    wro.eligible_plan_codes,\n    wro.available_from,\n    wro.available_until,\n    wro.voucher_expires_at,\n    wro.is_active\n  from public.wellness_reward_offers wro\n  left join public.wellness_reward_codes wrc\n    on wrc.offer_id = wro.id\n  where public.wellness_rewards_feature_enabled()\n    and wro.is_active = true\n    and (wro.available_from is null or wro.available_from <= now())\n    and (wro.available_until is null or wro.available_until > now())\n    and v_plan = any(wro.eligible_plan_codes)\n  group by wro.id\n  order by wro.cost_points, wro.created_at desc\n  limit greatest(1, least(coalesce(p_limit, 100), 200));\nend;\n$$","create or replace function public.list_my_reward_redemptions_v2(\n  p_limit integer default 100\n)\nreturns table (\n  id uuid,\n  redemption_id uuid,\n  offer_id uuid,\n  reward_type text,\n  title text,\n  provider_name text,\n  points_spent integer,\n  status text,\n  voucher_expires_at timestamptz,\n  created_at timestamptz,\n  cancelled_at timestamptz,\n  received_at timestamptz\n)\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_user_id uuid := auth.uid();\nbegin\n  if v_user_id is null then\n    raise exception using errcode = 'P0001', message = 'auth_required';\n  end if;\n\n  return query\n  select\n    wrr.id,\n    wrr.id,\n    wrr.offer_id,\n    wrr.reward_type_snapshot,\n    wrr.offer_title_snapshot,\n    wrr.provider_name_snapshot,\n    wrr.points_spent,\n    wrr.status,\n    wrr.voucher_expires_at,\n    wrr.created_at,\n    wrr.cancelled_at,\n    wrr.received_at\n  from public.wellness_reward_redemptions wrr\n  where wrr.user_id = v_user_id\n  order by wrr.created_at desc, wrr.id desc\n  limit greatest(1, least(coalesce(p_limit, 100), 200));\nend;\n$$","create or replace function public.redeem_my_reward_v2(\n  p_offer_id uuid,\n  p_idempotency_key text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_user_id uuid := auth.uid();\n  v_plan text;\n  v_offer public.wellness_reward_offers%rowtype;\n  v_wallet public.wellness_reward_wallets%rowtype;\n  v_existing public.wellness_reward_redemptions%rowtype;\n  v_response jsonb;\n  v_ledger_id uuid;\n  v_redemption_id uuid := gen_random_uuid();\n  v_subject_id uuid;\n  v_allocation record;\n  v_needed integer;\n  v_take integer;\nbegin\n  if v_user_id is null then\n    raise exception using errcode = 'P0001', message = 'auth_required';\n  end if;\n  if p_offer_id is null then\n    raise exception using errcode = 'P0001', message = 'offer_required';\n  end if;\n  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then\n    raise exception using errcode = 'P0001', message = 'idempotency_key_required';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(\n    'wellness:redeem:v2:' || v_user_id::text || ':' || btrim(p_idempotency_key),\n    0\n  ));\n\n  select * into v_existing\n  from public.wellness_reward_redemptions wrr\n  where wrr.user_id = v_user_id\n    and wrr.idempotency_key = btrim(p_idempotency_key);\n\n  if v_existing.id is not null then\n    if v_existing.offer_id <> p_offer_id then\n      raise exception using errcode = 'P0001', message = 'idempotency_conflict';\n    end if;\n    if v_existing.reward_type_snapshot = 'voucher' then\n      v_response := public.redeem_my_reward_offer(p_offer_id, p_idempotency_key);\n      select id into v_ledger_id\n      from public.wellness_point_ledgers\n      where redemption_id = v_existing.id\n      order by created_at desc\n      limit 1;\n      return v_response || jsonb_build_object('point_ledger_id', v_ledger_id);\n    end if;\n    select available_points into v_wallet.available_points\n    from public.wellness_reward_wallets\n    where user_id = v_user_id;\n    select id into v_ledger_id\n    from public.wellness_point_ledgers\n    where redemption_id = v_existing.id\n    order by created_at desc\n    limit 1;\n    return jsonb_build_object(\n      'success', true,\n      'id', v_existing.id,\n      'redemption_id', v_existing.id,\n      'offer_id', v_existing.offer_id,\n      'reward_type', 'physical',\n      'title', v_existing.offer_title_snapshot,\n      'provider_name', v_existing.provider_name_snapshot,\n      'points_spent', v_existing.points_spent,\n      'status', v_existing.status,\n      'point_ledger_id', v_ledger_id,\n      'available_points', coalesce(v_wallet.available_points, 0),\n      'created_at', v_existing.created_at,\n      'received_at', v_existing.received_at,\n      'idempotent_replay', true\n    );\n  end if;\n\n  if not public.wellness_rewards_feature_enabled() then\n    raise exception using errcode = 'P0001', message = 'wellness_rewards_disabled';\n  end if;\n\n  select * into v_offer\n  from public.wellness_reward_offers wro\n  where wro.id = p_offer_id\n  for update;\n\n  if v_offer.id is null\n     or not v_offer.is_active\n     or (v_offer.available_from is not null and v_offer.available_from > now())\n     or (v_offer.available_until is not null and v_offer.available_until <= now()) then\n    raise exception using errcode = 'P0001', message = 'offer_unavailable';\n  end if;\n\n  if v_offer.reward_type = 'voucher' then\n    v_response := public.redeem_my_reward_offer(p_offer_id, p_idempotency_key);\n    select id into v_ledger_id\n    from public.wellness_point_ledgers\n    where redemption_id = (v_response ->> 'redemption_id')::uuid\n    order by created_at desc\n    limit 1;\n    return v_response || jsonb_build_object('point_ledger_id', v_ledger_id);\n  end if;\n\n  if v_offer.stock_count <= 0 then\n    raise exception using errcode = 'P0001', message = 'offer_out_of_stock';\n  end if;\n\n  v_plan := public.current_plan_for_user(v_user_id)::text;\n  if not (v_plan = any(v_offer.eligible_plan_codes)) then\n    raise exception using errcode = 'P0001', message = 'offer_ineligible';\n  end if;\n\n  perform public.refresh_wellness_reward_wallet(v_user_id);\n  select * into v_wallet\n  from public.wellness_reward_wallets\n  where user_id = v_user_id\n  for update;\n\n  if v_wallet.available_points < v_offer.cost_points then\n    raise exception using errcode = 'P0001', message = 'insufficient_points';\n  end if;\n\n  select hs.id into v_subject_id\n  from public.health_subjects hs\n  where hs.owner_user_id = v_user_id\n    and hs.subject_type = 'self'\n    and hs.is_active = true\n  limit 1;\n  if v_subject_id is null then\n    raise exception using errcode = 'P0001', message = 'health_subject_required';\n  end if;\n\n  update public.wellness_reward_offers\n  set stock_count = stock_count - 1, updated_at = now()\n  where id = v_offer.id and stock_count > 0;\n  if not found then\n    raise exception using errcode = 'P0001', message = 'offer_out_of_stock';\n  end if;\n\n  insert into public.wellness_reward_redemptions (\n    id, user_id, offer_id, reward_code_id, reward_type_snapshot,\n    offer_title_snapshot, provider_name_snapshot, points_spent, status,\n    voucher_expires_at, idempotency_key\n  ) values (\n    v_redemption_id, v_user_id, v_offer.id, null, 'physical',\n    v_offer.title, v_offer.provider_name, v_offer.cost_points, 'redeemed',\n    null, btrim(p_idempotency_key)\n  );\n\n  v_needed := v_offer.cost_points;\n  for v_allocation in\n    select wpa.id, wpa.remaining_points\n    from public.wellness_point_allocations wpa\n    where wpa.user_id = v_user_id\n      and wpa.status = 'available'\n      and wpa.remaining_points > 0\n      and wpa.expires_at > now()\n    order by wpa.expires_at, wpa.created_at, wpa.id\n    for update\n  loop\n    exit when v_needed = 0;\n    v_take := least(v_needed, v_allocation.remaining_points);\n    insert into public.wellness_redemption_allocation_usages (\n      redemption_id, allocation_id, points_used\n    ) values (v_redemption_id, v_allocation.id, v_take);\n    update public.wellness_point_allocations\n    set remaining_points = remaining_points - v_take,\n        status = case when remaining_points - v_take = 0 then 'spent' else status end,\n        updated_at = now()\n    where id = v_allocation.id;\n    v_needed := v_needed - v_take;\n  end loop;\n\n  if v_needed <> 0 then\n    raise exception using errcode = 'P0001', message = 'wallet_allocation_mismatch';\n  end if;\n\n  insert into public.wellness_point_ledgers (\n    user_id, subject_id, source_type, source_id, schedule_date, points_delta,\n    program_code, idempotency_key, event_type, status, title, is_redeemable,\n    redemption_id, metadata\n  ) values (\n    v_user_id, v_subject_id, 'reward_redemption', v_redemption_id,\n    (now() at time zone 'Asia/Ho_Chi_Minh')::date, -v_offer.cost_points,\n    'wellness_rewards_v2', 'reward_redemption:' || v_redemption_id::text,\n    'redemption', 'redeemed', 'Đổi quà: ' || v_offer.title, true,\n    v_redemption_id, jsonb_build_object('offer_id', v_offer.id, 'reward_type', 'physical')\n  ) returning id into v_ledger_id;\n\n  update public.wellness_reward_wallets\n  set available_points = available_points - v_offer.cost_points,\n      lifetime_spent_points = lifetime_spent_points + v_offer.cost_points,\n      lock_version = lock_version + 1,\n      updated_at = now()\n  where user_id = v_user_id\n  returning * into v_wallet;\n\n  return jsonb_build_object(\n    'success', true,\n    'id', v_redemption_id,\n    'redemption_id', v_redemption_id,\n    'offer_id', v_offer.id,\n    'reward_type', 'physical',\n    'title', v_offer.title,\n    'provider_name', v_offer.provider_name,\n    'points_spent', v_offer.cost_points,\n    'status', 'redeemed',\n    'point_ledger_id', v_ledger_id,\n    'available_points', v_wallet.available_points,\n    'created_at', now(),\n    'idempotent_replay', false\n  );\nend;\n$$","create or replace function public.admin_upsert_reward_offer_v2(\n  p_offer_id uuid,\n  p_reward_type text,\n  p_title text,\n  p_description text,\n  p_provider_name text,\n  p_cost_points integer,\n  p_stock_count integer,\n  p_eligible_plan_codes text[],\n  p_available_from timestamptz,\n  p_available_until timestamptz,\n  p_voucher_expires_at timestamptz,\n  p_is_active boolean,\n  p_reason text,\n  p_idempotency_key text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_offer public.wellness_reward_offers%rowtype;\n  v_existing_audit public.admin_audit_events%rowtype;\n  v_new_id uuid := coalesce(p_offer_id, gen_random_uuid());\nbegin\n  perform public.admin_assert_permission('wellness_rewards.write');\n  if coalesce(p_reward_type, '') not in ('voucher', 'physical') then\n    raise exception using errcode = 'P0001', message = 'reward_type_invalid';\n  end if;\n  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then\n    raise exception using errcode = 'P0001', message = 'idempotency_key_required';\n  end if;\n  if nullif(btrim(coalesce(p_reason, '')), '') is null then\n    raise exception using errcode = 'P0001', message = 'admin_reason_required';\n  end if;\n\n  if p_offer_id is not null then\n    select * into v_offer from public.wellness_reward_offers\n    where id = p_offer_id for update;\n    if v_offer.id is null then\n      raise exception using errcode = 'P0001', message = 'offer_not_found';\n    end if;\n    if v_offer.reward_type <> p_reward_type then\n      raise exception using errcode = 'P0001', message = 'reward_type_immutable';\n    end if;\n  end if;\n\n  if p_reward_type = 'voucher' then\n    return public.admin_upsert_reward_offer(\n      p_offer_id, p_title, p_description, p_provider_name, p_cost_points,\n      p_eligible_plan_codes, p_available_from, p_available_until,\n      p_voucher_expires_at, p_is_active, p_reason, p_idempotency_key\n    );\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(\n    'wellness:admin:upsert:physical:' || btrim(p_idempotency_key), 0\n  ));\n  select * into v_existing_audit\n  from public.admin_audit_events aae\n  where aae.action = 'admin_upsert_physical_reward_offer'\n    and aae.idempotency_key = btrim(p_idempotency_key);\n  if v_existing_audit.id is not null then\n    if p_offer_id is not null and v_existing_audit.target_id <> p_offer_id::text then\n      raise exception using errcode = 'P0001', message = 'idempotency_conflict';\n    end if;\n    return jsonb_build_object(\n      'success', true,\n      'message', 'Yêu cầu đã được xử lý trước đó.',\n      'offer_id', v_existing_audit.target_id,\n      'idempotent_replay', true\n    );\n  end if;\n\n  if not public.reward_text_is_vietnamese(p_title)\n     or not public.reward_text_is_vietnamese(p_description) then\n    raise exception using errcode = 'P0001', message = 'invalid_vietnamese_copy';\n  end if;\n  if nullif(btrim(coalesce(p_provider_name, '')), '') is null then\n    raise exception using errcode = 'P0001', message = 'provider_name_required';\n  end if;\n  if p_cost_points is null or p_cost_points <= 0 then\n    raise exception using errcode = 'P0001', message = 'reward_cost_invalid';\n  end if;\n  if p_stock_count is null or p_stock_count < 0 then\n    raise exception using errcode = 'P0001', message = 'reward_stock_invalid';\n  end if;\n  if p_eligible_plan_codes is null\n     or cardinality(p_eligible_plan_codes) = 0\n     or not (p_eligible_plan_codes <@ array['free', 'plus', 'family_plus']::text[]) then\n    raise exception using errcode = 'P0001', message = 'eligible_plans_invalid';\n  end if;\n  if p_available_from is not null and p_available_until is not null\n     and p_available_until <= p_available_from then\n    raise exception using errcode = 'P0001', message = 'offer_window_invalid';\n  end if;\n\n  insert into public.wellness_reward_offers (\n    id, offer_code, reward_type, stock_count, title, description, provider_name,\n    cost_points, eligible_plan_codes, available_from, available_until,\n    voucher_expires_at, is_active, created_by, updated_by\n  ) values (\n    v_new_id, 'reward_' || replace(v_new_id::text, '-', ''), 'physical', p_stock_count,\n    btrim(p_title), btrim(p_description), btrim(p_provider_name), p_cost_points,\n    array(select distinct lower(btrim(x)) from unnest(p_eligible_plan_codes) x order by 1),\n    p_available_from, p_available_until, null, coalesce(p_is_active, false), auth.uid(), auth.uid()\n  )\n  on conflict (id) do update set\n    title = excluded.title,\n    description = excluded.description,\n    provider_name = excluded.provider_name,\n    cost_points = excluded.cost_points,\n    stock_count = excluded.stock_count,\n    eligible_plan_codes = excluded.eligible_plan_codes,\n    available_from = excluded.available_from,\n    available_until = excluded.available_until,\n    is_active = excluded.is_active,\n    updated_by = auth.uid(),\n    updated_at = now()\n  returning * into v_offer;\n\n  perform public.admin_write_audit(\n    'admin_upsert_physical_reward_offer', 'wellness_reward_offer', v_offer.id::text,\n    p_reason, p_idempotency_key,\n    jsonb_build_object(\n      'reward_type', v_offer.reward_type,\n      'is_active', v_offer.is_active,\n      'cost_points', v_offer.cost_points,\n      'stock_count', v_offer.stock_count,\n      'eligible_plan_codes', v_offer.eligible_plan_codes\n    )\n  );\n\n  return jsonb_build_object(\n    'success', true,\n    'message', 'Đã lưu quà tặng.',\n    'offer_id', v_offer.id,\n    'accepted_count', 1,\n    'idempotent_replay', false\n  );\nend;\n$$","create or replace function public.admin_list_wellness_rewards_v2(\n  p_query text default '',\n  p_limit integer default 100\n)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_offers jsonb;\n  v_redemptions jsonb;\n  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 200));\nbegin\n  perform public.admin_assert_permission('wellness_rewards.read');\n\n  select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) into v_offers\n  from (\n    select\n      'offer'::text as item_type,\n      wro.id,\n      wro.id as offer_id,\n      wro.reward_type,\n      wro.title,\n      wro.description,\n      wro.provider_name,\n      wro.cost_points,\n      wro.stock_count,\n      wro.eligible_plan_codes,\n      wro.available_from,\n      wro.available_until,\n      wro.voucher_expires_at,\n      wro.is_active,\n      (select count(*)::integer from public.wellness_reward_codes wrc\n        where wrc.offer_id = wro.id and wrc.status = 'available'\n          and coalesce(wrc.voucher_expires_at, wro.voucher_expires_at) > now()) as available_codes,\n      (select count(*)::integer from public.wellness_reward_codes wrc\n        where wrc.offer_id = wro.id and wrc.status = 'issued') as issued_codes,\n      wro.created_at,\n      wro.updated_at as sort_at\n    from public.wellness_reward_offers wro\n    where coalesce(btrim(p_query), '') = ''\n       or wro.title ilike '%' || btrim(p_query) || '%'\n       or wro.provider_name ilike '%' || btrim(p_query) || '%'\n       or wro.offer_code ilike '%' || btrim(p_query) || '%'\n    order by wro.updated_at desc, wro.id desc\n    limit v_limit\n  ) q;\n\n  select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) into v_redemptions\n  from (\n    select\n      'redemption'::text as item_type,\n      wrr.id,\n      wrr.id as redemption_id,\n      wrr.offer_id,\n      wrr.reward_type_snapshot as reward_type,\n      wrr.offer_title_snapshot as title,\n      wrr.provider_name_snapshot as provider_name,\n      wrr.points_spent,\n      wrr.status,\n      wrr.voucher_expires_at,\n      wrr.received_at,\n      wrr.received_by,\n      wrr.user_id,\n      coalesce(nullif(u.full_name, ''),\n        case when position('@' in coalesce(u.email, '')) > 1\n          then left(u.email, 1) || '***' || substring(u.email from position('@' in u.email))\n          else 'Tài khoản NanoBio' end) as user_label,\n      case when wrr.reward_type_snapshot = 'voucher' then '••••••'::text else null end as masked_code,\n      wrr.created_at,\n      wrr.cancelled_at,\n      wrr.updated_at as sort_at\n    from public.wellness_reward_redemptions wrr\n    join public.users u on u.id = wrr.user_id\n    where coalesce(btrim(p_query), '') = ''\n       or wrr.offer_title_snapshot ilike '%' || btrim(p_query) || '%'\n       or wrr.provider_name_snapshot ilike '%' || btrim(p_query) || '%'\n       or coalesce(u.full_name, '') ilike '%' || btrim(p_query) || '%'\n       or coalesce(u.email, '') ilike '%' || btrim(p_query) || '%'\n    order by wrr.updated_at desc, wrr.id desc\n    limit v_limit\n  ) q;\n\n  return jsonb_build_object('offers', v_offers, 'redemptions', v_redemptions);\nend;\n$$","create or replace function public.admin_mark_reward_redemption_received(\n  p_redemption_id uuid,\n  p_reason text,\n  p_idempotency_key text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_redemption public.wellness_reward_redemptions%rowtype;\n  v_existing_audit public.admin_audit_events%rowtype;\nbegin\n  perform public.admin_assert_permission('wellness_rewards.write');\n  if p_redemption_id is null then\n    raise exception using errcode = 'P0001', message = 'redemption_required';\n  end if;\n  if nullif(btrim(coalesce(p_reason, '')), '') is null then\n    raise exception using errcode = 'P0001', message = 'admin_reason_required';\n  end if;\n  if nullif(btrim(coalesce(p_idempotency_key, '')), '') is null then\n    raise exception using errcode = 'P0001', message = 'idempotency_key_required';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(\n    'wellness:admin:received:' || btrim(p_idempotency_key), 0\n  ));\n  select * into v_existing_audit\n  from public.admin_audit_events aae\n  where aae.action = 'admin_mark_reward_redemption_received'\n    and aae.idempotency_key = btrim(p_idempotency_key);\n  if v_existing_audit.id is not null then\n    if v_existing_audit.target_id <> p_redemption_id::text then\n      raise exception using errcode = 'P0001', message = 'idempotency_conflict';\n    end if;\n    return jsonb_build_object('success', true, 'status', 'received', 'idempotent_replay', true);\n  end if;\n\n  select * into v_redemption\n  from public.wellness_reward_redemptions\n  where id = p_redemption_id\n  for update;\n  if v_redemption.id is null then\n    raise exception using errcode = 'P0001', message = 'redemption_not_found';\n  end if;\n  if v_redemption.reward_type_snapshot <> 'physical' then\n    raise exception using errcode = 'P0001', message = 'physical_reward_required';\n  end if;\n  if v_redemption.status = 'received' then\n    return jsonb_build_object(\n      'success', true, 'status', 'received', 'received_at', v_redemption.received_at,\n      'idempotent_replay', true\n    );\n  end if;\n  if v_redemption.status <> 'redeemed' then\n    raise exception using errcode = 'P0001', message = 'reward_cannot_be_received';\n  end if;\n\n  update public.wellness_reward_redemptions\n  set status = 'received', received_at = now(), received_by = auth.uid(), updated_at = now()\n  where id = v_redemption.id\n  returning * into v_redemption;\n\n  perform public.admin_write_audit(\n    'admin_mark_reward_redemption_received', 'wellness_reward_redemption',\n    v_redemption.id::text, p_reason, p_idempotency_key,\n    jsonb_build_object(\n      'reward_type', v_redemption.reward_type_snapshot,\n      'previous_status', 'redeemed',\n      'status', 'received',\n      'received_at', v_redemption.received_at\n    )\n  );\n\n  return jsonb_build_object(\n    'success', true, 'redemption_id', v_redemption.id, 'status', 'received',\n    'received_at', v_redemption.received_at, 'received_by', v_redemption.received_by,\n    'idempotent_replay', false\n  );\nend;\n$$","revoke all on function public.guard_wellness_reward_redemption_type() from public, anon, authenticated","revoke all on function public.guard_wellness_reward_code_offer_type() from public, anon, authenticated","revoke all on function public.list_my_reward_catalog_v2(integer) from public, anon","revoke all on function public.list_my_reward_redemptions_v2(integer) from public, anon"